INSERT INTO `knowledge_nodes` VALUES (1,NULL,1,1,'语文[初中]',NULL,1,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(2,NULL,2,1,'数学[初中]',NULL,2,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(3,NULL,3,1,'英语[初中]',NULL,3,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(5,NULL,5,1,'网络应用基础',NULL,5,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(6,NULL,6,1,'办公应用基础',NULL,6,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(7,NULL,17,1,'Access',NULL,7,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(8,NULL,20,1,'语文[职高]',NULL,0,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(9,NULL,21,1,'语文[普高]',NULL,0,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(10,NULL,22,1,'数学[职高]',NULL,0,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(11,NULL,23,1,'数学[普高]',NULL,0,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(12,NULL,24,1,'英语[职高]',NULL,0,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(13,NULL,25,1,'英语[普高]',NULL,0,1,'2026-05-21 10:44:05','2026-05-21 10:44:05'),(439,NULL,4,1,'信息技术应用基础',NULL,4,1,'2026-05-22 06:58:17','2026-05-22 06:58:17'),(631,439,4,2,'单元2使用计算机',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(632,631,4,3,'任务2连接计算机及常用设备',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(633,632,4,4,'DisplayPort接口与雷电接口','# DisplayPort接口与雷电接口\n\n【一句话定义】\nDisplayPort（DP）是由VESA制定的高性能数字显示接口标准，已成为PC显卡的主流显示输出接口；雷电（Thunderbolt）接口是英特尔主导的多功能高速接口，融合数据传输、视频输出和供电于一体， Type-C物理形态使其通用性极强。\n\n【具体说明】\nDisplayPort（DP）接口：①版本迭代——DP 1.4支持8K@60Hz或4K@120Hz，DP 2.0带宽进一步提升支持16K显示；②免授权费——不像HDMI需交专利费，显示器厂商更倾向采用；③多显示器串联——DP支持MST（多流传输），一根线可串联多台显示器（菊花链），适合多屏办公；④与Mini DP——早期MacBook使用的迷你版本，功能与标准DP一致，尺寸更小。DP接口有卡扣设计，插拔时需按压释放。\n\n雷电（Thunderbolt）接口：①版本发展——雷电3和雷电4均采用Type-C物理接口，雷电3带宽40Gbps，雷电4在雷电3基础上增强了最低性能要求和安全性；②一线通——一根雷电Type-C线同时实现：传输数据（接高速硬盘）、输出视频（接4K/8K显示器）、给笔记本充电（最高100W供电）、扩展坞连接（一个接口扩展出USB/网卡/读卡器/显示器等多个接口）；③与USB4的关系——雷电3的技术已贡献给USB4标准，所以支持USB4的Type-C接口通常也兼容雷电设备。\n\nDP与HDMI的选择：游戏和高刷显示器优先选DP（支持G-Sync/FreeSync更稳定）；连接电视和影音设备优先选HDMI（ARC音频回传更成熟）。雷电接口的优势：笔记本用户只需一根线连接扩展坞，就能同时接显示器、键盘鼠标、网线并给笔记本充电，桌面整洁且插拔方便。\n\n【常见错误】\n1. 雷电接口就是Type-C——Type-C是物理接口形状，雷电是传输协议；所有雷电接口都是Type-C形状，但Type-C接口不一定支持雷电（可能只是普通USB）。\n2. DP和Mini DP功能不同——两者传输能力完全相同，只是尺寸差异，可用转接头互转。\n3. 雷电4比雷电3带宽大——雷电3和雷电4带宽都是40Gbps，雷电4改进的是最低保障性能和安全性，而非峰值带宽。\n\n【出题方向】\n常考选择题\"雷电接口采用的物理形态是\"（Type-C）。填空题\"DisplayPort接口支持____功能，可以用一根线串联多台显示器\"（MST/多流传输/菊花链）。判断题\"所有Type-C接口都支持雷电协议\"（错，Type-C是物理形状，雷电是传输协议，需单独认证）。简答题\"简述雷电接口相比普通USB接口的优势\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(634,632,4,4,'OLED与Mini LED显示技术','# OLED与Mini LED显示技术\n\n【一句话定义】\nOLED（有机发光二极管）是每个像素自发光的新型显示技术，对比度极高、可弯曲；Mini LED是LCD的升级方案，将传统背光源替换为数千颗微小LED灯珠，实现更精细的局部调光和更高亮度。\n\n【具体说明】\nOLED技术原理：传统LCD需要背光层照亮液晶层，显示黑色时背光仍亮所以黑得不够纯粹。OLED每个像素点自己就是光源，需要亮就亮、需要黑就完全熄灭，因此对比度接近无限大（理论上∞:1），黑色表现纯粹。OLED面板还可弯曲，用于曲面屏和折叠屏手机。\n\nOLED的优势与不足：优势——对比度极高、色彩鲜艳、响应速度极快（游戏无拖影）、可做超薄/曲面/柔性屏幕。不足——有机材料会老化，长期显示静态画面（如电视台标、任务栏）可能导致\"烧屏\"（残影）；大尺寸的OLED显示器和电视价格较高。\n\nMini LED技术原理：传统LCD只有一整块背光板，全开/全关无法精准控制。Mini LED将背光板分成数百到数千个独立控制的微小区域（如2304分区），显示星空时暗的区域背光调低甚至关闭，亮的星星区域背光增强，大幅提升对比度和HDR效果。\n\nMini LED的优势与不足：优势——对比度大幅提升接近OLED水平、亮度更高（适合HDR内容）、不存在烧屏问题、大尺寸成本比OLED低。不足——仍有液晶层的物理限制，对比度和可视角度不如OLED极致；分区数量不足时明亮物体周围可能出现光晕。\n\n选购建议：手机和小尺寸高端显示器选OLED（色彩对比度好）；大尺寸电视和追求性价比选Mini LED（亮度高无烧屏）；专业设计修图选OLED（色彩精准）；长时间办公选Mini LED或带防烧屏技术的OLED。\n\n【常见错误】\n1. Mini LED和OLED是竞争关系——两者各有优劣，OLED追求极致画质，Mini LED追求均衡表现，不是简单的替代关系。\n2. Mini LED就是LED显示器——Mini LED本质是LCD的背光升级方案，仍属于LCD技术范畴。\n3. OLED一定比Mini LED好——取决于使用场景，长时间静态显示时Mini LED更耐用，高亮度HDR场景Mini LED表现更好。\n\n【出题方向】\n常考选择题\"OLED显示器的最大优势是\"（对比度极高/自发光/黑色纯粹）。填空题\"Mini LED技术是对____显示器的背光升级方案\"（LCD）。判断题\"OLED显示器长时间显示固定画面可能出现烧屏现象\"（对）。简答题\"比较OLED和Mini LED两种显示技术的优缺点\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(635,632,4,4,'Type-C接口','# Type-C接口\n\n【一句话定义】\nType-C是一种正反两面都能插入的新型USB接口，支持数据传输、充电和视频输出，正逐渐成为各类电子设备的标准接口。\n\n【具体例子】\nType-C最大的特点是\"盲插\"——不分正反面，像苹果Lightning接口一样，黑暗中也能插对。现在的安卓手机、新笔记本电脑、iPad Pro都用Type-C。一条Type-C线可以做三件事：给手机充电（最高支持100W快充）、传数据（可以是USB 2.0/3.0/3.1速度）、接显示器（支持DisplayPort视频输出）。但要注意：不是所有Type-C口都支持全部功能，有些手机Type-C口只支持充电不支持视频输出。\n\n【常见错误】\n1. Type-C和USB 3.0搞混——Type-C是接口形状，USB 3.0是传输速度标准，两者不是一回事。\n2. 以为所有Type-C都能快充——还要看充电器、线材、设备是否都支持快充协议。\n3. Type-C能直接接VGA显示器——Type-C输出的是数字信号，接VGA模拟显示器需要转换器。\n\n【出题方向】\n常考选择题\"Type-C接口的主要特点是\"（正反两面都能插）。也常考填空题\"Type-C接口可以传输____、____和____\"（数据、充电、视频）。判断题\"所有Type-C接口都支持相同的速度和功能\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(636,632,4,4,'USB接口','# USB接口\n\n【一句话定义】\nUSB（通用串行总线）是计算机与外部设备之间最常用的数据传输接口标准，支持即插即用和热插拔，常见版本有USB 2.0、USB 3.0（3.1 Gen1）和USB 3.1（3.2 Gen2）。\n\n【具体例子】\nUSB就像万能的翻译官——U盘、鼠标、键盘、手机充电线都能插。USB 2.0理论速度480Mbps（实际约30MB/s），接口是白色或黑色。USB 3.0理论速度5Gbps（实际约500MB/s），接口是蓝色。USB 3.1理论速度10Gbps。从外观区分：看接口颜色，蓝色=3.0，红色/青色=3.1。Type-A是常见的扁平大头（插电脑），Type-B是方形头（插打印机），Type-C是双面都能插的小圆头（新手机用）。\n\n【常见错误】\n1. USB 2.0和3.0速度搞混——3.0是蓝色的，比2.0（白色/黑色）快10倍。\n2. 以为USB 3.0设备插2.0口也能满速——向下兼容但速度降到2.0水平。\n3. Type-C和USB 3.0搞混——Type-C是接口形状，USB 3.0是速度标准，Type-C接口可以是USB 2.0也可以是3.0速度。\n\n【出题方向】\n常考选择题\"USB 3.0接口的颜色通常是\"（蓝色）。也常考填空题\"USB的中文含义是____\"（通用串行总线）。判断题\"USB接口支持热插拔\"（对）。填空题\"USB 3.0的理论传输速度是____\"（5Gbps）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(637,632,4,4,'VGA与HDMI接口','# VGA与HDMI接口\n\n【一句话定义】\nVGA是模拟视频接口（蓝色梯形15针），用于连接显示器；HDMI是高清数字音视频接口，能同时传输高清视频和多声道音频。\n\n【具体例子】\nVGA是老式接口——蓝色梯形，15根针，只传模拟视频信号（没有声音），学校老投影仪常用。HDMI是新式接口——扁梯形，19针，同时传高清视频和声音，一条线搞定。现在主流显示器和电视都有HDMI接口。VGA接1080p显示器画面会模糊（模拟信号有损耗），HDMI接4K电视画面清晰锐利（数字信号无损传输）。转接头：HDMI转VGA需要带芯片的转换器（数字转模拟），VGA转HDMI也需要转换器。\n\n【常见错误】\n1. VGA和HDMI分不清楚——VGA是蓝色梯形（模拟），HDMI是扁梯形（数字）。\n2. VGA也能传声音——VGA只传视频，声音需要单独的音频线；HDMI一根线同时传视频和声音。\n3. HDMI和USB搞混——HDMI是音视频接口，USB是数据接口，功能不同。\n\n【出题方向】\n常考选择题\"能同时传输视频和音频的接口是\"（HDMI）。也常考填空题\"VGA接口传输的是____信号\"（模拟）。判断题\"VGA接口可以传输音频信号\"（错）。简答题\"比较VGA和HDMI接口的区别\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(638,632,4,4,'打印机','# 打印机\n\n【一句话定义】\n打印机是将计算机中的电子文档输出到纸质的输出设备，主要分为针式打印机、喷墨打印机和激光打印机三种类型。\n\n【具体例子】\n针式打印机像打字机——针头击打色带在纸上留下印迹，能多层复写（打印三联发票），但噪音大、速度慢、分辨率低。喷墨打印机像喷绘——喷头把墨水喷到纸上，彩色效果好，适合打印照片，但墨盒贵、打印成本高。激光打印机像复印机——用激光束在感光鼓上成像，转印到纸上加热固定，速度快（每分钟20-40页）、精度高、单页成本低，办公室最常用。\n\n【常见错误】\n1. 三种打印机适用场景搞混——针式用于发票复写，喷墨用于照片彩色，激光用于办公文档。\n2. 以为喷墨打印机便宜——虽然机器便宜，但墨盒消耗快，长期使用成本可能高于激光。\n3. 激光打印机不能打彩色——彩色激光打印机可以，但价格贵，一般办公室用黑白激光。\n\n【出题方向】\n常考选择题\"打印快递单应选用____打印机\"（针式）、\"办公室打印文档应选用____打印机\"（激光）。也常考填空题\"打印机的三种类型是____、____和____\"（针式、喷墨、激光）。简答题\"比较三种打印机的特点和适用场景\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(639,632,4,4,'扫描仪','# 扫描仪\n\n【一句话定义】\n扫描仪是利用光电技术和数字处理技术，将纸质图片、照片或文档转换为计算机可识别的数字图像文件的输入设备。\n\n【具体例子】\n扫描仪就像复印机+相机的组合——把纸质的试卷、照片、身份证放在玻璃板上，扫描仪用光线照射，CCD传感器捕捉反射光，转换成数字图像存到电脑里。分辨率用dpi（每英寸点数）衡量——300dpi足够日常办公，1200dpi以上适合专业印刷。扫描仪通过USB接口连接电脑。学校教务处常用扫描仪把学生试卷扫描成电子版存档。\n\n【常见错误】\n1. 把扫描仪和打印机搞混——扫描仪是把纸质变电子（输入），打印机是把电子变纸质（输出），功能相反。\n2. 以为扫描分辨率越高越好——分辨率越高文件越大，日常用300dpi足够，没必要开到最大。\n3. 扫描仪只能扫描照片——其实文档、身份证、手绘图都可以扫描，还能OCR识别文字。\n\n【出题方向】\n常考选择题\"扫描仪属于____设备\"（输入）。也常考填空题\"扫描仪的分辨率单位是____\"（dpi）。判断题\"扫描仪和打印机是同一种设备\"（错，扫描是输入，打印是输出）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(640,632,4,4,'显示器CRT与LCD','# 显示器（CRT与LCD）\n\n【一句话定义】\nCRT（阴极射线管）显示器是老式大体积显示器，利用电子束轰击荧光粉发光；LCD（液晶显示器）是现在主流的平板显示器，通过液晶分子偏转控制光线通过。\n\n【具体例子】\nCRT显示器像老式大屁股电视机——体积大、占地多、有辐射，但色彩还原好、响应时间快（玩游戏没有拖影），现在已经淘汰。LCD显示器像平板——轻薄、省电、无辐射，但早期有视角小、响应慢的问题（现在IPS面板已解决）。现在主流是LCD的IPS面板（视角广、色彩好）和TN面板（响应快、便宜）。选购注意：分辨率（1080p/2K/4K）、尺寸（24寸/27寸）、刷新率（60Hz/144Hz，越高越流畅）。\n\n【常见错误】\n1. CRT和LCD分不清楚——CRT是大屁股、厚重、已淘汰；LCD是平板、轻薄、现在主流。\n2. 以为显示器越大越好——还要看分辨率和桌面空间，27寸1080p的颗粒感比24寸明显。\n3. 刷新率不重要——对于打游戏，144Hz比60Hz流畅很多，但办公60Hz够用。\n\n【出题方向】\n常考选择题\"目前主流的显示器类型是\"（LCD）。也常考填空题\"CRT显示器的CRT是____的缩写\"（阴极射线管）。判断题\"CRT显示器比LCD显示器更轻薄\"（错）。简答题\"比较CRT和LCD显示器的优缺点\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(641,632,4,4,'机械键盘轴体与人体工学设计','# 机械键盘轴体与人体工学设计\n\n【一句话定义】\n机械键盘的每个按键都有独立的机械开关（轴体），相比薄膜键盘手感清晰、寿命更长；轴体按触发力和声音分为青轴、红轴、茶轴、黑轴等主要类型。人体工学外设通过科学设计减少长时间使用的疲劳和损伤。\n\n【具体说明】\n主流机械轴体（以德国Cherry MX为标准）：①青轴——触发力度大（约50g），段落感明显，按键发出清脆\"咔哒\"声，打字节奏感强但较吵，适合独立办公环境；②红轴——触发力度轻（约45g），线性无段落感，直上直下，声音小，适合游戏和安静的办公环境；③茶轴——触发力度中等（约45g），轻微段落感，声音适中，是打字和游戏的折中选择，被称为\"万能轴\"；④黑轴——触发力度大（约60g），线性无段落感，适合大力操作的游戏玩家；⑤银轴——触发键程极短（1.2mm），响应最快，适合电竞。国产轴体：凯华、TTC、佳达隆等品牌崛起，性价比更高，种类更丰富。\n\n机械键盘的优势：手感一致性好（每颗按键手感相同）；寿命极长（单键寿命通常5000万次以上，薄膜键盘约500万次）；可更换键帽个性化；支持全键无冲（同时按下多个键都能识别，游戏中重要）。\n\n人体工学外设设计：①人体工学键盘——分体式设计（左右手自然分开）、弧形排列（按键角度符合手指自然弯曲）、倾斜坡度（减少手腕翻转）；②人体工学鼠标——垂直鼠标（握持姿势自然）、轨迹球（减少手腕移动）；③人体工学椅子——腰靠支撑、扶手调节、坐垫透气，减少久坐疲劳；④显示器支架——调节到视线水平位置，避免低头或仰头。\n\n健康建议：遵循\"20-20-20\"法则——每用电脑20分钟，看20英尺（约6米）外的物体20秒，缓解眼部疲劳。手腕应保持自然姿势，避免长时间弯曲或扭曲。\n\n【常见错误】\n1. 机械键盘一定适合所有人——青轴的噪音在宿舍和开放式办公区会成为干扰；长时间打字建议选红轴或茶轴。\n2. 轴体只看颜色——不同品牌的同颜色轴体参数可能不同（如某品牌红轴可能比Cherry红轴更轻），购买前应查具体参数。\n3. 人体工学设备贵且不实用——一把好的人体工学椅和键盘能有效预防颈椎病和腕管综合征，长期来看是健康投资。\n\n【出题方向】\n常考选择题\"机械键盘的青轴特点是\"（段落感明显、声音清脆）。填空题\"被称为\'万能轴\'的机械键盘轴体是____\"（茶轴）。判断题\"机械键盘的单键寿命通常比薄膜键盘更长\"（对）。简答题\"简述选择机械键盘轴体时应考虑的因素\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(642,632,4,4,'键盘','# 键盘\n\n【一句话定义】\n键盘是计算机最基本的输入设备，标准104键键盘分为主键盘区、功能键区、控制键区、数字键区和状态指示区五个区域。\n\n【具体例子】\n主键盘区（打字用）：A-Z字母、数字、符号。功能键区：F1-F12，F1通常是帮助，F5刷新，F12在浏览器开开发者工具。控制键区（编辑用）：Insert切换插入/改写（按一下是插入新字，再按一下会替换后面的字），Delete删除光标后字符，Home跳到行首，End跳到行尾，PageUp/PageDown翻页，四个方向键移动光标。数字键区（小键盘）：Num Lock打开/关闭数字功能，关闭时变方向键。状态指示区：Num Lock灯、Caps Lock灯（大写锁定）、Scroll Lock灯。\n\n【常见错误】\n1. Insert键误按导致改写模式——写文档时后面的字莫名其妙被替换，是因为按了Insert键，再按一下切回插入模式。\n2. 不知道Home/End/PageUp/PageDown的用法——Home跳到行首、End跳到行尾、PageUp上翻一页、PageDown下翻一页。\n3. 小键盘输不出数字——看Num Lock灯是否亮，没亮按一下Num Lock键。\n\n【出题方向】\n常考选择题\"标准键盘分为几个区\"（5个：主键盘区、功能键区、控制键区、数字键区、状态指示区）。也常考填空题\"F1键通常的功能是____\"（帮助）。判断题\"Insert键用于切换插入和改写模式\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(643,632,4,4,'高拍仪与3D打印机','# 高拍仪与3D打印机\n\n【一句话定义】\n高拍仪（高速文件拍摄仪）是立在桌面上方、用摄像头快速拍摄纸质文件的数字化设备，教学中已大量替代传统扫描仪；3D打印机是将数字三维模型逐层堆积材料（塑料/金属/树脂）制造出实体物品的增材制造设备。\n\n【具体说明】\n高拍仪：结构——底座+可折叠或伸缩的立杆+顶部高清摄像头（500万-2000万像素）+LED补光灯。使用方式——将书本或纸张平放在底座上→摄像头从上方垂直拍摄→图像实时显示在电脑屏幕上→点击拍照保存为JPG/PDF。优势——扫描速度极快（翻一页拍一页，比扫描仪逐行扫描快得多）；可拍摄立体物体（如实验器材、文物）；自带OCR文字识别功能，拍完可直接导出Word文档。广泛应用于：教师课堂实时投影课本内容、图书馆古籍数字化、窗口单位证件快速复印。\n\n3D打印机工作原理：在计算机中建立三维模型（用SolidWorks、Blender等软件设计或从Thingiverse等网站下载）→切片软件将模型切成几百到几千个薄层→打印机喷头或激光逐层堆积材料，每完成一层工作台下降一点→层层叠加形成立体实物。\n\n3D打印机类型：①FDM熔融沉积——将PLA/ABS塑料丝加热熔化后挤出堆积，成本低（千元级），适合打印模型和原型，精度一般；②SLA光固化——用紫外激光照射液态光敏树脂使其固化，精度极高（可达0.05mm），适合打印精细手办和珠宝蜡模；③SLS选择性激光烧结——用激光烧结尼龙粉末，可打印复杂结构和功能性零件。\n\n应用场景：工业设计（快速制作产品原型验证外观和功能）；医疗领域（3D打印假肢、牙齿矫正器、手术导板）；教育（学生设计并打印创意作品，培养三维空间思维）；建筑（打印建筑构件甚至整栋房屋的墙体）。\n\n【常见错误】\n1. 高拍仪和扫描仪功能一样——高拍仪胜在速度快、可拍立体物体，但扫描仪的图像平整度和分辨率通常更高。\n2. 3D打印什么都能做——目前3D打印主要适合小批量定制和原型制作，大规模生产效率不如传统注塑和模具制造。\n3. 3D打印的材料只有塑料——还可以用金属（钛合金、不锈钢）、树脂、尼龙、陶瓷甚至食品材料（巧克力、面团）。\n\n【出题方向】\n常考选择题\"教师在课堂上实时投影课本内容，适合使用的设备是\"（高拍仪）。填空题\"3D打印的英文全称是____\"（3D Printing/增材制造/Additive Manufacturing）。判断题\"3D打印机是通过逐层堆积材料来制造实体物品的\"（对）。简答题\"比较高拍仪和传统扫描仪的适用场景差异\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(644,632,4,4,'鼠标','# 鼠标\n\n【一句话定义】\n鼠标是计算机最常用的输入设备，通过移动光标和点击操作来控制计算机，常见操作有单击、双击、右击、拖拽和滚轮滚动。\n\n【具体例子】\n单击左键：选中文件或执行按钮。双击左键：打开文件或程序（双击速度在控制面板可以调，太快或太慢都会双击变单击）。右击：弹出快捷菜单（复制、粘贴、删除等）。拖拽：按住左键不放拖动文件到另一个文件夹。滚轮：上下滚动页面，按下去是中键（某些软件有特殊功能）。光电鼠标底部发光，靠感应桌面纹理移动；现在大多是光电鼠标，机械鼠标（底部有滚球）已经很少见了。\n\n【常见错误】\n1. 双击和单击搞混——单击是选中，双击是打开，新手容易把双击变成两次单击。\n2. 右击没反应——可能鼠标坏了，也可能当前位置没有右键菜单（如桌面空白处右击有菜单，某些游戏界面右击没菜单）。\n3. 鼠标在光滑表面不能用——光电鼠标在玻璃、镜面上无法识别纹理，需要垫鼠标垫。\n\n【出题方向】\n常考选择题\"鼠标的常见操作不包括\"（干扰项可能是\"旋转\"\"缩放\"等）。也常考填空题\"鼠标右键通常弹出____\"（快捷菜单）。判断题\"光电鼠标可以在玻璃桌面上正常使用\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(645,631,4,3,'任务3设置BIOS',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(646,645,4,4,'BIOS与CMOS的区别','# BIOS与CMOS的区别\n\n【一句话定义】\nBIOS是固化在ROM中的程序软件，负责硬件检测和系统引导；CMOS是主板上的RAM芯片，由纽扣电池供电，用于保存BIOS的设置参数。二者密不可分但本质不同。\n\n【具体例子】\nBIOS像操作系统（软件），CMOS像数据库（硬件存数据）。BIOS是\"程序\"——开机时自动运行，检查硬件、引导系统。CMOS是\"记事本\"——记录BIOS的设置（如启动顺序、密码、时间），靠主板上的纽扣电池（CR2032）供电，断电后数据不丢失。BIOS需要读取CMOS里的参数来工作——如果CMOS电池没电了，每次开机时间都会重置为出厂日期，BIOS设置也恢复默认。 analogy：BIOS像食堂管理系统（程序），CMOS像菜单数据库（存储），系统需要读取菜单才知道今天卖什么菜。\n\n【常见错误】\n1. 以为BIOS和CMOS是同一个东西——本质不同：BIOS是软件/程序，CMOS是硬件/芯片。\n2. 不知道CMOS电池没电会怎样——开机提示\"CMOS Checksum Error\"、系统时间重置、BIOS设置丢失。\n3. 以为CMOS电池是普通电池——是CR2032纽扣电池，一般能用3-10年。\n\n【出题方向】\n常考简答题\"简述BIOS和CMOS的区别与联系\"。也常考填空题\"BIOS存储在____中，CMOS存储在____中\"（ROM、RAM）。判断题\"BIOS和CMOS是同一个概念\"（错）。选择题\"CMOS由____供电\"（主板纽扣电池）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(647,645,4,4,'BIOS基本概念','# BIOS基本概念\n\n【一句话定义】\nBIOS（基本输入输出系统）是固化在主板ROM芯片中的一组程序，负责开机自检（POST）、初始化硬件和引导操作系统启动。\n\n【具体例子】\nBIOS就像宿舍管理员阿姨——每天你回宿舍（开机），阿姨先检查学生证（POST自检：检查CPU、内存、硬盘等硬件是否正常），确认没问题才开门（引导系统启动）。BIOS里可以设置：开机密码（防止别人用你的电脑）、启动顺序（先从硬盘启动还是U盘/光盘启动）、系统时间、CPU风扇转速等。进入BIOS的方法：开机时按特定键（不同品牌不同，常见的是Delete、F2、F10，屏幕下方会有提示）。\n\n【常见错误】\n1. BIOS和CMOS混为一谈——BIOS是程序（存在ROM里），CMOS是存储芯片（存在RAM里，电池供电），BIOS从CMOS读取设置参数。\n2. 以为BIOS可以随便改——设置不当（如禁用硬盘）可能导致无法启动，修改前最好拍照记录原设置。\n3. 不知道BIOS可以设密码——BIOS密码比Windows密码更安全，因为BIOS密码在操作系统之前生效。\n\n【出题方向】\n常考填空题\"BIOS的中文含义是____\"（基本输入输出系统）。也常考选择题\"进入BIOS通常需要在开机时按____键\"（Delete/F2/F10）。判断题\"BIOS负责开机自检和引导操作系统\"（对）。简答题\"简述BIOS的主要功能\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(648,645,4,4,'UEFI与Legacy BIOS对比','# UEFI与Legacy BIOS对比\n\n【一句话定义】\nUEFI（统一可扩展固件接口）是传统BIOS的替代方案，采用图形化界面、支持鼠标操作、启动速度更快、支持2TB以上大硬盘和安全启动功能，目前新主板已全面采用UEFI，传统Legacy BIOS逐步被淘汰。\n\n【具体说明】\nLegacy BIOS的局限：①16位实模式运行，启动速度慢（自检时间长）；②分区表依赖MBR，最大只支持2.2TB硬盘；③启动过程无安全验证，恶意软件可劫持启动；④文本界面蓝底白字，只能用键盘操作；⑤扩展性差，新硬件支持需更新BIOS芯片中的固件。\n\nUEFI的优势：①启动速度快——跳过传统BIOS的逐项硬件自检，采用并行初始化，开机时间从几十秒缩短到几秒；②支持大容量硬盘——原生支持GPT分区表，可识别18EB（约180亿GB）容量的硬盘；③图形化界面——支持鼠标操作、多语言显示（包括中文），界面友好；④安全启动（Secure Boot）——只允许加载经过数字签名验证的操作系统引导程序，防止引导区病毒和恶意软件；⑤网络功能——UEFI环境下可直接联网下载更新或进行远程管理。\n\n兼容性设置：新主板默认UEFI模式，但为兼容旧系统通常保留CSM（Compatibility Support Module，兼容支持模块）选项。安装Windows 7 64位或更新系统建议用UEFI模式；安装Windows XP或32位旧系统需开启CSM以Legacy模式运行。UEFI模式下安装系统，硬盘必须初始化为GPT分区表；Legacy模式下使用MBR分区表。\n\n进入UEFI设置：与BIOS类似，开机时按Delete/F2/F10键（具体按键因主板品牌而异），部分Windows 10/11系统可通过\"设置→更新和安全→恢复→高级启动→UEFI固件设置\"重启进入。\n\n【常见错误】\n1. UEFI和BIOS是两个完全不同的东西——UEFI是BIOS的升级版和替代者，功能完全覆盖BIOS且更强大，日常仍习惯叫\"BIOS设置\"但实际已是UEFI。\n2. UEFI模式下装系统用了MBR分区表——UEFI+GPT是标准组合，UEFI+MBR会导致系统无法引导。\n3. 关闭安全启动装系统后忘记开启——安装某些Linux系统需暂时关闭Secure Boot，装完后建议重新开启以保障安全。\n\n【出题方向】\n常考选择题\"UEFI相比传统BIOS的优势不包括\"（16位实模式运行——这是BIOS的特点）。填空题\"UEFI原生支持____分区表，可识别超过2TB的大容量硬盘\"（GPT）。判断题\"UEFI支持图形化界面和鼠标操作\"（对）。简答题\"简述UEFI相比Legacy BIOS的三个主要优势\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(649,631,4,3,'任务1解剖计算机',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(650,649,4,4,'CPU性能指标','# CPU性能指标\n\n【一句话定义】\nCPU是计算机的运算和控制核心，主要性能指标包括主频、外频、倍频、字长和核心数，其中主频=外频×倍频。\n\n【具体例子】\n主频就像班长说话的速度——3.0GHz比2.0GHz快，处理同样的任务用时更短。外频是基准频率（好比时钟的滴答间隔），倍频是放大倍数，主频=外频×倍频。字长就像一次能装多少东西——64位CPU一次处理64bit数据，比32位（4字节）一次处理的数据更多。核心数就像有几个班长——双核是两个CPU一起干活，四核是四个一起。缓存就像讲台桌面——L1最小但最快（放最常用数据），L2较大稍慢，L3最大最慢。\n\n【常见错误】\n1. 认为主频越高CPU一定越好——还要看核心数、缓存、架构，同架构下才能直接比主频。\n2. 主频公式记反——主频=外频×倍频（不是外频÷倍频）。\n3. 字长单位搞混——64位CPU的\"位\"是bit，不是字节（Byte），64bit=8字节。\n\n【出题方向】\n常考计算题\"已知外频100MHz、倍频36，求主频\"（3600MHz=3.6GHz）。也常考填空题\"CPU的性能指标包括主频、____、____和____\"（外频、倍频、字长、核心数）。选择题\"主频=____×____\"（外频、倍频）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(651,649,4,4,'CPU散热器与风冷水冷系统','# CPU散热器与风冷水冷系统\n\n【一句话定义】\nCPU散热器是将CPU工作时产生的热量及时散出的装置，主流散热方式分为风冷（风扇+散热片，成本低维护简单）和水冷（液体循环导热，散热效率高噪音低），选择合适的散热器对CPU稳定运行和寿命至关重要。\n\n【具体说明】\n风冷散热器结构：散热鳍片（铝制或铜制薄金属片，增大与空气接触面积）+热管（铜管内填充相变液体，快速将CPU热量传导到鳍片）+风扇（推动空气流过鳍片带走热量）。下压式风冷：风扇向下吹风，兼顾主板供电区域散热，适合小机箱；塔式风冷：侧面吹风，鳍片面积大散热效率高，是主流选择。代表产品：利民AX120、九州风神玄冰400。\n\n水冷散热器结构：水冷头（贴合CPU表面，内部有微水道）+水泵（推动冷却液循环）+冷排（带鳍片的散热器）+风扇（吹冷排散热）+水管（连接水冷头和冷排）。一体式水冷（AIO）：出厂已封装好冷却液，无需维护，安装方便，有120mm/240mm/360mm规格（数字表示冷排风扇总数）。分体式水冷：自己组装水路，可扩展显卡和主板散热，外观炫酷但价格高、需定期维护。\n\n散热性能对比：入门级风冷 < 高端风冷（双塔双风扇）< 240mm一体水冷 < 360mm一体水冷。对于普通办公和学习的CPU，百元级风冷已足够；高性能游戏CPU和长时间满载的工作站建议用240mm以上水冷。\n\n其他散热方式：机箱风扇（辅助整体通风，前进后出/下进上出形成风道）；硅脂（填充CPU与散热器之间的微小缝隙，提高导热效率，安装时需涂抹均匀）；液态金属（导热效率是硅脂的10倍以上，用于高端超频玩家）。\n\n【常见错误】\n1. 水冷一定比风冷好——高端双塔风冷的散热能力可以媲美240mm水冷，且风冷没有漏液风险。\n2. 忽视机箱风道——再好的散热器，如果机箱内部热空气排不出去也会影响散热效果。\n3. 水冷会漏液损坏电脑——一体式水冷出厂已密封，正常使用漏液概率极低；分体式水冷需定期检查接头。\n\n【出题方向】\n常考选择题\"下列CPU散热方式中，散热效率最高的是\"（水冷/360mm一体水冷）。填空题\"风冷散热器由____、热管和风扇三部分组成\"（散热鳍片）。判断题\"风冷散热器一定比水冷散热器的噪音大\"（错，高端风冷可以很安静）。简答题\"简述风冷和水冷散热器的区别及各自的适用场景\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(652,649,4,4,'NVMe M.2接口与DDR5内存','# NVMe M.2接口与DDR5内存\n\n【一句话定义】\nNVMe M.2是当前主流的固态硬盘接口标准，通过PCIe总线直接通信，读写速度远超传统SATA接口；DDR5是第五代双倍数据率同步动态随机存储器，带宽和容量相比DDR4大幅提升，是2022年后新装机的主流内存规格。\n\n【具体说明】\nNVMe M.2固态硬盘：传统SATA接口SSD的读写速度约500MB/s，已达SATA 3.0接口的物理上限。NVMe（Non-Volatile Memory Express）是专为闪存设计的新协议，通过M.2接口走PCIe总线（不与SATA共享带宽），顶级型号顺序读取速度可达7000MB/s以上，是SATA SSD的10倍以上。\n\nM.2接口形态：M.2是一种小型插槽标准（像一块口香糖大小），直接插在主板上无需数据线和电源线。长度规格有2230/2242/2260/2280（22mm宽，30/42/60/80mm长），2280最常见。安装方式：对准M.2插槽斜插入→按下→用螺丝或主板卡扣固定。\n\nDDR5内存特点：①更高频率——起步频率4800MHz（DDR4最高3200MHz常见），高端型号可达6400MHz以上；②更大容量——单条容量从8GB起步，最高可达128GB（DDR4单条最高32GB常见）；③更低电压——工作电压从DDR4的1.2V降至1.1V，更省电发热更小；④双通道增强——每个DDR5内存模块内部有两个独立32位子通道，效率更高。\n\n注意：DDR5与DDR4互不兼容——接口缺口位置不同，不能混插；主板必须支持DDR5才能使用。选购时应根据主板支持的规格选择。\n\n【常见错误】\n1. M.2和SATA固态混为一谈——M.2是接口形态，SATA是协议；M.2接口可以走SATA协议（慢）或NVMe协议（快），购买时需确认是否支持NVMe。\n2. DDR5能插在DDR4主板上——两者接口不同，物理上插不进去，升级需同时更换主板和内存。\n3. 只看容量不看频率——内存性能由容量和频率共同决定，同样的16GB内存，DDR5-4800比DDR4-2666快得多。\n\n【出题方向】\n常考选择题\"NVMe固态硬盘通过____总线与CPU通信\"（PCIe）。填空题\"DDR5内存的起始频率是____MHz\"（4800）。判断题\"M.2接口的固态硬盘一定比SATA接口的快\"（错，M.2接口走SATA协议的速度与2.5寸SATA SSD相同）。简答题\"简述NVMe M.2固态硬盘相比SATA固态硬盘的优势\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(653,649,4,4,'主板与芯片组','# 主板与芯片组\n\n【一句话定义】\n主板是连接计算机所有硬件的平台，芯片组是主板的核心，由北桥和南桥组成，分别负责高速设备和低速外设的数据传输。\n\n【具体例子】\n主板就像学校的操场：CPU插槽是主席台（最重要），内存插槽是观众席（离CPU近速度快），PCI-E插槽是侧门（显卡插这里），SATA接口是地下管道（接硬盘），电源接口是总电闸。北桥像教导主任，只管\"重要的事\"——CPU、内存、显卡之间的高速数据交换。南桥像后勤主任，管\"杂事\"——硬盘、USB、声卡、网卡等低速外设的连接。现在新主板（如Intel平台）把南北桥合并成了一个芯片，叫PCH。\n\n【常见错误】\n1. 以为主板只是个\"托板\"——主板上的芯片组决定了能用什么CPU、多少内存、什么显卡。\n2. 南北桥功能记混——口诀\"北桥管快、南桥管杂\"：北桥连接高速设备（CPU/内存/显卡），南桥连接低速外设（硬盘/USB）。\n3. 分不清PCI-E和PCI——PCI-E是高速接口（显卡），PCI是老式接口（已淘汰）。\n\n【出题方向】\n常考填空题\"主板的核心部件是____\"（芯片组）。也常考选择题\"北桥芯片主要负责连接____\"（CPU、内存、显卡）。简答题\"简述主板芯片组的组成和功能\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(654,649,4,4,'光驱','# 光驱\n\n【一句话定义】\n光驱是读取光盘数据的存储设备，常见类型有CD-ROM、DVD-ROM和DVD刻录机，目前正逐渐被U盘和网络所取代。\n\n【具体例子】\n光驱就像CD机——把光盘放进去，激光头读取盘片上的数据。CD-ROM只能读CD（约700MB），DVD-ROM能读DVD（约4.7GB），DVD刻录机还能往空白光盘上写数据。安装系统时可以用光盘启动（开机时按F12选择光盘启动）。现在U盘更方便（速度快、容量大），所以很多新电脑已经没有光驱了。但学校有些老教材还配光盘，或者需要读银行U盾的光盘驱动。\n\n【常见错误】\n1. DVD光盘和CD光盘搞混——CD容量700MB，DVD容量4.7GB，DVD容量是CD的6倍多。\n2. 以为所有光驱都能刻盘——只有标有\"RW\"或\"刻录机\"的光驱才能写数据，普通DVD-ROM只能读。\n3. 光盘不会坏——光盘也会老化（尤其是盗版盘），数据可能丢失。\n\n【出题方向】\n常考选择题\"CD-ROM光盘的存储容量约为\"（700MB）、\"DVD光盘的存储容量约为\"（4.7GB）。也常考填空题\"光驱正在逐渐被____和____所取代\"（U盘、网络）。判断题\"所有光驱都能刻录光盘\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(655,649,4,4,'内存RAM与ROM','# 内存RAM与ROM\n\n【一句话定义】\nRAM是随机存取存储器，可读可写但断电数据丢失；ROM是只读存储器，断电数据不丢失但内容不可随意更改。\n\n【具体例子】\nRAM就像你的短期记忆——现在正在写的作文内容存在大脑里（RAM），但如果突然停电（断电），没保存的内容就丢了（数据丢失）。ROM就像刻在石头上的字——BIOS程序存在ROM里，关机也不会消失（断电不丢失），但正常手段改不了（只读）。DDR4内存条是现在的主流，有2400MHz、2666MHz等频率，频率越高速度越快。内存容量越大，同时开的程序越多不卡顿——8GB内存能同时开QQ+微信+浏览器，16GB还能再加个游戏。\n\n【常见错误】\n1. RAM和ROM搞混——RAM可读可写断电丢数据，ROM只读断电不丢。口诀\"R（人）W（忘）\"=RAM忘得快（断电丢）。\n2. 以为ROM完全不能写——EPROM和EEPROM可以擦除重写（如升级BIOS），但正常工作时是只读。\n3. 内存条频率越高越好——还要看主板是否支持，插上不兼容的内存条可能开不了机。\n\n【出题方向】\n常考选择题\"断电后数据丢失的存储器是\"（RAM）。也常考填空题\"RAM的中文名称是____，特点是____\"（随机存取存储器、可读可写断电数据丢失）。判断题\"ROM断电后数据会丢失\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(656,649,4,4,'固态硬盘SSD','# 固态硬盘（SSD）\n\n【一句话定义】\n固态硬盘是采用闪存芯片作为存储介质的外存储器，没有机械运动部件，读写速度快、抗震性强、功耗低，但单位容量价格高于机械硬盘。\n\n【具体例子】\n固态硬盘像U盘——都是闪存芯片存储数据，没有转动的盘片。开机速度对比很明显：机械硬盘开机要40-60秒，固态硬盘只要10-15秒。打开Photoshop，机械硬盘要20秒，固态硬盘只要5秒。但固态硬盘贵——1TB固态硬盘的价格能买4TB机械硬盘。接口有SATA（和机械硬盘一样）和M.2（直接插主板，速度更快）。现在主流装机方案是\"固态硬盘装系统+机械硬盘存数据\"——既快又省钱。\n\n【常见错误】\n1. 以为固态硬盘不会坏——固态硬盘有写入次数限制（寿命指标），频繁大量写入会缩短寿命。\n2. 固态硬盘满了不会变慢——实际上固态硬盘使用率超过85%后性能会明显下降。\n3. 所有固态硬盘速度都一样——SATA SSD速度约500MB/s，M.2 NVMe SSD速度可达3000MB/s以上。\n\n【出题方向】\n常考选择题\"固态硬盘与机械硬盘相比，主要优点是\"（速度快、抗震性强）。也常考填空题\"固态硬盘的存储介质是____\"（闪存芯片）。判断题\"固态硬盘有机械运动部件\"（错）。简答题\"比较固态硬盘和机械硬盘的优缺点\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(657,649,4,4,'声卡','# 声卡\n\n【一句话定义】\n声卡是负责音频信号处理的硬件，将计算机中的数字音频信号转换为模拟音频信号输出到音箱，或将麦克风的模拟信号转换为数字信号输入计算机。\n\n【具体例子】\n声卡就像翻译官（和显卡类似）——计算机里的音频文件是数字的（010101），音箱只能放模拟信号（连续的电波），声卡负责翻译。集成声卡集成在主板上，一般人听歌看电影够用。独立声卡（如Creative Sound Blaster）像专业调音台——音质更好、支持更多声道，音乐制作人和游戏玩家喜欢。声卡背面有颜色标记的接口：绿色是音频输出（接音箱），粉色是麦克风输入，蓝色是线路输入。\n\n【常见错误】\n1. 以为声卡只负责输出声音——声卡还负责输入，麦克风录音也要靠声卡。\n2. 独立声卡一定比集成声卡好——对于普通用户，现在的集成声卡（如Realtek）音质已经足够。\n3. 声卡和显卡搞混——声卡管声音，显卡管图像，功能完全不同。\n\n【出题方向】\n常考选择题\"声卡的主要功能是\"（音频信号处理）。也常考填空题\"声卡背面的绿色接口是____\"（音频输出/音箱接口）。判断题\"声卡只能输出声音不能输入\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(658,649,4,4,'显卡','# 显卡\n\n【一句话定义】\n显卡（显示适配器）是负责将计算机中的数字信号转换为显示器能显示的图像信号的硬件，分为集成显卡和独立显卡。\n\n【具体例子】\n显卡就像翻译官——CPU算好画面数据（数字信号），显卡翻译成显示器能看懂的语言（图像信号），输出到屏幕上。集成显卡集成在CPU或主板里，像自带的翻译——够用但不够专业，适合办公上网。独立显卡（如NVIDIA GTX系列、AMD RX系列）像专业同声传译——有独立的GPU芯片和显存，打游戏、做视频剪辑很流畅。显存就像显卡的内存——4GB显存能处理更复杂的画面，8GB显存能开更高的画质。\n\n【常见错误】\n1. 认为不打游戏就不需要显卡——其实集显也能满足日常办公，但独显在处理视频、3D建模时优势明显。\n2. 显存越大显卡越好——还要看GPU核心性能，小显存高性能显卡可能比大显存低性能显卡强。\n3. 独立显卡和集成显卡同时使用不会冲突——现在的计算机可以智能切换，轻任务用集显省电，重任务用独显高性能。\n\n【出题方向】\n常考选择题\"下列属于独立显卡厂商的是\"（NVIDIA、AMD）。也常考填空题\"显卡分为____和____\"（集成显卡、独立显卡）。判断题\"集成显卡性能一定比独立显卡差\"（错，高端集显可能超过低端独显）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(659,649,4,4,'机械硬盘','# 机械硬盘\n\n【一句话定义】\n机械硬盘（HDD）是利用磁头在旋转的盘片上进行数据读写的外存储器，由盘片、磁头、主轴电机和磁头臂组成，容量大但速度相对较慢。\n\n【具体例子】\n机械硬盘像唱片机——盘片高速旋转（5400转或7200转每分钟），磁头像唱针一样悬浮在盘片上方读写数据。转速越快，读写速度越快——7200转比5400转快约33%。容量以TB计（1TB≈1000GB），一个4TB硬盘能存大约1000部高清电影。硬盘的接口是SATA，数据线像扁平的鞋带。选购注意：转速选7200RPM（转/分钟），缓存越大越好（64MB比32MB快）。\n\n【常见错误】\n1. 把转速当成唯一的速度指标——还要看缓存大小、单碟容量等因素。\n2. 以为机械硬盘不能摔——磁头悬浮在盘片上方仅几纳米，碰撞会导致磁头划伤盘片（\"硬盘坏道\"），数据永久丢失。\n3. 和固态硬盘分不清——机械硬盘有盘片会转、便宜、容量大；固态硬盘没盘片、贵、速度快。\n\n【出题方向】\n常考填空题\"机械硬盘的转速单位是____，常见转速有____和____\"（RPM、5400RPM、7200RPM）。也常考选择题\"机械硬盘的数据接口是\"（SATA）。判断题\"机械硬盘不怕震动\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(660,649,4,4,'机箱','# 机箱\n\n【一句话定义】\n机箱是计算机的外壳，用于保护内部硬件并提供安装空间，分为AT和ATX两种架构，ATX是目前主流标准。\n\n【具体例子】\nATX机箱就像标准化的公寓楼——电源在主板下方，主板横放，散热设计更合理。AT机箱像老式筒子楼——布局陈旧，电源在CPU上方，不利于散热，已被淘汰。选购机箱要关注：能否装得下你的主板（ATX全尺寸还是MATX小板）、有没有足够的风扇位散热、钢板厚度（薄的容易共振嗡嗡响）。侧透机箱侧面是透明玻璃或亚克力，可以看见里面发亮的RGB风扇，很炫酷。\n\n【常见错误】\n1. 认为机箱随便买一个就行——其实机箱大小决定能装什么主板、什么显卡，散热设计也影响性能。\n2. AT和ATX分不清——AT是老标准已淘汰，ATX是现在主流，记住\"X\"代表\"扩展性好\"。\n3. 以为机箱影响电脑速度——机箱本身不影响性能，但散热差的机箱会让CPU和显卡降频变慢。\n\n【出题方向】\n常考选择题\"目前主流的机箱架构是\"（ATX）。也常考判断题\"AT机箱是目前主流的机箱架构\"（错）。填空题\"机箱的主要作用是保护____和提供安装空间\"（内部硬件）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(661,649,4,4,'电源','# 电源\n\n【一句话定义】\n电源（PSU）是将交流市电（220V）转换为计算机各部件所需直流电（+12V、+5V、+3.3V）的供电设备，是计算机正常运行的基础。\n\n【具体例子】\n电源就像计算机的\"心脏\"——把家用220V交流电转换成CPU、主板、硬盘需要的低压直流电。功率单位是瓦（W），普通办公电脑300W够用，打游戏需要500W以上。选购电源要看功率是否足够（CPU+显卡+其他≈总功率×1.2），还要看是否有80PLUS认证（铜牌、银牌、金牌——转换效率越高越省电）。劣质电源可能电压不稳，烧坏主板和CPU，所以电源不能省。\n\n【常见错误】\n1. 买电脑只看CPU和显卡，忽视电源——劣质电源会导致整机不稳定甚至烧毁硬件。\n2. 电源功率越大越好——够用就行，500W电脑配1000W电源浪费钱。\n3. 以为电源没有技术含量——好的电源有更稳定的电压输出、更好的散热和更长的寿命。\n\n【出题方向】\n常考填空题\"电源的主要作用是将____V交流电转换为计算机需要的____电\"（220、直流）。也常考选择题\"电源功率的单位是\"（瓦/W）。判断题\"电源功率越大电脑性能越好\"（错，功率够用即可）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(662,649,4,4,'网卡','# 网卡\n\n【一句话定义】\n网卡（网络接口卡NIC）是计算机连接网络的硬件设备，负责数据的发送和接收，每个网卡有全球唯一的MAC地址。\n\n【具体例子】\n网卡就像计算机的\"嘴巴\"——负责和外界（网络）说话。集成网卡集成在主板上，现在几乎所有主板都有。独立网卡像专业的播音设备——服务器上用的多，支持更高速度和更稳定连接。网卡背面是RJ-45接口（像电话线接口但大一点），插网线用。MAC地址是网卡的\"身份证号\"——48位二进制，全球唯一，出厂时烧录在网卡里改不了，如00-1A-2B-3C-4D-5E。\n\n【常见错误】\n1. MAC地址和IP地址搞混——MAC地址是物理地址（网卡的身份证号），IP地址是逻辑地址（可变的网络门牌号）。\n2. 以为无线网卡和有线网卡是一个东西——无线网卡（Wi-Fi）和有线网卡（插网线的）是两种不同硬件。\n3. 网卡速度只看接口——还要看路由器、网线是否支持相同速度。\n\n【出题方向】\n常考填空题\"网卡的物理地址称为____地址\"（MAC）。也常考选择题\"网卡的全球唯一标识是\"（MAC地址）。判断题\"MAC地址可以自行修改\"（错，出厂烧录一般不可改）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(663,439,4,2,'单元3录入文字',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(664,663,4,3,'任务1录入英文',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(665,664,4,4,'打字姿势与击键要领','# 打字姿势与击键要领\n\n【一句话定义】\n正确的打字姿势要求身体坐直、双脚平放、显示器与眼睛平齐，手腕自然悬空不压键盘，击键时干脆利落、力度适中，实现盲打（不看键盘输入）。\n\n【具体说明】\n坐姿要求：①身体坐直略前倾，正对键盘和显示器；②双脚自然平放地面，大腿与地面平行；③两肘贴身体两侧，大臂与小臂约成90度角；④手腕自然悬空或轻放掌托上，不压在键盘边缘；⑤显示器顶部略低于眼睛水平线，距离约50-70cm；⑥椅子高度调整到前臂与桌面平齐。\n\n击键要领：①每个手指分工明确，击键后立即返回基准键位；②击键要干脆，一触即回，不要按住不放或连击；③力度适中，听到按键声即可；④只看屏幕不看键盘，逐步实现盲打；⑤初学者建议从英文文章开始练习，逐步提高速度。\n\n考核标准：对口升学考试中，英文录入一般要求速度≥60字/分钟，准确率≥95%。\n\n【常见错误】\n1. 手腕压在键盘边缘——长时间打字会压迫正中神经，导致手腕酸痛甚至腕管综合征。\n2. 低头看键盘——养成习惯后永远无法盲打，效率始终提不上去。\n3. 用整个手臂带动手指——应该是手指独立运动，手臂保持相对稳定。\n4. 击键过重——既伤手指又影响键盘寿命，而且速度慢。\n\n【出题方向】\n常考填空题\"打字时手腕应该____，不能压在键盘边缘\"（悬空/自然放松）。也常考判断题\"打字时眼睛应该看键盘确保准确\"（错，应看屏幕实现盲打）。简答题\"简述正确的打字姿势要求\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(666,664,4,4,'特殊功能键的使用','# 特殊功能键的使用\n\n【一句话定义】\n键盘上除字母和数字键外，Shift、Caps Lock、Num Lock、Ctrl、Alt、Tab、Esc等功能键在录入和操作中起重要辅助作用，熟练使用能大幅提升效率。\n\n【具体说明】\nShift键（上档键）：按住Shift+字母键输入大写字母；Shift+数字键输入上方符号（如Shift+4=$）；Ctrl+Shift切换输入法。\n\nCaps Lock键（大写锁定）：按一下锁定大写（指示灯亮），此后所有字母输入大写，再按一下解锁。注意：Caps Lock只影响字母键，不影响数字和符号键。\n\nNum Lock键（数字锁定）：控制小键盘区（数字键区）的状态。灯亮时小键盘输入数字（0-9、.、+、-、*、/）；灯灭时小键盘变成方向键和编辑键（Home、End、PgUp、PgDn、Insert、Delete）。\n\nCtrl键（控制键）：通常与其他键组合使用。Ctrl+C复制、Ctrl+X剪切、Ctrl+V粘贴、Ctrl+Z撤销、Ctrl+A全选、Ctrl+S保存、Ctrl+P打印。\n\nAlt键（交替键）：Alt+Tab切换窗口、Alt+F4关闭窗口、Alt+菜单字母打开菜单。\n\nTab键（制表键）：在文本中输入一个制表位（通常是4或8个空格），在对话框中切换焦点。\n\nEsc键（退出键）：取消当前操作、关闭对话框、退出全屏模式。\n\nInsert键：切换插入/改写模式。插入模式：新输入的字符插入到光标位置，后面字符后移；改写模式：新输入的字符替换光标位置的字符。\n\n【常见错误】\n1. Caps Lock灯亮时输入全大写——不知道灯的含义，再按一下Caps Lock即可关闭。\n2. Num Lock灯灭时小键盘不能用——以为是键盘坏了，按一下Num Lock即可恢复。\n3. Insert键误按导致改写——输入时后面的字被替换，再按一下Insert切回插入模式。\n\n【出题方向】\n常考选择题\"输入大写字母应使用____键或按住____+字母键\"（Caps Lock、Shift）。填空题\"Num Lock灯亮时小键盘输入____，灯灭时变成____键\"（数字、方向）。判断题\"Caps Lock锁定后数字键也会输入大写\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(667,664,4,4,'键盘分区与功能键','# 键盘分区与功能键\n\n【一句话定义】\n标准104键键盘分为主键盘区（字母数字）、功能键区（F1-F12）、控制键区（编辑控制）、数字键区（小键盘）和状态指示区五个部分，各区域有特定的功能。\n\n【具体例子】\n主键盘区：A-Z、0-9、符号键，打字主要在这里。功能键区F1-F12：F1帮助、F2重命名、F5刷新、F11全屏、F12另存为（不同软件定义不同）。控制键区：Insert切换插入/改写、Delete删除、Home行首、End行尾、PageUp上翻、PageDown下翻、方向键移动光标。数字键区：Num Lock打开/关闭数字功能，关闭时变成方向键。状态指示区：三个灯（Num Lock、Caps Lock大写锁定、Scroll Lock滚动锁定）。\n\n【常见错误】\n1. Insert键误按导致改写模式——写文档时后面的字被替换，是因为按了Insert键，再按一下切回插入模式。\n2. 不知道Home/End/PageUp/PageDown——Home跳到行首、End跳到行尾、PageUp上翻一页、PageDown下翻一页。\n3. Caps Lock灯亮时以为键盘坏了——只是大写锁定开了，再按一下Caps Lock关掉即可。\n\n【出题方向】\n常考选择题\"标准键盘分为几个区\"（5个）。也常考填空题\"F1键通常的功能是____\"（帮助）。判断题\"Insert键用于切换插入和改写模式\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(668,663,4,3,'任务2录入中文',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(669,668,4,4,'五笔字型输入法基础','# 五笔字型输入法基础\n\n【一句话定义】\n五笔字型是由王永民发明的一种形码输入法，将汉字拆分为字根（约130个基本字根分布在25个键位上，除Z键外），通过敲击字根对应的键位来输入汉字，具有重码率低、输入速度快的特点。\n\n【具体说明】\n字根分区：横区（G-A键，起笔为横的字根）、竖区（H-M键，起笔为竖）、撇区（T-Q键，起笔为撇）、捺区（Y-P键，起笔为捺/点）、折区（N-X键，起笔为折）。每个键位有1个键名汉字（如G键键名\"王\"、F键键名\"土\"），按4下该键可输入键名汉字。\n\n汉字拆分原则：①书写顺序——按汉字正常书写顺序拆分；②取大优先——优先拆出较大的字根；③兼顾直观——拆分结果应符合视觉直观性；④能连不交——优先拆相连的字根而非相交的。\n\n编码规则：\n- 键名汉字：连击键位4次（如\"王\"=GGGG）\n- 成字字根：先打键位（报户口）+首笔+次笔+末笔（如\"五\"=GGHG）\n- 一般汉字：最多取4码——第1字根+第2字根+第3字根+末字根（如\"中\"=KHK，拆成\"口\"+\"丨\"）\n- 不足4个字根的字：打完字根后加末笔识别码（由末笔笔画+字形结构确定）\n\n一级简码：25个最常用的字只需按1个键+空格（如\"的\"=R+空格、\"了\"=B+空格、\"在\"=D+空格）。\n\n【常见错误】\n1. 字根位置记不准——需要背诵字根口诀并反复练习，如G键\"王旁青头戋五一\"。\n2. 拆分顺序错误——必须按汉字正确书写顺序拆分。\n3. 忘记加识别码——对于不足4个字根的字，如果不加识别码会出现大量重码。\n\n【出题方向】\n常考选择题\"五笔字型输入法属于____编码方式\"（形码）。填空题\"五笔字型中，\'中\'字的编码是____\"（KHK）。判断题\"五笔字型的字根分布在25个键位上（除Z键外）\"（对）。简答题\"简述五笔字型输入法的优缺点\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(670,668,4,4,'搜狗拼音输入法的使用','# 搜狗拼音输入法的使用\n\n【一句话定义】\n搜狗拼音输入法是目前最常用的拼音输入法之一，支持全拼、简拼、双拼输入，具有智能联想、云输入、细胞词库、手写输入等功能，能大幅提高中文录入效率。\n\n【具体说明】\n输入方式：①全拼——输入完整拼音\"zhongguo\"候选\"中国\"；②简拼——只输入声母\"zg\"候选\"中国\"；③混拼——部分全拼+部分简拼\"zhongg\"候选\"中国\"。\n\n候选字选择：①按空格输入第1个候选字；②按数字键1-9选择对应候选字；③按\"+\"/\"-\"或PageDown/PageUp翻页查看更多候选；④按Shift+数字键删除错误候选。\n\n高级功能：①V模式——按V后输入数字可快速输入大写金额（如V123→\"壹佰贰拾叁元整\"）、日期、算式结果；②U模式——按U后输入笔画或拆分输入不会读的字（如U\'hspn→输入横竖撇捺对应的字）；③自定义短语——设置\"xx\"=\"四川省成都市\"，输入xx即可快速输入长文本。\n\n【常见错误】\n1. 候选字找不到——按\"+\"号向后翻页，或者用更完整的拼音缩小范围。\n2. 专业名词输不出来——搜狗输入法支持细胞词库（如计算机专业词库），可在设置中下载。\n3. 简拼重码太多——对于常用词用简拼，不常用的词用全拼减少重码。\n\n【出题方向】\n常考选择题\"搜狗拼音输入法中，输入\'v123\'会输出____\"（壹佰贰拾叁元整）。判断题\"搜狗输入法支持自定义短语功能\"（对）。简答题\"简述拼音输入法中全拼和简拼的区别\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(671,668,4,4,'正确打字指法','# 正确打字指法\n\n【一句话定义】\n正确的打字指法是将双手食指到小指分别放在基准键位（ASDF和JKL;）上，每个手指负责特定区域的按键，实现盲打（不看键盘打字）。\n\n【具体例子】\n基准键位（Home Row）：左手小指放A、无名指放S、中指放D、食指放F；右手食指放J、中指放K、无名指放L、小指放;（分号）。F和J键上有小凸点——手指不看键盘也能定位。每个手指分工明确：左手小指管QAZ，左手无名指管WSX，左手中指管EDC，左手食指管RFVTGB；右手食指管YHNUJM，右手中指管IK，右手无名指管OL，右手小指管P;。大拇指只负责空格键。\n\n【常见错误】\n1. 一指禅——只用两个食指打字，速度慢、容易出错。\n2. 不看基准键位——手指悬空乱按，找不到按键位置。\n3. 手腕压在键盘边缘——长时间打字会得腕管综合征，手腕应该悬空或放在掌托上。\n\n【出题方向】\n常考填空题\"打字基准键位中，左手的基准键是____，右手的基准键是____\"（ASDF、JKL;）。也常考判断题\"F和J键上有小凸点用于手指定位\"（对）。简答题\"简述正确的打字姿势和指法\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(672,668,4,4,'汉字输入法分类','# 汉字输入法分类\n\n【一句话定义】\n汉字输入法分为键盘输入法（音码如拼音、形码如五笔、音形结合）、非键盘输入法（手写、语音、扫描识别），每种有不同的输入原理和适用人群。\n\n【具体例子】\n音码输入法：全拼（打完整拼音\"zhong\"出\"中\"）、简拼（打\"zh\"或\"z\"）、双拼（每个字只需要按两个键）。形码输入法：五笔字型（\"中\"字拆成\"口\"+\"丨\"，编码是KHK），重码率低、输入速度快，但需要记字根。音形结合：自然码（拼音+笔画辅助）。手写输入：用触控笔或手指在屏幕上写字，适合不会拼音的老年人。语音输入：对着麦克风说话自动转成文字。扫描识别（OCR）：把纸质文档扫描后自动识别成电子文字。\n\n【常见错误】\n1. 以为拼音输入法最慢——其实熟练的简拼或双拼速度也很快，且学习成本低。\n2. 五笔一定比拼音快——对于普通用户，拼音输入法（尤其是智能联想）已经足够快。\n3. 手写输入和扫描识别搞混——手写是实时输入（一笔一划写），扫描识别是批量处理（整页扫描后识别）。\n\n【出题方向】\n常考选择题\"五笔字型输入法属于____\"（形码）。也常考填空题\"汉字输入法按编码方式可分为____、____和____\"（音码、形码、音形结合）。判断题\"拼音输入法属于音码输入法\"（对）。简答题\"简述汉字输入法的分类\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(673,668,4,4,'软键盘的使用','# 软键盘的使用\n\n【一句话定义】\n软键盘是输入法提供的屏幕虚拟键盘，通过鼠标点击输入键盘上没有的特殊符号（如数学符号、希腊字母、日文假名、制表符等），也可在物理键盘故障时作为应急输入工具。\n\n【具体说明】\n打开方式：①右键点击输入法状态栏上的软键盘图标→选择需要的软键盘类型；②左键点击软键盘图标快速打开/关闭最近一次使用的软键盘。\n\n常见软键盘类型：PC键盘（标准键盘）、标点符号（，。！？等）、数字序号（①②③④⑤）、数学符号（+-×÷=≠≈）、单位符号（℃￥$€£）、制表符（┌─┬─┐等）、特殊符号（★☆●○等）、希腊字母（αβγδ）、俄文字母、注音符号、拼音、日文平假名/片假名、韩文。\n\n应用场景：①需要输入键盘上没有的特殊符号（如℃、★、α等）；②需要输入大段中文标点时；③物理键盘部分按键损坏时作为应急方案。\n\n【常见错误】\n1. 不知道软键盘可以输入特殊符号——一直用插入符号菜单，效率低。\n2. 软键盘打开后忘记关闭——占用屏幕空间，再点一下软键盘按钮即可关闭。\n3. 不知道软键盘有多种类型——右键点击可以选择数学符号、希腊字母等多种类型。\n\n【出题方向】\n常考选择题\"需要输入希腊字母αβγ时，应该使用输入法的____功能\"（软键盘）。填空题\"打开软键盘的常用操作是____点击输入法状态栏上的软键盘图标\"（右键/左键）。判断题\"软键盘只能替代标准键盘输入\"（错，还可以输入各种特殊符号）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(674,668,4,4,'输入法的切换与状态栏','# 输入法的切换与状态栏\n\n【一句话定义】\nWindows中通过Ctrl+Shift循环切换已安装的输入法，Ctrl+Space（空格）快速在中英文输入法间切换，输入法状态栏显示当前输入状态并提供常用设置入口。\n\n【具体说明】\n切换快捷键：①Ctrl+Shift——按一次切换一种已安装的输入法（循环切换）；②Ctrl+Space——在中文输入法和英文输入法之间快速切换；③Win+Space（Windows 10/11）——切换输入法；④Shift键——在中文输入法状态下按Shift临时切换为英文半角。\n\n输入法状态栏组成：①中/英按钮——显示当前是中文还是英文输入状态；②全/半角按钮——全角字符占两个字节宽度（如中文标点），半角占一个字节（如英文标点）；③中/英文标点——中文句号\"。”与英文句号\"。\"的区别；④软键盘按钮——打开屏幕虚拟键盘，输入特殊符号；⑤设置按钮——打开输入法属性设置。\n\n添加输入法：控制面板→时钟、语言和区域→区域和语言→键盘和语言→更改键盘→添加→选择需要的输入法。\n\n【常见错误】\n1. 打不出中文——按Ctrl+Space或Ctrl+Shift切换到中文输入法。\n2. 输入的标点总是英文——点击状态栏上的标点按钮切换到中文标点。\n3. 全角半角搞混——输入密码时如果开了全角，数字和字母会变成全角字符导致密码错误。\n\n【出题方向】\n常考选择题\"在Windows中切换输入法的快捷键是____\"（Ctrl+Shift）。填空题\"中英文输入法快速切换的快捷键是____\"（Ctrl+Space）。判断题\"Shift键可以在中文输入法状态下临时输入英文\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(675,439,4,2,'单元4认识操作系统',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(676,675,4,3,'任务2简单操作Windows',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(677,676,4,4,'任务栏操作','# 任务栏操作\n\n【一句话定义】\n任务栏是位于屏幕底部的水平长条，由开始按钮、中间部分（已打开程序/快速启动）和通知区域（系统托盘）组成，可设置为自动隐藏、改变位置、锁定。\n\n【具体例子】\n任务栏操作步骤：①锁定/解锁——右击任务栏空白处→勾选/取消\"锁定任务栏\"；②自动隐藏——右击→属性→勾选\"自动隐藏任务栏\"，鼠标移到屏幕底部才显示；③改变位置——解锁后按住任务栏拖到屏幕顶部、左侧或右侧；④调整大小——解锁后把鼠标放在任务栏边缘，出现双向箭头时拖动。通知区域（右下角）显示时钟、音量、网络连接状态、杀毒软件图标等。如果图标太多可以点\"显示隐藏的图标\"小三角查看。\n\n【应会操作】设置任务栏的完整操作路径：\n第一步：移动任务栏位置→右击任务栏空白处→取消勾选\"锁定任务栏\"→拖拽任务栏到屏幕的底部/顶部/左侧/右侧→再次勾选\"锁定任务栏\"固定位置。\n第二步：调整任务栏大小→取消锁定后→将鼠标移到任务栏边缘→指针变成双向箭头→拖拽调整高度/宽度。\n第三步：设置任务栏属性→右击任务栏→属性→设置锁定任务栏/自动隐藏任务栏/使用小图标→任务栏按钮（始终合并、隐藏标签/当任务栏被占满时合并/从不合并）→通知区域自定义→点击\"确定\"。\n第四步：添加快速启动图标→将程序图标/快捷方式拖拽到任务栏上固定→或从开始菜单拖拽程序到任务栏。\n\n【常见错误】\n1. 任务栏拖不动——因为锁定了，先右击取消\"锁定任务栏\"再拖。\n2. 程序最小化后找不到——看任务栏中间部分的按钮，点击即可恢复窗口。\n3. 以为任务栏只能在底部——其实可以放在屏幕的上、下、左、右四个位置。\n\n【出题方向】\n常考实操题\"将任务栏设置为自动隐藏并移动到屏幕右侧\"。也常考填空题\"任务栏由____、____和____三部分组成\"（开始按钮、中间部分、通知区域）。选择题\"任务栏上的通知区域位于\"（右下角）。判断题\"锁定的任务栏可以改变位置\"（错，需先解锁）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(678,676,4,4,'剪贴板','# 剪贴板\n\n【一句话定义】\n剪贴板是Windows在内存中开辟的临时存储区，用于在不同程序或位置之间传递信息，一次只能保留一则信息，关机后内容消失。\n\n【应会操作】\n\n复制粘贴的过程就是剪贴板在工作：①选中文字按Ctrl+C（内容被复制到剪贴板）→②到另一个地方按Ctrl+V（从剪贴板取出内容粘贴）。剪切（Ctrl+X）也是先把内容放到剪贴板，然后从原位置删除。剪贴板只能存一条信息——你复制了A再复制B，剪贴板里就只有B了。剪贴板的内容关机后消失（因为存在内存里）。Windows 7中按Win+V可以查看剪贴板历史（如果开启了剪贴板功能）。\n\n【常见错误】\n1. 以为剪贴板能存多条信息——默认只能存最近的一条（Windows 10+支持剪贴板历史）。\n2. 关机后以为剪贴板内容还在——剪贴板存在内存中，断电/关机后内容丢失。\n3. 复制后忘了粘贴又复制别的——之前的内容被覆盖了。\n\n【出题方向】\n常考填空题\"剪贴板是Windows在____中开辟的临时存储区\"（内存）。也常考判断题\"剪贴板中的内容关机后仍然存在\"（错）。选择题\"剪贴板一次能保留____则信息\"（一/1）。简答题\"简述剪贴板的作用和工作原理\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(679,676,4,4,'回收站','# 回收站\n\n【一句话定义】\n回收站是硬盘上的一块临时存储区域，用于存放从硬盘删除的文件和文件夹，这些文件可以被还原到原位置或永久删除，但U盘/软盘删除的文件不经过回收站。\n\n【应会操作】\n\n操作：①删除到回收站——选中文件按Delete键（可恢复）；②永久删除——选中文件按Shift+Delete（不可恢复）或在回收站中删除；③还原——双击打开回收站→选中文件→\"还原此项目\"（文件回到原位置）。注意：每个磁盘分区有独立的回收站空间，可在回收站属性中设置大小（默认占磁盘10%）。当回收站满了，最早删除的文件会被自动清除以腾出空间。U盘/软盘/网络位置删除的文件直接删除，不进回收站。\n\n【常见错误】\n1. 以为回收站在内存里——回收站在硬盘上，删除文件其实没真正删除，只是换了个地方存。\n2. U盘删除的文件去回收站找——U盘删除的文件不进回收站，直接永久删除。\n3. 还原后找不到文件——还原的文件回到原来所在的文件夹，不是在桌面上。\n\n【出题方向】\n常考选择题\"删除到回收站的快捷键是\"（Delete）、\"永久删除的快捷键是\"（Shift+Delete）。也常考判断题\"U盘删除的文件可以在回收站中恢复\"（错）。实操题\"将文件删除到回收站，然后还原到原位置\"。填空题\"回收站中的文件____被还原\"（可以/可以）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(680,676,4,4,'图标与快捷方式','# 图标与快捷方式\n\n【一句话定义】\n图标是文件、文件夹、程序或快捷方式的图形化表示；快捷方式是指向某个程序或文件的指针（扩展名.lnk），删除快捷方式不会影响原程序。\n\n【具体例子】\n桌面上的\"计算机\"\"网络\"\"回收站\"是系统图标；\"Internet Explorer\"是应用程序图标；你创建的文件夹是文件夹图标；快捷方式图标左下角有个小箭头——表示这不是真正的程序，只是个\"门牌号\"指向真正的程序。比如你安装了QQ，安装目录在C:\\Program Files\\Tencent\\QQ，你在桌面创建的QQ快捷方式只是个指针（约1KB），双击它实际是告诉系统\"去那个目录运行QQ.exe\"。删除桌面快捷方式：QQ还在硬盘里，只是桌面上找不到入口了。\n\n【应会操作】创建桌面快捷方式的完整操作路径：\n方法一（从开始菜单）：点击开始菜单→所有程序→找到目标程序→右键→发送到→桌面快捷方式。\n方法二（从程序文件夹）：打开资源管理器→进入C:\\Program Files→找到程序文件夹→右键程序主执行文件（.exe）→发送到→桌面快捷方式。\n方法三（从桌面右键）：桌面空白处右键→新建→快捷方式→输入程序路径或点击\"浏览\"选择→点击\"下一步\"→输入快捷方式名称→点击\"完成\"。\n\n删除快捷方式：右键快捷方式→删除（注意：只删除快捷方式指针，不影响原程序文件）。快捷方式图标左下角有小箭头标识。\n\n【常见错误】\n1. 以为删除快捷方式就卸载了程序——快捷方式只是指针，删了不影响原程序。\n2. 分不清图标和快捷方式——快捷方式左下角有小箭头，普通图标没有。\n3. 把快捷方式复制给别人以为对方能用——别人的电脑没有对应程序，快捷方式打不开。\n\n【出题方向】\n常考判断题\"删除桌面上的快捷方式会卸载该程序\"（错）。也常考选择题\"快捷方式的扩展名是\"（.lnk）。实操题\"为指定程序创建桌面快捷方式，然后删除快捷方式验证原程序是否还能运行\"。填空题\"快捷方式的本质是____\"（指向原程序或文件的指针）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(681,676,4,4,'对话框元素','# 对话框元素\n\n【一句话定义】\n对话框是Windows中的特殊窗口，一般可移动但不能改变大小，包含命令按钮、选项卡、单选按钮、复选框、文本框、下拉列表框和数值框等元素。\n\n【具体例子】\n打开\"显示属性\"对话框观察元素：①选项卡——顶部一排\"主题\"\"桌面\"\"屏幕保护程序\"等标签，点击切换不同设置页；②单选按钮○——圆点标记，一组只能选一个（如分辨率选择1024×768或800×600）；③复选框□——方框打勾√，可以多选（如\"在恢复时显示登录屏幕\"）；④文本框——直接输入文字（如搜索关键词）；⑤下拉列表框——点击▼展开选项列表（如选择屏幕分辨率）；⑥数值框——可输入数字或点上下箭头调节；⑦命令按钮——\"确定\"\"取消\"\"应用\"等，点击执行操作。对话框和窗口的区别：对话框一般不能改变大小（没有最大化和最小化按钮）。\n\n【常见错误】\n1. 分不清单选按钮和复选框——单选是○（圆点，一组选一个），复选是□（方框，可以多选）。\n2. 点了\"取消\"以为设置生效了——取消是放弃修改，确定才是保存。\n3. 以为对话框可以最大化——对话框一般不能改变大小。\n\n【出题方向】\n常考选择题\"对话框中一组只能选一个的控件是\"（单选按钮）。也常考填空题\"对话框中可多选的控件是____\"（复选框）。判断题\"对话框可以改变大小\"（错）。实操题\"打开显示属性对话框，分别识别其中的选项卡、单选按钮、复选框和下拉列表框\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(682,676,4,4,'开始菜单','# 开始菜单\n\n【一句话定义】\n开始菜单是计算机程序、文件夹和设置的主门户，由用户标识、固定项目列表、常用程序列表、\"所有程序\"菜单、搜索框和关机按钮组成。\n\n【具体例子】\n打开开始菜单的方法：①点击任务栏左下角的开始按钮（彩色Windows图标）；②按键盘上的Windows徽标键（Win键，在Ctrl和Alt之间）。固定项目列表——你可以把常用的程序\"固定\"在这里（右击程序→附到开始菜单）。常用程序列表——系统自动记录你最近经常用的程序。所有程序——按字母顺序列出所有已安装的程序。搜索框——直接输入程序名（如\"记事本\"）快速找到并打开。关机按钮——点击有选项：关机、重新启动、睡眠、休眠。Win7还新增了跳转列表功能——右击任务栏或开始菜单上的程序图标，显示最近使用的文件列表。\n\n【应会操作】自定义开始菜单的完整操作路径：\n第一步：右击任务栏空白处→选择\"属性\"→切换到\"开始菜单\"选项卡。\n第二步：选择开始菜单样式→选择\"开始菜单\"（默认）或\"经典开始菜单\"。\n第三步：点击\"自定义\"按钮→在列表中设置各项目的显示方式（显示为链接/显示为菜单/不显示此项目）。\n第四步：设置\"要显示在跳转列表中的最近使用的项目数\"→点击\"确定\"→再点击\"确定\"。\n\n跳转列表（Jump List）：将鼠标移到开始菜单中某个程序上→程序右侧出现向右箭头→点击显示最近打开的文档和常用操作→可以快速打开最近使用的文件。\n\n【常见错误】\n1. 找不到已安装的程序——去开始菜单→所有程序里按字母顺序找。\n2. 以为开始菜单就是程序列表——实际上还包括搜索、设置、关机等功能。\n3. 不知道Win键能打开开始菜单——Win键是最高效的打开方式，比鼠标点更快。\n\n【出题方向】\n常考填空题\"打开开始菜单的快捷键是____\"（Win键/Windows徽标键）。也常考实操题\"通过开始菜单搜索框打开\'计算器\'程序\"。选择题\"开始菜单的关机按钮包含以下哪些选项\"（关机、重新启动、睡眠、休眠）。判断题\"跳转列表可以显示最近使用的文件\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(683,676,4,4,'文件命名规则','# 文件命名规则\n\n【一句话定义】\nWindows 7文件名不区分大小写，最多255个字符，可以包含空格但不能包含\\ / : * ? \" < > |，不能使用系统保留的设备名（CON、PRN、AUX等）。\n\n【具体例子】\n合法文件名：\"我的作文.docx\"\"2024期末成绩.xlsx\"\"photo(1).jpg\"——可以有空格、数字、括号、下划线。非法文件名：\"成绩/汇总.xlsx\"（含/）\"作业*答案.docx\"（含*）\"我的：日记.txt\"（含：）——这些特殊字符在Windows中有特殊含义，不能出现在文件名中。系统保留名：CON（控制台）、PRN（打印机）、AUX（辅助设备）等，即使加扩展名也不能用，如\"CON.txt\"也是非法的。文件名中可以有多个点，最后一个点后面的是扩展名，如\"report.final.docx\"的扩展名是docx。\n\n【常见错误】\n1. 文件名中用了非法字符——尤其容易用*、?、/、|等，这些在Windows中不允许。\n2. 以为文件名区分大小写——Windows文件名不区分大小写，\"File.txt\"和\"file.txt\"是同一个文件。\n3. 给文件起名用保留设备名——如\"CON.txt\"\"PRN.doc\"会导致无法创建文件。\n\n【出题方向】\n常考选择题\"下列文件名合法的是\"（给出几个选项判断）。也常考填空题\"Windows文件名中不能包含的字符有____\"（\\ / : * ? \" < > |）。判断题\"Windows文件名区分大小写\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(684,676,4,4,'文件夹与路径','# 文件夹与路径\n\n【一句话定义】\n文件夹是用来组织和管理磁盘文件的容器，采用树状层次结构；路径是指从根目录到目标文件所经过的文件夹序列，如\"C:\\Users\\Admin\\Desktop\\文件.txt\"。\n\n【具体例子】\n文件夹像抽屉里的隔板——C盘是抽屉，里面分\"Users\"\"Program Files\"\"Windows\"等文件夹（第一层），Users文件夹里又分\"Admin\"\"Public\"等用户文件夹（第二层），Admin里又有\"Desktop\"\"Documents\"\"Downloads\"等（第三层）。这种一层套一层的结构叫\"树状结构\"。路径就是地址——\"C:\\Users\\Admin\\Desktop\"表示C盘→Users文件夹→Admin文件夹→Desktop文件夹。相对路径是相对于当前位置的路径，如在Desktop文件夹里，\"文件.txt\"就是相对路径。\n\n【常见错误】\n1. 以为文件夹没有大小——文件夹本身不占空间（只是\"标签\"），里面文件才占空间。\n2. 路径中的\\和/搞混——Windows用反斜杠\\（如C:\\Users），网址用斜杠/（如http://）。\n3. 同一文件夹下同名——同一文件夹中不能有同名文件或文件夹，不同文件夹可以。\n\n【出题方向】\n常考填空题\"Windows文件夹的组织结构是____\"（树状结构）。也常考选择题\"下列路径表示正确的是\"（C:\\Users\\Admin）。判断题\"不同文件夹中可以有同名文件\"（对）。实操题\"在D盘创建文件夹结构：D:\\学习\\语文\\作文，并在最内层创建一个文本文件\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(685,676,4,4,'文件属性','# 文件属性\n\n【一句话定义】\nWindows 7文件属性包括只读（R，只能读不能修改）、隐藏（H，默认不显示）、存档（A，标记是否备份过）和系统（S，系统文件），可通过右键→属性查看和修改。\n\n【具体例子】\n只读属性：你给老师交的作业设为只读，老师能打开看但不能修改评分（防止误改）。隐藏属性：系统文件如pagefile.sys（虚拟内存文件）默认隐藏，防止用户误删。修改属性方法：右击文件→属性→勾选/取消相应属性。显示隐藏文件：资源管理器→组织→文件夹和搜索选项→查看→勾选\"显示隐藏的文件、文件夹和驱动器\"。\n\n【应会操作】设置文件属性的完整操作路径：\n第一步：选中文件或文件夹→右键→选择\"属性\"→打开属性对话框。\n第二步：在\"常规\"选项卡中设置基本属性：\n  - 只读（R）：勾选后文件只能读取不能修改（防止误修改）。\n  - 隐藏（H）：勾选后文件不在普通视图中显示（用于保护系统文件）。\n第三步：点击\"高级\"按钮→可设置\"存档\"属性（标记文件是否已备份）和\"索引\"属性→点击\"确定\"。\n第四步：点击\"确定\"或\"应用\"保存属性设置。\n\n显示隐藏文件的操作路径：资源管理器→点击\"组织\"→\"文件夹和搜索选项\"→\"查看\"选项卡→选择\"显示隐藏的文件、文件夹和驱动器\"→取消勾选\"隐藏受保护的操作系统文件\"→点击\"确定\"。\n\n【常见错误】\n1. 只读属性以为是密码保护——只读只是防止修改，不是加密，任何人都能取消只读属性。\n2. 隐藏文件以为丢了——其实只是看不见了，勾选\"显示隐藏文件\"就能找到。\n3. 系统属性随便修改——系统文件一般不要动，修改可能导致系统不稳定。\n\n【出题方向】\n常考选择题\"表示文件只能读取不能修改的属性是\"（只读）。也常考填空题\"文件的四种属性是____、____、____和____\"（只读、隐藏、存档、系统）。实操题\"将指定文件设置为只读属性，并尝试修改验证效果\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(686,676,4,4,'桌面组成','# 桌面组成\n\n【一句话定义】\nWindows 7启动后的整个屏幕称为桌面，由桌面背景、任务栏和图标三部分组成，实质是\"C:\\Users\\当前用户名\\Desktop\"文件夹。\n\n【具体例子】\n开机后看到的整个屏幕就是桌面——中间那张壁纸叫桌面背景（可以换成自己喜欢的图片）；底部那条横杠是任务栏（显示开始按钮、打开的程序、时间等）；上面各种小图案是图标（如\"计算机\"\"回收站\"\"网络\"）。桌面上的文件其实都存在C盘Users文件夹下你的用户名文件夹里的Desktop子文件夹中。在机房上课，如果你把文件放在桌面，换一台电脑就看不到了（因为每台电脑的C盘不同）。\n\n【应会操作】设置桌面的完整操作路径：\n第一步：右击桌面空白处→选择\"个性化\"（或控制面板→外观和个性化→个性化）。\n第二步：设置桌面背景→点击\"桌面背景\"→选择图片→设置图片位置（填充/适应/拉伸/平铺/居中）→点击\"保存修改\"。\n第三步：设置屏幕保护程序→点击\"屏幕保护程序\"→选择程序（如气泡/彩带/三维文字）→设置等待时间→勾选\"在恢复时显示登录屏幕\"→点击\"确定\"。\n第四步：设置桌面图标→点击左侧\"更改桌面图标\"→勾选要在桌面显示的图标（计算机/网络/回收站/用户的文件/控制面板）→点击\"确定\"。\n\n【常见错误】\n1. 以为桌面文件存在显示器里——实际上存在硬盘C盘，显示器只是显示出来。\n2. 删除桌面图标就等于卸载程序——删除的只是快捷方式（指针），真正的程序还在硬盘里。\n3. 桌面文件越多开机越慢——桌面上放太多大文件会占用内存影响启动速度。\n\n【出题方向】\n常考填空题\"Windows 7的桌面由____、____和____三部分组成\"（桌面背景、任务栏、图标）。也常考判断题\"桌面上的文件实际存储在内存中\"（错，存在硬盘）。实操题\"将桌面背景更换为指定图片，并设置显示方式为\'填充\'\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(687,676,4,4,'窗口组成与操作','# 窗口组成与操作\n\n【一句话定义】\nWindows 7窗口由标题栏、菜单栏、工作区、状态栏和边框组成；窗口操作包括移动、改变大小、最大化、最小化、关闭、切换活动窗口和排列窗口。\n\n【具体例子】\n打开\"计算机\"看到的框就是窗口：最上面是标题栏（显示\"计算机\"和控制按钮）；下面是菜单栏（文件、编辑、查看、工具、帮助）；中间大片空白是工作区（显示内容）；底部是状态栏（显示项目数量）；边缘是边框（可拖动改变大小）。窗口操作：①移动——把鼠标放在标题栏上按住拖动；②最大化/还原——双击标题栏或点击右上角按钮；③最小化——缩到任务栏；④关闭——点×按钮或Alt+F4；⑤切换——Alt+Tab或点任务栏按钮；⑥排列——右击任务栏→层叠/堆叠/并排显示。活动窗口：标题栏高亮且不被遮挡的窗口，一个时间只有一个。\n\n【应会操作】窗口操作的完整操作路径：\n最大化：双击标题栏→或点击右上角最大化按钮→或Win+↑方向键。\n最小化：点击最小化按钮→窗口缩小到任务栏；点击任务栏按钮可恢复。\n关闭窗口：点击关闭按钮（X）→或Alt+F4→或双击左上角控制菜单图标。\n移动窗口：拖拽标题栏到目标位置（最大化状态下需先双击标题栏还原）。\n改变大小：将鼠标移到窗口边框或角落→指针变成双向箭头→拖拽调整（最大化状态下需先还原）。\n窗口排列：右击任务栏空白处→选择\"层叠窗口\"/\"堆叠显示窗口\"/\"并排显示窗口\"。\n切换窗口：Alt+Tab（切换所有窗口）→Win+Tab（3D翻转切换）→单击任务栏上的窗口按钮→单击窗口可见部位。\n\n对话框与窗口的区别：对话框可以移动但不能改变大小（没有最大化/最小化按钮，部分不能调整大小）。\n\n【常见错误】\n1. 最大化后找不到还原按钮——最大化按钮会变成\"还原\"按钮（两个重叠方块），点一下恢复。\n2. 窗口拖出屏幕外找不回来——按Alt+空格→移动，用方向键把窗口移回来。\n3. 以为关闭按钮和最小化一样——关闭是退出程序，最小化还在后台运行。\n\n【出题方向】\n常考实操题\"打开\'计算机\'窗口，完成移动、最大化、最小化、关闭等操作\"。也常考填空题\"窗口由____、____、____、____和____组成\"（标题栏、菜单栏、工作区、状态栏、边框）。选择题\"切换活动窗口的快捷键是\"（Alt+Tab）。判断题\"双击标题栏可以在最大化和还原之间切换\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(688,676,4,4,'获取帮助信息的方法','# 获取帮助信息的方法\n\n【一句话定义】\nWindows系统提供了多种获取帮助的途径，包括F1键调用帮助中心、开始菜单搜索、对话框中的帮助按钮、微软官方支持网站等，帮助用户解决使用中遇到的问题。\n\n【具体说明】\nF1键帮助：在Windows桌面按F1键打开\"Windows帮助和支持\"窗口；在大多数应用程序中按F1键打开该软件的帮助文档。帮助窗口中可以搜索关键词查找相关帮助主题。\n\n开始菜单搜索帮助：点击开始菜单→在搜索框中输入关键词（如\"如何更改桌面背景\"）→系统会显示相关帮助主题和设置入口。\n\n对话框中的帮助按钮：部分对话框右上角有一个\"?\"按钮（帮助按钮），点击后再点击对话框中的某个元素，可以查看该元素的说明。也可以直接按F1键在对话框中打开帮助。\n\n工具提示（Tooltip）：将鼠标指针悬停在按钮、图标或菜单项上片刻，会自动显示简短的说明文字（工具提示），这是最快捷的获取即时帮助的方式。\n\n微软官方支持：浏览器访问support.microsoft.com，可以搜索Windows相关问题的解决方案，包含详细的文章、视频教程和社区论坛。\n\n其他帮助方式：①程序菜单中的\"帮助\"菜单项；②右键菜单中的\"这是什么？\"选项；③命令提示符中输入命令+/参数查看帮助（如dir /?）。\n\n【常见错误】\n1. 不知道F1是帮助键——遇到问题时只会上网搜索，忽略了系统自带的帮助文档。\n2. 不会使用对话框的帮助按钮——点击\"?\"后再点击不理解的选项，可以直接查看说明。\n3. 网上搜索的答案不可靠——优先使用微软官方支持网站，避免被错误信息误导。\n\n【出题方向】\n常考选择题\"在Windows中，获取帮助的快捷键是____\"（F1）。填空题\"将鼠标悬停在工具栏按钮上片刻会显示____\"（工具提示/Tooltip）。判断题\"在大多数Windows应用程序中按F1键可以打开帮助文档\"（对）。简答题\"列举3种获取Windows帮助信息的方法\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(689,676,4,4,'菜单类型与命令约定','# 菜单类型与命令约定\n\n【一句话定义】\nWindows 7菜单有三种形式：开始菜单、下拉菜单和快捷菜单（右键菜单）；菜单命令有灰色不可用、复选标记√、单选标记●、级联箭头▶、省略号…等约定。\n\n【具体例子】\n三种菜单：开始菜单（点击开始按钮）、下拉菜单（点击菜单栏上的\"文件\"\"编辑\"等）、快捷菜单（右击桌面或文件弹出）。菜单约定含义：①灰色显示——当前不可用（如没选中文字时\"复制\"是灰色的）；②前有√——复选标记，可在两种状态间切换（如视图→状态栏，打勾显示状态栏，去掉隐藏）；③前有●——单选标记，同一组只能选一个（如视图→大图标/小图标）；④后有▶——有子菜单（鼠标悬停展开）；⑤后有…——会打开对话框（需要进一步设置）；⑥带下划线字母——热键，按Alt+字母可执行（如Alt+F打开文件菜单）。\n\n【常见错误】\n1. 灰色菜单以为是程序坏了——其实是当前条件不满足，比如没有选中内容时\"复制\"就是灰色的。\n2. 复选√和单选●搞混——√可以多个同时选（多选），●同一组只能选一个（单选）。\n3. 不知道省略号…的含义——菜单项后面有…表示会弹出对话框，没有…表示直接执行。\n\n【出题方向】\n常考选择题\"菜单命令呈灰色表示\"（该命令当前不可用）。也常考填空题\"菜单命令前有\'√\'标记表示____\"（该命令被选中/复选状态）。判断题\"菜单命令后有\'…\'表示直接执行\"（错，表示会打开对话框）。实操题\"在Word中设置视图显示方式为大图标，观察单选标记的变化\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(690,676,4,4,'通配符','# 通配符\n\n【一句话定义】\n通配符是在搜索或命令中代替一个或多个字符的特殊符号，Windows中*代表任意多个字符，?代表任意一个字符。\n\n【具体例子】\n搜索文件时：输入\"*.docx\"能找到所有Word文档；输入\"报告*.xlsx\"能找到\"报告1.xlsx\"\"报告2024.xlsx\"等以\"报告\"开头的Excel文件；输入\"照片?.jpg\"能找到\"照片1.jpg\"\"照片2.jpg\"但不能找到\"照片10.jpg\"（因为?只代表一个字符）。在CMD命令中也常用：DIR *.txt 列出所有文本文件，DEL  temp?.tmp 删除temp1.tmp、temp2.tmp等。搜索时\"计算机*\"能找到\"计算机基础.doc\"\"计算机网络.pdf\"等所有以\"计算机\"开头的文件。\n\n【常见错误】\n1. *和?搞混——*代表任意多个字符（0个也行），?只能代表一个字符。\n2. 以为通配符只能在搜索框用——CMD命令（DIR、DEL等）中也广泛使用。\n3. 搜索时用了通配符但范围太大——\"*.docx\"会搜出大量文件，最好配合文件夹路径缩小范围。\n\n【出题方向】\n常考选择题\"在Windows中，*代表____\"（任意多个字符）、\"?代表____\"（任意一个字符）。也常考填空题\"搜索所有以\'成绩\'开头的Excel文件，应输入____\"（成绩*.xlsx）。判断题\"通配符*可以代表零个或多个字符\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(691,676,4,4,'键盘快捷键','# 键盘快捷键\n\n【一句话定义】\n键盘快捷键是不通过菜单直接按组合键执行命令的方式，常用快捷键包括Ctrl+C复制、Ctrl+V粘贴、Ctrl+X剪切、Ctrl+Z撤销、Ctrl+A全选、Alt+F4关闭窗口、F1帮助等。\n\n【具体例子】\n文件操作：Ctrl+C复制（先选中文件）、Ctrl+X剪切、Ctrl+V粘贴、Ctrl+A全选、Delete删除（到回收站）、Shift+Delete永久删除（不经过回收站）。窗口操作：Alt+F4关闭当前窗口、Alt+Tab切换窗口、Win+D显示桌面、Win+E打开资源管理器。文本编辑：Ctrl+Z撤销、Ctrl+Y恢复、Ctrl+S保存、Ctrl+P打印、Ctrl+F查找、Ctrl+H替换。程序启动：Win+R打开运行对话框（输入notepad打开记事本、calc打开计算器）。\n\n【常见错误】\n1. Ctrl+X和Ctrl+C搞混——X是剪切（原位置消失），C是复制（原位置还在）。\n2. Delete和Shift+Delete搞混——Delete删除到回收站（可恢复），Shift+Delete永久删除（不可恢复）。\n3. 快捷键记不住——最常用的记牢：复制粘贴剪切（C/V/X）、保存（S）、撤销（Z）、全选（A）。\n\n【出题方向】\n常考选择题\"复制文件的快捷键是\"（Ctrl+C）、\"永久删除文件的快捷键是\"（Shift+Delete）。也常考填空题\"切换窗口的快捷键是____\"（Alt+Tab）。判断题\"Ctrl+Z的功能是撤销\"（对）。实操题\"使用快捷键完成文件复制、粘贴和删除操作\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(692,676,4,4,'鼠标操作','# 鼠标操作\n\n【一句话定义】\nWindows 7中常用的鼠标操作包括：单击（选中）、双击（打开）、右击（弹出快捷菜单）、拖拽（移动或复制）、滚轮滚动（上下翻页）。\n\n【具体例子】\n单击左键：选中文件或执行按钮。双击左键：打开文件或程序（注意：双击速度可在控制面板调整，太快会变成两次单击）。右击：弹出快捷菜单（复制、粘贴、删除、重命名、属性等），是最常用的操作之一。拖拽：按住左键不放拖动文件——同一分区拖拽是移动，不同分区拖拽是复制（按住Ctrl拖拽强制复制，按住Shift拖拽强制移动）。滚轮：在网页或文档中上下滚动；按下滚轮（中键）进入滚动模式，鼠标移动即可滚动。\n\n【常见错误】\n1. 双击变单击——双击间隔时间太长，系统识别为两次单击，在控制面板可调快双击速度。\n2. 拖拽文件不知道会移动还是复制——看有没有小图标提示，同分区移动、跨分区复制。\n3. 不会用中键——按下滚轮可以进入滚动模式，在浏览长网页时很方便。\n\n【出题方向】\n常考选择题\"在同一磁盘分区中拖拽文件是____操作\"（移动）、\"在不同磁盘分区中拖拽文件是____操作\"（复制）。也常考判断题\"右击桌面可以弹出快捷菜单\"（对）。实操题\"用鼠标完成选中、打开、复制、移动文件的操作\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(693,675,4,3,'任务1初识Windows',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(694,693,4,4,'01_操作系统概念与地位','# 知识点：操作系统概念与地位\n\n## 一句话定义\n\n操作系统（Operating System，OS）是管理和控制计算机硬件与软件资源的计算机程序，是直接运行在\"裸机\"上最基本的系统软件，任何其他软件都必须在操作系统的支持下才能运行。\n\n## 具体说明\n\n### 操作系统的核心地位\n\n操作系统在计算机系统中处于承上启下的核心地位，可以从两个维度理解：\n\n**1. 用户与计算机的接口**\n- 操作系统为用户提供了良好的人机接口（界面），使用户无需直接面对复杂的硬件，就能方便地使用计算机\n- 用户通过操作系统提供的命令、菜单、图形界面等方式与计算机交互\n- 操作系统屏蔽了硬件的复杂性，使计算机系统更易使用\n\n**2. 硬件与软件的接口**\n- 操作系统是计算机硬件上第一层软件，是最基本的系统软件\n- 所有应用软件都必须运行在操作系统之上，依赖操作系统提供的资源和服务\n- 操作系统负责管理计算机的各种硬件资源（CPU、内存、硬盘、打印机等），合理调度，使其高效协调工作\n\n### 操作系统的作用总结\n\n| 作用 | 说明 |\n|------|------|\n| 资源管理者 | 管理和分配CPU、内存、外存、I/O设备等资源 |\n| 用户接口 | 提供命令行或图形界面，方便用户使用计算机 |\n| 工作流程组织者 | 合理组织计算机系统的工作流程，改善系统性能 |\n| 软硬件翻译 | 将用户的操作指令翻译成硬件能执行的命令 |\n\n### 生活中的类比\n\n操作系统就像学校的教务处：学生（用户）通过教务处（操作系统）来申请教室（内存）、借用设备（I/O设备）、提交作业（程序运行），教务处负责协调和分配学校的各种资源。\n\n## 常见错误\n\n| 错误认知 | 正确理解 |\n|----------|----------|\n| 操作系统是应用软件 | 操作系统是系统软件，不是应用软件 |\n| 操作系统可有可无 | 没有操作系统，计算机无法正常运行，应用软件也无法运行 |\n| 操作系统只管理硬件 | 操作系统同时管理硬件资源和软件资源 |\n| 只有Windows才是操作系统 | 操作系统有多种，Windows只是其中之一 |\n\n## 出题方向\n\n- **判断题**：操作系统是用户和计算机的接口，也是硬件和软件的接口。（√）\n- **选择题**：下列软件中，属于系统软件的是（ ）。A. Word  B. 操作系统  C. 浏览器  D. 游戏\n- **填空题**：操作系统是管理和控制计算机______与______资源的计算机程序。\n- **简答题**：简述操作系统在计算机系统中的地位。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(695,693,4,4,'02_操作系统五大功能','# 知识点：操作系统五大功能\n\n## 一句话定义\n\n操作系统的主要功能包括作业管理、文件管理、存储管理、设备管理以及进程管理五大功能，这五大功能共同协作，确保计算机系统高效、稳定地运行。\n\n## 具体说明\n\n### 五大功能总览\n\n| 功能名称 | 核心职责 | 管理对象 |\n|----------|----------|----------|\n| 作业管理 | 对作业的运行进行组织与控制 | 用户提交的任务 |\n| 文件管理 | 对文件进行组织、存储、检索、共享和保护 | 外存中的文件 |\n| 存储管理 | 对内存空间进行分配、回收和保护 | 内存（RAM） |\n| 设备管理 | 对I/O设备进行分配、控制和回收 | 输入/输出设备 |\n| 进程管理 | 对CPU的分配和运行进行管理 | 进程/处理机 |\n\n### 各功能简述\n\n**1. 作业管理**\n- 根据系统条件和用户需要，对作业的运行进行合理的组织及相应控制\n- 包括作业调度（选择作业进入系统）和作业控制（控制作业执行过程）\n- 类比：工厂的生产调度员安排生产任务\n\n**2. 文件管理**\n- 计算机系统中大量信息以文件形式存放在外存中\n- 操作系统负责文件的创建、删除、读写、命名、保护等操作\n- 文件管理又称为信息管理，操作系统的文件系统作为信息管理的接口\n\n**3. 存储管理**\n- 实质上是对存储空间的管理，主要是指对内存的管理\n- 为多道程序的并发运行提供良好环境\n- 提高存储器的利用率，为尽量多的用户程序提供服务\n\n**4. 设备管理**\n- 为用户程序分配I/O设备\n- 完成用户程序请求的I/O操作\n- 提高CPU和I/O设备的利用率，改善人机界面\n- 具有缓冲管理、设备分配、设备处理和虚拟设备等功能\n\n**5. 进程管理**\n- 也称为处理机管理，是对处理机的分配和运行实施有效管理\n- 具有进程控制、进程同步、进程通信和进程调试的功能\n- 确保CPU时间被合理分配给各个运行的程序\n\n## 常见错误\n\n| 错误认知 | 正确理解 |\n|----------|----------|\n| 操作系统只有三大功能 | 操作系统有五大功能 |\n| 文件管理就是管理文件夹 | 文件管理包括文件的存储、检索、共享和保护等 |\n| 存储管理就是管理硬盘 | 存储管理主要指对内存的管理 |\n| 进程管理和作业管理是一回事 | 进程管理是对CPU的管理，作业管理是对用户任务的管理 |\n\n## 出题方向\n\n- **填空题**：操作系统的主要功能包括______管理、______管理、______管理、______管理和______管理五大功能。\n- **选择题**：下列不属于操作系统主要功能的是（ ）。A. 作业管理  B. 病毒查杀  C. 设备管理  D. 进程管理\n- **判断题**：操作系统的存储管理主要是指对硬盘空间的管理。（×，主要是对内存的管理）\n- **简答题**：列举操作系统的五大功能，并简述其中任意两种功能的含义。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(696,693,4,4,'03_作业管理','# 知识点：作业管理\n\n## 一句话定义\n\n作业管理是操作系统的主要功能之一，其主要任务是根据系统条件和用户需要，对作业的运行进行合理的组织及相应控制，包括作业调度和作业控制两大功能。\n\n## 具体说明\n\n### 什么是\"作业\"\n\n作业是用户提交给计算机系统的一个独立任务单位。例如：\n- 打印一份文档\n- 编译一个程序\n- 计算一组数据\n- 备份一批文件\n\n### 作业管理的两大功能\n\n**1. 作业调度**\n- 决定哪些作业可以进入系统运行\n- 在多道程序环境下，从后备作业队列中选择若干作业调入内存\n- 调度的目标是提高系统效率和资源利用率\n\n**2. 作业控制**\n- 对已进入系统的作业进行控制和监督\n- 控制作业的执行顺序、资源分配、异常处理\n- 确保作业按照用户要求正确完成\n\n### 作业管理的工作流程\n\n```\n用户提交作业 → 作业进入后备队列 → 作业调度（选择作业）→ 作业进入内存运行 → 作业控制（监控执行）→ 作业完成\n```\n\n### 生活类比\n\n作业管理就像医院的挂号系统：病人（作业）到挂号处排队（后备队列），护士（调度程序）根据诊室情况和病人病情安排就诊顺序（调度），医生治疗过程中护士全程跟踪服务（控制）。\n\n## 常见错误\n\n| 错误认知 | 正确理解 |\n|----------|----------|\n| 作业管理就是管理文件 | 作业管理管理的是用户提交的任务/作业 |\n| 作业调度就是进程调度 | 作业调度是选择作业进入系统，进程调度是分配CPU时间 |\n| 作业管理与用户无关 | 作业管理正是根据用户需求来组织作业运行的 |\n\n## 出题方向\n\n- **填空题**：作业管理包括______和______两大功能。\n- **选择题**：作业调度的主要目的是（ ）。A. 删除作业  B. 决定哪些作业可以进入系统运行  C. 格式化磁盘  D. 安装软件\n- **判断题**：作业管理的主要任务是根据系统条件和用户需要，对作业的运行进行合理的组织及相应控制。（√）\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(697,693,4,4,'04_文件管理','# 知识点：文件管理\n\n## 一句话定义\n\n文件管理是操作系统的主要功能之一，又称为信息管理，负责计算机系统中大量信息的组织、存储、检索、共享和保护，使用户能够方便地存取外存中的文件。\n\n## 具体说明\n\n### 文件管理的核心职责\n\n**1. 文件组织**\n- 确定文件在外存中的存放方式\n- 建立目录结构，方便文件分类和查找\n- 常见的文件组织方式：连续存放、链接存放、索引存放\n\n**2. 文件存储**\n- 管理外存（硬盘、U盘等）的存储空间\n- 为文件分配存储空间\n- 回收已删除文件的存储空间\n\n**3. 文件检索**\n- 提供按文件名查找文件的机制\n- 支持通配符搜索（如*.txt）\n- 记录文件的位置信息，快速定位\n\n**4. 文件共享**\n- 允许多个用户或程序同时使用同一文件\n- 设置共享权限（只读、读写等）\n\n**5. 文件保护**\n- 防止文件被非法访问或篡改\n- 通过设置文件属性（只读、隐藏等）实现保护\n- 提供文件备份和恢复机制\n\n### 文件系统的作用\n\n操作系统的文件系统作为信息管理的接口，是用户与外存之间的桥梁。用户通过文件系统来：\n- 创建新文件\n- 打开已有文件\n- 读写文件内容\n- 删除不需要的文件\n- 设置文件属性\n\n## 常见错误\n\n| 错误认知 | 正确理解 |\n|----------|----------|\n| 文件管理就是管理文件夹 | 文件管理涵盖文件的存储、检索、共享和保护等多方面 |\n| 文件管理是对内存的管理 | 文件管理主要是对外存（硬盘等）中的信息进行管理 |\n| 删除文件就是彻底清除 | 删除文件通常只是标记删除，数据仍可恢复 |\n\n## 出题方向\n\n- **填空题**：文件管理又称为______管理，计算机系统中大量信息以______形式存放在外存中。\n- **选择题**：操作系统的文件系统主要作为（ ）的接口。A. 用户与内存  B. 用户与信息管理  C. 硬件与软件  D. CPU与硬盘\n- **判断题**：文件管理的主要任务是管理和控制计算机内存中的数据。（×，主要是外存中的文件）\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(698,693,4,4,'05_存储管理','# 知识点：存储管理\n\n## 一句话定义\n\n存储管理是操作系统的主要功能之一，实质上是对存储空间的管理，主要是指对内存的管理，其主要任务是为多道程序的并发运行提供良好环境，提高存储器的利用率。\n\n## 具体说明\n\n### 存储管理的核心任务\n\n**1. 内存分配**\n- 为每个运行的程序分配所需的内存空间\n- 记录哪些内存已被使用，哪些内存空闲\n- 程序结束后回收其占用的内存空间\n\n**2. 地址映射**\n- 将程序中的逻辑地址转换为内存中的物理地址\n- 每个程序认为自己从地址0开始运行，实际被映射到不同物理位置\n\n**3. 内存保护**\n- 防止一个程序访问或修改其他程序的内存空间\n- 防止用户程序访问操作系统的内存区域\n- 确保多道程序互不干扰\n\n**4. 虚拟内存**\n- 利用硬盘空间模拟扩展内存容量\n- 使程序可以使用比实际物理内存更大的地址空间\n- 提高多道程序运行的能力\n\n### 为什么需要存储管理\n\n如果没有存储管理：\n- 多个程序可能同时写入同一内存地址，导致数据混乱\n- 一个程序可能覆盖操作系统或其他程序的数据\n- 内存空间浪费严重\n- 大程序无法在小内存中运行\n\n### 存储管理与文件管理的区别\n\n| 对比项 | 存储管理 | 文件管理 |\n|--------|----------|----------|\n| 管理对象 | 内存（RAM） | 外存（硬盘、U盘等） |\n| 数据特点 | 易失性（断电丢失） | 持久性（断电保存） |\n| 访问速度 | 快 | 慢 |\n| 主要任务 | 为程序运行分配内存空间 | 组织和管理文件信息 |\n\n## 常见错误\n\n| 错误认知 | 正确理解 |\n|----------|----------|\n| 存储管理就是管理硬盘 | 存储管理主要是指对内存的管理 |\n| 存储管理和文件管理是一回事 | 两者管理对象不同，存储管内存，文件管外存 |\n| 内存越大存储管理越不重要 | 无论内存大小，都需要存储管理来合理分配和保护 |\n\n## 出题方向\n\n- **填空题**：存储管理实质上是对______的管理，主要是指对______的管理。\n- **选择题**：下列关于存储管理的描述，正确的是（ ）。A. 管理硬盘空间  B. 管理内存空间  C. 管理CPU  D. 管理网络\n- **判断题**：存储管理的主要任务是为多道程序的并发运行提供良好环境。（√）\n- **简答题**：简述存储管理的主要任务。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(699,693,4,4,'Windows7的版本与特点','# Windows 7的版本与特点\n\n【一句话定义】\nWindows 7有6个版本（Starter入门版、Home Basic家庭普通版、Home Premium家庭高级版、Professional专业版、Enterprise企业版、Ultimate旗舰版），特点包括更快响应、改进任务栏、跳转列表、更好的设备管理等。\n\n【具体例子】\n版本选择：学校机房一般用Professional（专业版），功能全面支持域管理；家用电脑多是Home Premium（家庭高级版），有Aero玻璃特效和媒体中心；Ultimate（旗舰版）功能最全但最贵；Starter（入门版）功能最少，低配上网本用。Windows 7的Aero特效让窗口边框有半透明玻璃效果；任务栏上的程序可以\"锁定\"（即使没打开也显示在任务栏上，像快捷方式）；跳转列表功能——右击任务栏上的Word图标，可以直接看到最近打开的文档列表。安装要求：1GHz以上CPU、1GB以上内存（32位）/2GB（64位）、16GB以上硬盘空间。\n\n【常见错误】\n1. 版本从高到低排序搞错——从高到低：Ultimate > Enterprise > Professional > Home Premium > Home Basic > Starter。\n2. 32位和64位的内存要求搞混——32位系统最多认4GB内存，64位系统要求至少2GB内存。\n3. 认为Windows 7是最新系统——实际上Windows 7已停止支持，最新的是Windows 11。\n\n【出题方向】\n常考选择题\"Windows 7的最高版本是\"（Ultimate旗舰版）、\"32位Windows 7最低要求内存是\"（1GB）。也常考填空题\"Windows 7的版本从低到高依次为Starter、____、____、____、____、____\"（Home Basic、Home Premium、Professional、Enterprise、Ultimate）。判断题\"Windows 7的Professional版本支持域管理\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(700,693,4,4,'Windows安全模式','# Windows安全模式\n\n【一句话定义】\nWindows安全模式是一种诊断启动模式，仅加载最基本的系统驱动程序和服务，不加载第三方软件和多余的驱动，用于在系统出现故障时排查问题、修复错误。\n\n【具体说明】\n进入方式（Windows 7）：重启计算机→在开机自检后、Windows启动画面出现前反复按F8键→进入\"高级启动选项\"界面→选择\"安全模式\"或\"带网络连接的安全模式\"或\"带命令提示符的安全模式\"。\n\n三种安全模式：①安全模式——只加载最基本的驱动和服务，分辨率低（800×600），桌面四角显示\"安全模式\"字样；②带网络连接的安全模式——在安全模式基础上增加网络驱动，可以上网下载修复工具；③带命令提示符的安全模式——不加载图形界面，直接进入CMD命令行。\n\n主要用途：①系统无法正常启动时进入安全模式排查原因；②卸载无法正常卸载的软件或驱动；③查杀顽固病毒和木马（病毒在安全模式下通常不会自启动）；④修复系统文件（如用sfc /scannow命令）；⑤还原系统到之前的还原点；⑥修改被病毒锁定的注册表项。\n\n安全模式特点：屏幕分辨率固定为800×600且不可更改；部分硬件功能不可用；无法播放音频视频；网络功能视进入方式而定。\n\n【常见错误】\n1. F8按的时机不对——必须在BIOS自检完成后、Windows徽标出现之前按F8，太早或太晚都不行。\n2. 在安全模式下安装软件——安全模式不适合日常使用，仅用于排错，完事后应正常重启。\n3. 不知道有\"带网络的安全模式\"——需要下载修复工具时必须选择带网络连接的版本。\n\n【出题方向】\n常考选择题\"Windows安全模式的进入快捷键是____\"（F8）。填空题\"安全模式仅加载____的系统驱动程序和服务\"（最基本/最小集）。判断题\"在安全模式下可以正常玩游戏和播放视频\"（错）。简答题\"简述Windows安全模式的作用及进入方法\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(701,693,4,4,'Windows操作系统的安装','# Windows操作系统的安装\n\n【一句话定义】\n安装Windows操作系统需要使用安装光盘或U盘启动盘，通过BIOS设置从安装介质启动，按照安装向导完成分区、格式化、系统文件复制、用户设置等步骤。\n\n【具体操作步骤】\n第一步：准备安装介质。制作U盘启动盘（用UltraISO或微软官方工具将系统ISO写入U盘）或使用系统安装光盘。\n\n第二步：BIOS设置启动顺序。开机按Delete/F2/F10键进入BIOS→找到Boot菜单→将第一启动项设为USB（U盘安装）或CD-ROM（光盘安装）→按F10保存退出。\n\n第三步：启动安装程序。计算机从安装介质启动→出现\"Press any key to boot from CD/USB...\"提示时按任意键→进入Windows安装界面。\n\n第四步：安装设置。①选择语言、时间和货币格式、键盘输入法（默认中文简体）→②点击\"现在安装\"→③输入产品密钥（或选择跳过）→④选择要安装的版本（家庭版/专业版等）→⑤阅读并接受许可条款。\n\n第五步：磁盘分区。选择安装类型\"自定义（高级）\"→在磁盘分区界面：\n- 如果是新硬盘：点击\"驱动器选项（高级）\"→新建→输入分区大小→应用\n- 如果已有分区：选择要安装的分区（通常是C盘），可格式化后安装\n- 注意：系统盘建议至少分配50GB空间\n\n第六步：开始安装。选择分区后点击\"下一步\"→系统自动完成复制文件、展开文件、安装功能、安装更新等过程（约15-30分钟，期间会自动重启数次）。\n\n第七步：首次设置。①设置用户名和计算机名→②设置登录密码→③输入产品密钥（如果之前跳过了）→④选择Windows更新设置→⑤设置日期和时间→⑥选择网络位置（家庭网络/工作网络/公用网络）。\n\n【常见错误】\n1. BIOS启动顺序没设置对——电脑直接从硬盘启动，跳过了安装介质。需进BIOS调整Boot Priority。\n2. 安装时没选对分区——误将系统装到数据分区，导致数据丢失。安装前应备份重要数据。\n3. 产品密钥输入错误——密钥中的字母和数字容易混淆（如B和8、O和0），建议直接复制粘贴。\n\n【出题方向】\n常考选择题\"安装Windows时，需要在____中设置第一启动项为USB或CD-ROM\"（BIOS）。填空题\"安装Windows操作系统的过程中，磁盘分区步骤应在____阶段完成\"（自定义安装/高级选项）。判断题\"安装Windows时可以不输入产品密钥先跳过，安装后再激活\"（对）。简答题\"简述从U盘安装Windows操作系统的基本步骤\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(702,693,4,4,'主流操作系统','# 主流操作系统\n\n【一句话定义】\n主流操作系统包括Windows（微软，个人PC最常用）、Unix（贝尔实验室，服务器稳定可靠）、Linux（开源免费，服务器和嵌入式）、MacOS（苹果）以及移动端Android和鸿蒙OS。\n\n【具体例子】\n学校机房装的Windows 7就是微软的操作系统——图形界面友好、软件兼容性强。银行的服务器常用Unix或Linux——运行稳定几个月不重启。你用的安卓手机是Android系统（基于Linux内核），华为手机很多已升级到鸿蒙OS——可以在手机、平板、手表、电视上无缝协作。MacOS是苹果电脑专用，界面美观但只能装在苹果硬件上。Linux有很多发行版：Ubuntu适合初学者、CentOS适合服务器、红旗Linux是中国开发的版本。记住一个规律：个人电脑Windows占主流，服务器Linux/Unix占主流，手机Android占主流。\n\n【常见错误】\n1. 认为Windows是唯一的操作系统——实际上Linux在服务器领域占有率很高，Android在手机领域占主流。\n2. Android和Linux搞混——Android是基于Linux内核开发的移动操作系统，二者不是同一个东西。\n3. 鸿蒙OS和Android搞混——鸿蒙OS是华为自主研发的分布式操作系统，不是Android的换皮版。\n\n【出题方向】\n常考选择题\"目前个人PC使用最广泛的操作系统是\"（Windows）、\"属于开源操作系统的是\"（Linux）。也常考填空题\"华为公司开发的操作系统是____\"（鸿蒙OS）。判断题\"Android是基于Linux内核开发的操作系统\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(703,693,4,4,'操作系统的分类','# 操作系统的分类\n\n【一句话定义】\n按处理模式分为批处理系统、分时系统、实时系统、分布式系统和网络操作系统；按用户数分为单用户和多用户操作系统。\n\n【具体例子】\n批处理系统像食堂大锅饭——把一批任务（如全校学生的饭卡充值数据）收集起来，一次性集中处理，适合处理周期性大笔数据，但不适合实时需求。分时系统像ATM机——多个用户轮流使用CPU的\"时间片\"，每个用户感觉自己独占计算机（实际上每隔几毫秒就切换一次）。实时系统像飞机导航——必须在限定时间内完成任务，延误一秒都可能出事故。分布式系统像网购平台——资源分散在不同服务器上，联合完成一个任务。网络操作系统像学校服务器——为网络中的多台计算机提供文件共享、打印共享等服务。单用户系统如MS-DOS（一次只能一个人用），多用户系统如Linux（多个用户同时登录使用）。\n\n【常见错误】\n1. 把\"分时系统\"理解为\"分时间段预约\"——实际上是CPU时间被划分成极短的时间片轮流服务多个用户，切换速度极快。\n2. 认为\"实时系统\"就是\"速度快\"——实时系统的关键是\"有严格的时间限制\"，必须在截止期限前完成。\n3. 分时和实时搞混——分时强调\"公平轮流\"，实时强调\"按时完成\"。\n\n【出题方向】\n常考选择题\"ATM自动柜员机使用的是____系统\"（分时系统）、\"飞机导航系统使用的是____系统\"（实时系统）。也常考填空题\"按处理模式，操作系统可分为批处理系统、____、____、分布式系统和网络操作系统\"（分时系统、实时系统）。简答题\"简述分时系统的特点\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(704,693,4,4,'操作系统的概念与地位','# 操作系统的概念与地位\n\n【一句话定义】\n操作系统（OS）是管理和控制计算机硬件与软件资源的系统软件，是直接运行在\"裸机\"上的最基本软件，所有其他软件都必须在操作系统支持下才能运行。\n\n【具体例子】\n裸机就像一块没装修的空地，操作系统就像地基和水电管线——没有它，房子（应用软件）盖不起来。Windows 7就是操作系统，你开机看到的桌面、能打开Word写作文、能上网玩游戏，都是Windows 7在底层帮你管理CPU、内存、硬盘，协调各种硬件和软件的工作。如果把计算机比作 orchestra（管弦乐队），操作系统就是指挥家——CPU是钢琴师、内存是小提琴手、硬盘是大提琴手，操作系统指挥大家何时演奏、何时停止，才能奏出和谐的乐曲。\n\n【常见错误】\n1. 认为操作系统就是桌面——桌面只是操作系统提供的界面之一，操作系统的核心功能是管理硬件和软件资源。\n2. 把Office当成操作系统——Word、Excel是应用软件，Windows才是操作系统。\n3. 以为没有操作系统也能用软件——裸机（没装系统的电脑）什么都做不了，必须先装操作系统。\n\n【出题方向】\n常考填空题\"操作系统是管理和控制计算机____与____资源的系统软件\"（硬件、软件）。也常考判断题\"操作系统是应用软件\"（错）。选择题\"直接运行在裸机上的最基本软件是\"（操作系统）。简答题\"简述操作系统在计算机系统中的地位\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(705,439,4,2,'单元5管理Windows资源',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(706,705,4,3,'任务1使用资源管理器',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(707,706,4,4,'Windows资源管理器','# Windows资源管理器\n\n【一句话定义】\nWindows资源管理器是Windows中用于组织和管理计算机上文件、文件夹和驱动器的实用程序，以分层结构显示所有存储设备的内容，支持复制、移动、重命名、搜索等操作。\n\n【具体例子】\n打开资源管理器的方法：①Win+E快捷键（最常用）；②开始菜单→所有程序→附件→Windows资源管理器；③右击开始按钮→打开Windows资源管理器。资源管理器左侧是导航窗格（显示收藏夹、库、计算机、网络），右侧是文件列表窗格。你可以通过左侧点击文件夹来浏览内容，也可以在右侧双击打开文件夹。资源管理器显示了计算机上的所有驱动器（C盘、D盘等）、文件夹的分层结构，以及映射的网络驱动器。\n\n【常见错误】\n1. 资源管理器和IE浏览器搞混——资源管理器管理文件（Win+E），IE浏览器上网（不是同一个程序）。\n2. 不知道Win+E快捷键——这是最快速打开资源管理器的方法，比鼠标点快得多。\n3. 以为资源管理器只能看文件——实际上可以完成复制、移动、删除、重命名等所有文件操作。\n\n【出题方向】\n常考选择题\"打开Windows资源管理器的快捷键是\"（Win+E）。也常考填空题\"Windows资源管理器的作用是____\"（组织和管理计算机上的文件和文件夹）。判断题\"资源管理器可以显示网络驱动器\"（对）。实操题\"使用资源管理器浏览D盘内容，并复制一个文件到桌面\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(708,706,4,4,'库的概念与使用','# 库的概念与使用\n\n【一句话定义】\n库是Windows 7新增的功能，它将分散在不同位置的同类型文件夹聚合在一起统一显示和管理，默认包含视频、图片、文档、音乐四个库。\n\n【具体例子】\n库就像虚拟文件夹——它本身不存储文件，只是\"快捷方式集合\"。比如\"图片\"库可以同时显示C盘\\Users\\你的照片、D盘\\旅游照片、E盘\\班级活动照片，不用分别去三个地方找。使用库的步骤：①打开资源管理器→点击\"图片\"库；②在空白处右击→属性→\"包含文件夹\"→选择要添加的文件夹；③确定后，该文件夹的内容就出现在图片库中了。你可以像操作普通文件夹一样对库中的文件进行浏览、排序、搜索。\n\n【常见错误】\n1. 以为库里的文件存在库里——实际上文件在原位置，库只是\"视图\"，不是存储位置。\n2. 删除了库中的文件——删除库中的文件就是删除原位置的文件！\n3. 不知道库可以自定义——可以添加任意文件夹到任意库中，也可以新建自己的库。\n\n【出题方向】\n常考选择题\"Windows 7默认提供的库不包括\"（视频、图片、文档、音乐是默认的，干扰项可能是\"下载\"\"桌面\"等）。也常考填空题\"库的功能是将____在不同位置的文件夹聚合在一起\"（分散/不同）。判断题\"删除库中的文件不会删除原文件\"（错，会删除原文件）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(709,706,4,4,'资源管理器基本操作','# 资源管理器基本操作\n\n【一句话定义】\n资源管理器的基本操作包括浏览文件夹（单击展开/折叠）、改变视图方式（超大图标/列表/详细信息等）、使用地址栏导航、使用搜索框查找文件等。\n\n【应会操作】\n\n浏览操作：单击导航窗格中文件夹左侧的▶展开子文件夹，▼表示已展开。视图切换：工具栏右侧有视图按钮，可以切换超大图标、大图标、中等图标、小图标、列表、详细信息、平铺、内容等8种视图。详细信息视图可以显示文件名、修改日期、类型、大小等列，点击列标题可以按该列排序（如按大小排序找出最大的文件）。地址栏导航：点击路径中的任意文件夹可以快速跳转，如当前在\"D:\\学习\\语文\\作文\"，点击\"语文\"直接回到语文文件夹。预览窗格：工具栏→组织→布局→预览窗格，选中文件右侧显示预览（如图片缩略图、文本内容）。\n\n【常见错误】\n1. 双击导航窗格的文件夹——应该单击（单击在右侧显示内容），双击会展开/折叠。\n2. 不知道怎么排序——详细信息视图下点击列标题（如\"大小\"）即可按该列排序。\n3. 不会用预览窗格——打开预览窗格后，选中文件不用打开就能看到内容。\n\n【出题方向】\n常考选择题\"资源管理器中按文件大小排序应在____视图下操作\"（详细信息）。也常考实操题\"在资源管理器中将视图切换为详细信息，并按修改日期排序\"。填空题\"资源管理器的预览窗格可以通过____菜单→布局→预览窗格打开\"（组织）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(710,706,4,4,'资源管理器窗口组成','# 资源管理器窗口组成\n\n【一句话定义】\n资源管理器窗口由导航窗格（左侧，显示文件夹树状结构）和文件列表窗格（右侧，显示当前文件夹内容）组成，还包括地址栏、搜索框、工具栏等部件。\n\n【具体例子】\n导航窗格在左侧：收藏夹（桌面、下载、最近访问的位置）、库（文档、音乐、图片、视频）、计算机（C盘、D盘等驱动器）、网络。点击导航窗格的文件夹，右侧显示该文件夹的内容。地址栏显示当前路径（如\"计算机 → D盘 → 学习 → 语文\"），可以点击路径中的任意位置快速跳转。搜索框在右上角，输入关键词可以搜索当前文件夹及其子文件夹中的文件。工具栏有\"组织\"按钮（包含剪切、复制、粘贴、删除、重命名等常用操作）。\n\n【常见错误】\n1. 导航窗格和文件列表搞混——左侧是树状目录（导航），右侧是具体文件（内容）。\n2. 不知道地址栏可以点击跳转——点\"D盘\"可以直接回到D盘根目录，不用逐级返回。\n3. 不会用搜索框——搜索框可以输入文件名、扩展名（如*.docx）甚至文件内容中的关键词。\n\n【出题方向】\n常考填空题\"资源管理器窗口由____窗格和____窗格组成\"（导航、文件列表）。也常考选择题\"资源管理器左侧导航窗格显示的是\"（文件夹的树状结构）。实操题\"在资源管理器中使用地址栏快速跳转到上级文件夹\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(711,705,4,3,'任务2管理文件和文件夹',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(712,711,4,4,'CMD常用命令DIR MD CD COPY DEL','# CMD常用命令（DIR、MD、CD、COPY、DEL）\n\n【一句话定义】\nCMD（命令提示符）是Windows的命令行界面，常用命令包括DIR（显示目录）、MD（创建文件夹）、CD（切换目录）、COPY（复制文件）、DEL（删除文件）。\n\n【具体例子】\n打开CMD：开始→搜索cmd→回车。常用命令：①DIR——显示目录文件列表（DIR /W宽屏显示）；②MD——创建文件夹（MD 文件夹名）；③CD——切换目录（CD 文件夹名进入，CD..返回上级，CD\\返回根目录）；④COPY——复制文件（COPY 源文件 目标位置）；⑤DEL——删除文件（DEL 文件名，支持通配符如DEL *.tmp）。\n\n【常见错误】\n1. CMD命令记不住——重点记DIR（看）、CD（进）、MD（建）、COPY（复制）、DEL（删文件）。\n2. 路径写错——CMD中路径用反斜杠\\，不能用斜杠/。\n3. DEL和RD搞混——DEL删文件，RD删空文件夹。\n\n【出题方向】\n常考选择题\"显示目录文件列表的命令是\"（DIR）、\"创建文件夹的命令是\"（MD）。填空题\"切换目录的命令是____\"（CD）。判断题\"DEL命令可以删除文件夹\"（错，DEL删文件，RD删文件夹）。实操题\"使用CMD命令完成创建文件夹、复制文件、删除文件的操作\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(713,711,4,4,'创建快捷方式','# 创建快捷方式\n\n【一句话定义】\n快捷方式是指向某个程序、文件或文件夹的指针（扩展名.lnk），双击快捷方式可以打开目标对象，但删除快捷方式不会影响原程序。\n\n【具体例子】\n创建方法：①找到目标程序/文件；②右击→发送到→桌面快捷方式；③桌面就会出现一个带小箭头的图标。也可以在目标文件上右击→创建快捷方式，然后把生成的快捷方式拖到想要的位置。快捷方式图标左下角有一个小箭头，表示这不是真正的文件，只是个\"门牌号\"。\n\n【应会操作】创建快捷方式的完整操作路径：\n方法一（发送到桌面）：选中文件/文件夹/程序→右键→发送到→桌面快捷方式。\n方法二（在当前位置创建）：选中文件/文件夹→右键→创建快捷方式（会在当前位置创建，可再移动到目标位置）。\n方法三（拖拽+Alt键）：选中文件→按住Alt键→拖拽到目标位置→释放鼠标和Alt键。\n\n快捷方式特点：图标左下角有小箭头标识；删除快捷方式不影响原文件；可以跨分区创建；可以创建网址快捷方式。\n\n【常见错误】\n1. 以为删除快捷方式就卸载了程序——快捷方式只是指针，删了不影响原程序。\n2. 把快捷方式复制给别人——别人的电脑没有对应程序，快捷方式打不开。\n3. 分不清快捷方式和原文件——快捷方式左下角有小箭头，文件大小只有1KB左右。\n\n【出题方向】\n常考选择题\"快捷方式的扩展名是\"（.lnk）。填空题\"创建快捷方式可以通过右击目标→____→桌面快捷方式\"（发送/发送到）。判断题\"删除快捷方式会删除原程序\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(714,711,4,4,'剪贴板的概念与使用','# 剪贴板的概念与使用\n\n【一句话定义】\n剪贴板是Windows在内存中开辟的临时存储区，用于在不同程序或位置之间传递信息，一次只能保留一则信息，关机后内容消失。\n\n【应会操作】\n\n复制粘贴全过程：①选中文字→Ctrl+C（内容被复制到剪贴板）→②到目标位置→Ctrl+V（从剪贴板取出内容粘贴）。剪切（Ctrl+X）也是先把内容放到剪贴板，然后从原位置删除。剪贴板只能存一条信息——你复制了A再复制B，剪贴板里就只有B了。剪贴板的内容关机后消失（因为存在内存里）。Win+V可以查看剪贴板历史（Windows 10+功能）。\n\n【常见错误】\n1. 以为剪贴板能存多条信息——默认只能存最近的一条。\n2. 关机后以为剪贴板内容还在——剪贴板存在内存中，断电/关机后内容丢失。\n3. 复制后忘了粘贴又复制别的——之前的内容被覆盖了。\n\n【出题方向】\n常考填空题\"剪贴板是Windows在____中开辟的临时存储区\"（内存）。判断题\"剪贴板中的内容关机后仍然存在\"（错）。选择题\"剪贴板一次能保留____则信息\"（一/1）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(715,711,4,4,'回收站的工作原理','# 回收站的工作原理\n\n【一句话定义】\n回收站是硬盘上的一块临时存储区域，用于存放从硬盘删除的文件和文件夹，这些文件可以被还原到原位置或永久删除，但U盘/软盘/网络位置删除的文件不经过回收站。\n\n【应会操作】\n\n操作步骤：①删除到回收站——选中文件按Delete键（可恢复）；②永久删除——选中文件按Shift+Delete（不可恢复）；③还原——双击打开回收站→选中文件→\"还原此项目\"（文件回到原位置）；④清空回收站——回收站右键→\"清空回收站\"（所有文件永久删除）。每个磁盘分区有独立的回收站空间，可在回收站属性中设置大小（默认占磁盘10%）。当回收站满了，最早删除的文件会被自动清除。\n\n【常见错误】\n1. 以为回收站在内存里——回收站在硬盘上（C盘根目录下的隐藏文件夹$Recycle.Bin）。\n2. U盘删除的文件去回收站找——U盘删除的文件不进回收站，直接永久删除。\n3. 还原后找不到文件——还原的文件回到原来所在的文件夹，不是在桌面上。\n\n【出题方向】\n常考选择题\"删除到回收站的快捷键是\"（Delete）、\"永久删除的快捷键是\"（Shift+Delete）。判断题\"U盘删除的文件可以在回收站中恢复\"（错）。实操题\"将文件删除到回收站，然后还原到原位置\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(716,711,4,4,'复制移动删除文件和文件夹','# 复制、移动、删除文件和文件夹\n\n【一句话定义】\n复制是创建文件副本（原文件保留在原地），移动是将文件从原位置转移到新位置（原文件消失），删除是将文件移到回收站或永久删除；常用快捷键Ctrl+C复制、Ctrl+X剪切、Ctrl+V粘贴、Delete删除到回收站、Shift+Delete永久删除。\n\n【应会操作】复制文件/文件夹的完整操作路径（以资源管理器为例）：\n第一步：选中要复制的文件/文件夹。单击选中单个文件；按住Ctrl单击可选中多个不连续文件；按住Shift单击可选中连续范围内的文件；Ctrl+A全选。\n\n第二步：执行复制。方法①：按Ctrl+C（复制到剪贴板）；方法②：右键→选择\"复制\"；方法③：点击菜单栏\"编辑\"→\"复制\"。\n\n第三步：打开目标文件夹。在资源管理器左侧导航栏中点击目标文件夹。\n\n第四步：执行粘贴。按Ctrl+V（或右键→\"粘贴\"），文件/文件夹即被复制到目标位置。\n\n拖拽方式：按住Ctrl键拖拽文件到目标文件夹→释放鼠标→完成复制（鼠标指针旁显示\"+\"号）。\n\n【应会操作】移动文件/文件夹的完整操作路径：\n第一步：选中要移动的文件/文件夹。\n\n第二步：执行剪切。方法①：按Ctrl+X；方法②：右键→选择\"剪切\"。\n\n第三步：打开目标文件夹，按Ctrl+V粘贴。\n\n拖拽方式：同一磁盘分区内直接拖拽=移动；不同磁盘分区之间拖拽=复制（注意：跨分区拖拽时如需移动，按住Shift键拖拽）。拖拽时注意观察鼠标指针旁的提示文字。\n\n【应会操作】删除文件/文件夹的完整操作路径：\n普通删除（移到回收站）：选中文件→按Delete键→或右键→\"删除\"→文件被移到回收站（可恢复）。\n\n永久删除（不经过回收站）：选中文件→按Shift+Delete键→弹出确认对话框→点击\"是\"→文件被永久删除，不可恢复。\n\n【应会操作】新建文件夹的完整操作路径：\n在资源管理器中打开目标位置→右键空白处→新建→文件夹→输入文件夹名称→按回车键确认。\n\n快捷键方式：Ctrl+Shift+N快速新建文件夹。\n\n【常见错误】\n1. 复制和移动搞混——复制后原位置还有文件（Ctrl+C→Ctrl+V），移动后原位置没了（Ctrl+X→Ctrl+V）。\n2. 同一分区拖拽误以为是复制——同一磁盘分区直接拖拽=移动，跨分区拖拽=复制。\n3. Shift+Delete误删重要文件——永久删除不进回收站，操作前务必确认，重要文件建议先备份。\n4. 不小心把文件复制到了错误位置——粘贴后注意查看目标文件夹，如有误操作立即按Ctrl+Z撤销。\n\n【出题方向】\n常考选择题\"Ctrl+C的功能是____，Ctrl+X的功能是____\"（复制、剪切）。填空题\"永久删除文件的快捷键是____\"（Shift+Delete）。判断题\"同一分区中直接拖拽文件是复制操作\"（错，是移动）。实操题\"在D盘新建一个名为\'作业\'的文件夹，将桌面的两个文件复制到该文件夹中\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(717,711,4,4,'搜索文件和文件夹','# 搜索文件和文件夹\n\n【一句话定义】\nWindows 7提供搜索功能，可以在资源管理器中按文件名、扩展名、修改日期、大小等条件搜索文件和文件夹。\n\n【具体例子】\n搜索方法：①打开资源管理器，在右上角搜索框输入关键词；②输入\"*.docx\"搜索所有Word文档；③输入\"报告\"搜索文件名包含\"报告\"的文件；④输入\"*.jpg\"搜索所有图片。高级搜索：搜索框输入后，在工具栏会出现\"添加搜索筛选器\"选项，可以按修改日期、类型、大小等条件筛选。搜索范围默认是当前文件夹及其子文件夹。\n\n【应会操作】搜索文件的完整操作路径：\n第一步：打开资源管理器→在右上角搜索框中输入关键词（文件名或部分名称）。\n第二步：系统实时显示匹配结果→搜索范围包括当前文件夹及其子文件夹。\n第三步：使用搜索筛选器优化结果：\n  - 按日期：点击搜索框下方\"修改日期\"→选择今天/昨天/本周/本月等。\n  - 按大小：点击\"大小\"→选择空/微小/小/中等/大/巨大。\n  - 按类型：输入*.doc搜索所有Word文档，*.jpg搜索所有图片。\n第四步：在搜索结果中右键→打开文件所在位置（定位到文件的实际存储位置）。\n\n高级搜索：使用通配符（*代表任意多个字符，?代表一个字符），如搜索\"*.tx?\"可找到.txt和.tex文件。\n\n【常见错误】\n1. 搜索范围不清楚——默认搜索当前文件夹及其子文件夹，不是整个电脑。\n2. 不知道可以用通配符——搜索框支持*和?通配符。\n3. 搜索不到以为文件丢了——可能是文件被隐藏了，或者搜索范围不对。\n\n【出题方向】\n常考选择题\"在资源管理器中搜索*.docx表示搜索____\"（所有Word文档）。填空题\"搜索所有以\'期末\'开头的Excel文件，应输入____\"（期末*.xlsx）。判断题\"搜索功能默认搜索当前文件夹及其子文件夹\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(718,711,4,4,'文件与文件夹属性','# 文件与文件夹属性\n\n【一句话定义】\nWindows 7中文件和文件夹的属性包括只读（R，只能读取不能修改）、隐藏（H，默认不显示）、存档（A，标记是否备份过）和系统（S，系统文件），可通过右键→属性查看和修改。\n\n【具体例子】\n只读属性：你给老师的作业设为只读，老师能打开看但不能修改。设置方法：右击文件→属性→勾选\"只读\"→确定。隐藏属性：系统文件如pagefile.sys（虚拟内存文件）默认隐藏。显示隐藏文件：资源管理器→组织→文件夹和搜索选项→查看→勾选\"显示隐藏的文件、文件夹和驱动器\"。NTFS格式下还可以设置压缩属性（节省空间）和加密属性（保护隐私）。\n\n【常见错误】\n1. 只读属性以为是密码保护——只读只是防止修改，不是加密，任何人都能取消只读属性。\n2. 隐藏文件以为丢了——其实只是看不见了，勾选\"显示隐藏文件\"就能找到。\n3. 系统属性随便修改——系统文件一般不要动，修改可能导致系统不稳定。\n\n【出题方向】\n常考选择题\"表示文件只能读取不能修改的属性是\"（只读）。填空题\"文件的四种属性是____、____、____和____\"（只读、隐藏、存档、系统）。判断题\"隐藏属性的文件完全不能被访问\"（错，只是默认不显示）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(719,711,4,4,'文件夹与树状结构','# 文件夹与树状结构\n\n【一句话定义】\n文件夹是用来组织和管理磁盘文件的容器，采用多级层次结构（树状结构），每个磁盘有一个根文件夹（如C:\\），根文件夹下可以包含子文件夹和文件，同一文件夹中不能有同名文件或文件夹。\n\n【具体例子】\n树状结构像家谱：C盘是\"老祖宗\"（根目录C:\\），下面分Users、Program Files、Windows等\"儿子\"（一级文件夹），Users下面又有你的用户名文件夹等\"孙子\"（二级文件夹）。操作示例：在资源管理器D盘根目录下创建\"学习\"文件夹→在\"学习\"中创建\"语文\"和\"数学\"两个子文件夹→在\"语文\"中创建一个文本文件。路径表示法：D:\\学习\\语文\\作文.txt，表示从D盘根目录→学习文件夹→语文文件夹→作文.txt文件。\n\n【常见错误】\n1. 同一文件夹下同名——同一文件夹中不能有同名文件或文件夹，不同文件夹可以。\n2. 路径中的\\和/搞混——Windows用反斜杠\\（如C:\\Users），网址用斜杠/（如http://）。\n3. 以为文件夹有扩展名就有类型——文件夹可以有扩展名（如\"资料.doc\"），但不具有文件扩展名的作用。\n\n【出题方向】\n常考填空题\"Windows文件夹的组织结构是____\"（树状结构/层次结构）。选择题\"同一文件夹中能否有同名文件\"（不能）。判断题\"不同文件夹中可以有同名文件\"（对）。实操题\"在D盘创建文件夹结构D:\\学习\\语文\\作文\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(720,711,4,4,'文件的概念与命名规则','# 文件的概念与命名规则\n\n【一句话定义】\n文件是具有文件名的一组相关信息的集合，文件名格式为\"主文件名.扩展名\"；Windows 7中文件名不区分大小写，最多255个字符，不能包含\\ / : * ? \" < > |，也不能使用系统保留设备名。\n\n【具体例子】\n文件名\"cmd.exe\"中，\"cmd\"是主文件名，\"exe\"是扩展名表示可执行文件。命名规则实操：①合法文件名：\"我的作文.docx\"\"2024期末成绩.xlsx\"\"照片(1).jpg\"；②非法文件名：\"成绩/汇总.xlsx\"（含/）、\"作业*答案.doc\"（含*）、\"我的：日记.txt\"（含：）；③保留设备名不能用：CON.txt、PRN.doc、AUX.jpg都是非法的，因为CON、PRN、AUX是系统保留名。文件名中可以有多个点，最后一个点后面是扩展名，如\"report.final.v2.docx\"的扩展名是docx。\n\n【常见错误】\n1. 文件名中用非法字符——尤其容易用*、?、/、|、<、>、:等，这些在Windows中不允许。\n2. 用系统保留名——CON、PRN、AUX、NUL、COM0-COM9、LPT0-LPT9都不能用。\n3. 以为文件名区分大小写——Windows文件名不区分大小写，\"File.txt\"和\"file.txt\"是同一个文件。\n\n【出题方向】\n常考选择题\"下列文件名合法的是\"。填空题\"Windows文件名中不能包含的字符有____\"（\\ / : * ? \" < > |）。判断题\"Windows文件名区分大小写\"（错）。实操题\"尝试创建几个文件名，验证命名规则\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(721,711,4,4,'文件类型与扩展名','# 文件类型与扩展名\n\n【一句话定义】\nWindows通过文件扩展名识别文件类型，常见类型有：.txt（文本）、.doc/.docx（Word）、.xls/.xlsx（Excel）、.ppt/.pptx（PPT）、.jpg/.png/.bmp（图片）、.mp3/.wma（音频）、.avi/.mp4（视频）、.exe（可执行）、.zip/.rar（压缩）、.bat（批处理）。\n\n【具体例子】\n机房常见文件：你写的作文保存为.docx（Word 2007+格式），表格是.xlsx，演示文稿是.pptx，从网上下载的图片是.jpg或.png，音乐课听的歌曲是.mp3，视频是.avi或.mp4。安装程序都是.exe（如QQ的安装程序qqsetup.exe）。同一个扩展名对应默认打开程序——双击.docx自动用Word打开，双击.mp3自动用音乐播放器打开。如果扩展名被隐藏了（Windows默认隐藏已知扩展名），可以在文件夹选项→查看→取消勾选\"隐藏已知文件类型的扩展名\"来显示。\n\n【常见错误】\n1. .doc和.docx搞混——.doc是Word 2003格式，.docx是Word 2007+格式，新格式更小更安全。\n2. .jpg和.png搞混——.jpg适合照片（有损压缩、文件小），.png支持透明背景（无损压缩）。\n3. .exe文件随便双击——exe是可执行程序，来历不明的exe可能携带病毒。\n\n【出题方向】\n常考选择题\"Word文档的扩展名是\"（.doc/.docx）、\"可执行文件的扩展名是\"（.exe）。填空题\"Excel工作簿的扩展名是____\"（.xls/.xlsx）。判断题\".txt文件是文本文件，可以用记事本打开\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(722,711,4,4,'文件系统格式','# 文件系统格式\n\n【一句话定义】\n文件系统是操作系统管理磁盘文件的方法，Windows 7支持FAT、FAT32和NTFS三种文件系统，其中NTFS安全性高、支持大文件和权限管理，是推荐使用的格式。\n\n【应会操作】\n\n格式化U盘时会选文件系统：FAT很老，单个文件不能超过2GB，现在基本不用；FAT32兼容性好（手机、电视、游戏机都能读），但单个文件不能超过4GB，适合小U盘；NTFS是Windows推荐格式，支持单个64TB的大文件，有文件权限加密压缩功能，安全性高。比如你要存一个5GB的高清电影到U盘，FAT32格式的U盘存不进去（超过4GB限制），必须用NTFS格式。查看文件系统：右击磁盘→属性→文件系统。\n\n【常见错误】\n1. 三种文件系统特点记混——FAT最老（2GB限制），FAT32兼容好（4GB限制），NTFS功能最全。\n2. 不知道FAT32的4GB限制——存大文件时提示\"文件过大\"，其实是文件系统的问题。\n3. Mac电脑读不了NTFS——Mac默认能读NTFS但不能写，需要第三方软件或格式化为exFAT。\n\n【出题方向】\n常考选择题\"Windows 7推荐使用的文件系统是\"（NTFS）。也常考填空题\"FAT32格式的磁盘，单个文件最大不能超过____\"（4GB）。判断题\"NTFS文件系统支持文件权限设置\"（对）。简答题\"比较FAT32和NTFS文件系统的区别\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(723,711,4,4,'文件系统格式FAT FAT32 NTFS','# 文件系统格式（FAT、FAT32、NTFS）\n\n【一句话定义】\n文件系统是操作系统管理磁盘文件的方法，Windows 7支持FAT（老标准，2GB限制）、FAT32（兼容性好，4GB文件限制）和NTFS（功能最全，支持大文件、权限管理和加密）。\n\n【具体例子】\n格式化U盘时选文件系统：FAT32兼容性好（手机、电视、游戏机都能读），但单个文件不能超过4GB（存不了高清电影）；NTFS是Windows推荐格式，支持单个64TB的大文件，有文件权限加密压缩功能，安全性高。操作：右击U盘→格式化→文件系统选择NTFS→开始。注意：格式化会清空磁盘所有数据！查看文件系统：右击磁盘→属性→文件系统。\n\n【常见错误】\n1. 三种格式特点记混——FAT最老（2GB限制），FAT32兼容好（4GB限制），NTFS功能最全。\n2. 不知道FAT32的4GB限制——存大文件时提示\"文件过大\"，其实是文件系统限制。\n3. Mac电脑读不了NTFS——Mac默认能读NTFS但不能写，需要第三方软件或格式化为exFAT。\n\n【出题方向】\n常考选择题\"Windows 7推荐使用的文件系统是\"（NTFS）。填空题\"FAT32格式的磁盘，单个文件最大不能超过____\"（4GB）。判断题\"NTFS文件系统支持文件权限设置\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(724,711,4,4,'新建文件和文件夹','# 新建文件和文件夹\n\n【一句话定义】\n在资源管理器中可以通过菜单、右键菜单或快捷键创建新文件和新文件夹，新建文件夹的快捷键是Ctrl+Shift+N。\n\n【具体例子】\n新建文件夹：①在资源管理器中打开目标位置；②右击空白处→新建→文件夹（或菜单栏→新建文件夹）；③输入文件夹名称→回车确认。快捷键方式：Ctrl+Shift+N直接新建文件夹。新建文件：右击空白处→新建→选择文件类型（文本文档、Word文档、Excel工作表等）→输入文件名。也可以在记事本中编辑后\"另存为\"创建新文件。\n\n【应会操作】新建文件夹的完整操作路径：\n第一步：在资源管理器中打开目标位置（如D盘）。\n第二步：右键点击空白处→新建→文件夹→出现一个名为\"新建文件夹\"的文件夹且名称处于选中状态。\n第三步：输入新文件夹名称→按回车键确认。\n快捷键方式：打开目标位置后按Ctrl+Shift+N→直接新建文件夹。\n\n新建文件：右键空白处→新建→选择文件类型（文本文档/Word文档/Excel工作表等）→输入文件名→按回车。\n\n【常见错误】\n1. 新建后忘了改名——新建文件夹默认叫\"新建文件夹\"，要及时改成有意义的名称。\n2. 在错误的位置新建——注意先确认当前路径（看地址栏），别建到桌面去了。\n3. 新建文件类型选错——要新建Word文档就选\"Microsoft Word文档\"，不是\"文本文档\"。\n\n【出题方向】\n常考选择题\"新建文件夹的快捷键是\"（Ctrl+Shift+N）。填空题\"在资源管理器中，可以通过____菜单→新建来创建新文件夹\"（文件/右击）。判断题\"新建文件夹后需要立即输入名称\"（对，默认高亮待输入）。实操题\"在D盘根目录下新建一个名为\'学习资料\'的文件夹\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(725,711,4,4,'系统还原与还原点','# 系统还原与还原点\n\n【一句话定义】\n系统还原是Windows 7将计算机恢复到之前某个正常状态（还原点）的功能，还原点可以自动创建或手动创建，用于解决系统故障。\n\n【具体例子】\n场景：安装了一个软件后电脑变慢了，卸载后还是很慢。这时用系统还原：开始→所有程序→附件→系统工具→系统还原→选择安装软件之前的还原点→还原。注意：系统还原只还原系统文件和设置，不删除个人文档！操作前最好手动创建一个还原点：系统还原→创建还原点→输入描述→创建。\n\n【常见错误】\n1. 以为系统还原会删除个人文件——不会，只影响系统文件和程序。\n2. 没有提前创建还原点——等到系统出问题了才发现没有可用的还原点。\n3. 系统还原和系统备份搞混——还原是回到某个时间点，备份是把文件复制到别处保存。\n\n【出题方向】\n常考选择题\"系统还原可以恢复到____\"（之前的还原点）。填空题\"系统还原点可以____创建或____创建\"（自动、手动）。判断题\"系统还原会删除用户的个人文档\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(726,711,4,4,'通配符的使用','# 通配符的使用\n\n【一句话定义】\n通配符是搜索或命令中代替一个或多个字符的特殊符号，Windows中*（星号）代表任意多个字符（含0个），?（问号）代表任意一个字符。\n\n【具体例子】\n搜索操作：输入\"*.docx\"找所有Word文档；输入\"计算机*\"找以\"计算机\"开头的所有文件（如计算机基础知识.txt、计算机科学.doc）；输入\"计算机*.doc\"找以\"计算机\"开头且扩展名为.doc的文件。?的用法：\"照片?.jpg\"能找到\"照片1.jpg\"\"照片A.jpg\"但不能找到\"照片10.jpg\"（因为?只代表一个字符）。CMD中也常用：DIR *.txt列出所有文本文件，DEL temp*.tmp删除所有以temp开头的临时文件。\n\n【常见错误】\n1. *和?搞混——*代表任意多个字符（0个也行），?只能代表一个字符。\n2. 搜索时范围太大——\"*.docx\"会搜出大量文件，最好指定文件夹缩小范围。\n3. 以为通配符只能用在搜索框——CMD命令（DIR、DEL、COPY等）中也广泛使用。\n\n【出题方向】\n常考选择题\"*代表____\"（任意多个字符）、\"?代表____\"（任意一个字符）。填空题\"搜索所有以\'成绩\'开头的Excel文件应输入____\"（成绩*.xlsx）。判断题\"通配符?可以代表零个或多个字符\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(727,711,4,4,'重命名文件和文件夹','# 重命名文件和文件夹\n\n【一句话定义】\n重命名是修改文件或文件夹名称的操作，选中文件/文件夹后按F2键（或右击→重命名）即可编辑名称。\n\n【具体例子】\n操作步骤：①选中要重命名的文件/文件夹（单击一次）；②按F2键（或右击→重命名），名称变为可编辑状态；③输入新名称；④按回车键确认。也可以：①选中文件→缓慢双击（间隔稍长，不要双击太快变成打开）；②输入新名称→回车确认。\n\n【应会操作】重命名文件/文件夹的完整操作路径：\n第一步：选中要重命名的文件/文件夹。\n第二步：按F2键（或右键→重命名，或点击菜单栏\"组织\"→\"重命名\"）。\n第三步：输入新名称→按回车键确认。\n\n注意：文件名不能包含以下字符：\\ / : * ? \" < > |。不能与同一文件夹中的其他文件重名。修改扩展名会改变文件类型，可能导致无法打开。\n\n【常见错误】\n1. 双击太快变成打开——选中后缓慢双击（间隔约半秒）才是重命名。\n2. 只改扩展名——重命名时如果只改扩展名（如把.txt改成.docx），文件并不能变成Word格式，只是名字变了。\n3. 改完名找不到文件——如果按了Esc键会取消重命名，文件保持原名。\n\n【出题方向】\n常考选择题\"重命名文件/文件夹的快捷键是\"（F2）。填空题\"重命名文件时，不能修改____否则可能导致文件无法打开\"（扩展名）。判断题\"重命名文件就是修改扩展名\"（错，重命名是改名称，不是改格式）。实操题\"将指定文件重命名为新的名称\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(728,439,4,2,'单元6设置和维护操作系统',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(729,728,4,3,'任务1个性化设置Windows',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(730,729,4,4,'主题与个性化设置','# 主题与个性化设置\n\n【一句话定义】\n主题是Windows 7桌面外观的完整方案，包含桌面背景、窗口颜色、声音方案和屏幕保护程序的组合，通过控制面板→个性化进行设置。\n\n【应会操作】\n\n设置方法：控制面板→个性化→可以选择系统预设主题，也可以自定义：①桌面背景——选择一张或多张图片（多选则自动轮播），设置位置为\"填充\"\"平铺\"\"居中\"等；②窗口颜色——选择颜色并调节透明度（Aero特效）；③声音——选择不同事件的声音方案；④屏幕保护程序——选择屏保样式和等待时间，可以勾选\"在恢复时显示登录屏幕\"增强安全性。\n\n【常见错误】\n1. 桌面背景位置和大小搞混——\"填充\"保持比例填满屏幕，\"拉伸\"变形填满，\"居中\"原大小放中间，\"平铺\"重复排列。\n2. 以为屏幕保护程序能省电——LCD显示器不需要屏保来防止老化，屏保主要是美观和安全。\n3. 不知道怎么换主题——个性化窗口中有预设主题，也可以从微软官网下载更多主题。\n\n【出题方向】\n常考选择题\"桌面背景的显示方式不包括\"（填充、平铺、居中、拉伸是包含的，干扰项如\"旋转\"\"放大\"）。填空题\"Windows 7中，个性化设置可以在____面板中找到\"（控制）。实操题\"更换桌面背景为指定图片，设置显示方式为填充\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(731,729,4,4,'主题的概念与组成','# 主题的概念与组成\n\n【一句话定义】\n主题是计算机上图片、颜色和声音的组合，包括桌面背景、屏幕保护程序、窗口边框颜色和声音方案，某些主题还包括桌面图标和鼠标指针。\n\n【应会操作】\n\nWindows 7提供多种主题：Aero主题（带半透明玻璃效果，最漂亮但较耗性能）、Windows 7基本主题（无Aero效果，适合老旧电脑）、高对比度主题（让屏幕项目更易看清，适合视力障碍者）。自定义主题：控制面板→外观和个性化→个性化→点击\"桌面背景\"选图片→\"窗口颜色\"选颜色→\"声音\"选声音方案→保存主题。注意：如果电脑运行缓慢，应选择基本主题；如果想要更清晰的显示，选择高对比度主题。\n\n【常见错误】\n1. 以为主题只是换壁纸——主题还包括窗口颜色、声音、屏幕保护程序等。\n2. Aero主题卡就以为是电脑坏了——Aero需要较好的显卡支持，老电脑用基本主题更流畅。\n3. 不会保存自定义主题——设置好各项后点击\"保存主题\"，输入名称即可。\n\n【出题方向】\n常考选择题\"主题不包括以下哪项\"（干扰项如\"字体大小\"——主题不含字体大小设置）。填空题\"主题包括桌面背景、____、窗口边框颜色和____\"（屏幕保护程序、声音方案）。判断题\"Aero主题包含半透明玻璃效果\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(732,729,4,4,'屏幕分辨率','# 屏幕分辨率\n\n【一句话定义】\n屏幕分辨率是屏幕上显示的文本和图像的清晰度，由水平像素数和垂直像素数表示（如1920×1080），分辨率越高项目越清楚但尺寸越小。\n\n【具体例子】\n1920×1080表示水平方向1920个像素，垂直方向1080个像素。分辨率对比：800×600（字大但模糊，老式显示器）、1024×768（较老标准）、1366×768（笔记本常用）、1920×1080（全高清，主流）。设置方法：控制面板→外观和个性化→显示→调整分辨率。分辨率取决于显示器大小和显卡类型——不是想设多高就多高，超出显示器支持范围会黑屏。屏幕上的项目数量和分辨率的关系：分辨率越高，屏幕能容纳的项目越多，但每个项目越小。\n\n【应会操作】设置屏幕分辨率的完整操作路径：\n第一步：桌面空白处→右键→\"屏幕分辨率\"（或控制面板→外观和个性化→显示→屏幕分辨率）。\n第二步：在\"分辨率\"下拉列表中拖动滑块选择合适的分辨率（推荐的分辨率通常是显示器的最佳分辨率，旁边会标注\"推荐\"）。\n第三步：点击\"应用\"→屏幕会暂时切换→弹出确认对话框→点击\"保留更改\"确认；如果屏幕显示不正常，等待15秒会自动恢复。\n第四步：点击\"确定\"完成设置。\n\n调整显示方向：在同一窗口中→\"方向\"下拉→选择横向/纵向/横向（翻转）/纵向（翻转）。\n\n调整刷新率：点击\"高级设置\"→\"监视器\"选项卡→\"屏幕刷新频率\"下拉选择→确定。\n\n【常见错误】\n1. 分辨率设太高导致黑屏——超出显示器支持范围，需进安全模式调回。\n2. 以为分辨率只影响清晰度——还影响屏幕能显示的项目数量。\n3. 分辨率和刷新率搞混——分辨率是像素数量（1920×1080），刷新率是每秒刷新次数（60Hz）。\n\n【出题方向】\n常考选择题\"1920×1080的分辨率表示\"（水平1920像素，垂直1080像素）。填空题\"分辨率越高，项目越____但尺寸越____\"（清楚、小）。判断题\"分辨率只取决于显示器的大小\"（错，还取决于显卡类型）。实操题\"将屏幕分辨率调整为1024×768，观察显示效果后再恢复\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(733,729,4,4,'控制面板三种视图','# 控制面板三种视图\n\n【一句话定义】\nWindows 7控制面板提供类别、大图标和小图标三种视图方式，其中\"类别\"是默认视图，将相关设置归为8大类。\n\n【具体例子】\n打开控制面板：开始菜单→控制面板。三种视图切换：右上角\"查看方式\"下拉选择。类别视图（默认）：分为\"系统和安全\"\"网络和Internet\"\"硬件和声音\"\"程序\"\"用户帐户和家庭安全\"\"外观和个性化\"\"时钟、语言和区域\"\"轻松访问\"8类。大图标/小图标视图：类似Windows XP的经典视图，按字母顺序列出所有设置项目。哪种好用？类别视图适合找功能（如\"改桌面背景\"去\"外观和个性化\"），大图标视图适合找具体项目（直接看到\"显示\"\"个性化\"等）。\n\n【应会操作】切换控制面板视图的完整操作路径：\n第一步：打开控制面板（开始菜单→控制面板）。\n第二步：点击右上角\"查看方式\"下拉列表→选择视图模式：\n  - 类别（默认）：按功能分类显示（系统和安全/网络和Internet/硬件和声音/程序等8大类），适合新手。\n  - 大图标：所有项目以大图标方式平铺显示。\n  - 小图标：所有项目以小图标方式平铺显示。\n\n通过控制面板设置屏幕保护程序：控制面板→外观和个性化→个性化→屏幕保护程序→选择程序→设置等待时间→确定。\n\n通过控制面板设置日期和时间：控制面板→时钟、语言和区域→日期和时间→更改日期和时间→设置→确定。\n\n【常见错误】\n1. 找不到需要的设置——右上角搜索框输入关键词（如\"分辨率\"）即可找到。\n2. 视图方式不会切换——右上角\"查看方式\"下拉菜单切换。\n3. 以为控制面板只能看不能改——所有设置都可以修改。\n\n【出题方向】\n常考选择题\"Windows 7控制面板默认的视图方式是\"（类别）。填空题\"控制面板共有____种视图方式\"（3/三）。实操题\"打开控制面板，将视图方式切换为大图标，然后打开\'显示\'设置\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(734,729,4,4,'类别视图的8大分类','# 类别视图的8大分类\n\n【一句话定义】\n控制面板\"类别\"视图将设置项目归为8大类：系统和安全、网络和Internet、硬件和声音、程序、用户帐户和家庭安全、外观和个性化、时钟语言和区域、轻松访问。\n\n【具体例子】\n系统和安全：Windows更新、备份和还原、电源选项、系统属性。外观和个性化：更改桌面背景、更改主题、调整屏幕分辨率。程序：卸载程序、打开或关闭Windows功能。用户帐户和家庭安全：创建新帐户、更改密码、家长控制。硬件和声音：设备和打印机、鼠标、声音。网络和Internet：网络和共享中心、Internet选项。时钟、语言和区域：日期和时间、区域和语言。轻松访问：优化视频显示、更改键盘工作方式。\n\n【常见错误】\n1. 卸载程序找不到——在\"程序\"类别里，不是在\"系统和安全\"。\n2. 改分辨率找不到——在\"外观和个性化\"里，不是在\"硬件和声音\"。\n3. 8类名称记不全——重点记\"程序\"\"外观和个性化\"\"用户帐户\"这三个常用的。\n\n【出题方向】\n常考选择题\"卸载已安装程序应在控制面板的____类别中操作\"（程序）。填空题\"控制面板的\'外观和个性化\'类别中包含____和____等设置\"（更改桌面背景、调整屏幕分辨率）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(735,728,4,3,'任务2管理程序',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(736,735,4,4,'安装与卸载应用程序','# 安装与卸载应用程序\n\n【一句话定义】\n安装应用程序通过运行安装程序（setup.exe或install.exe）按向导完成；卸载应通过控制面板→程序和功能进行，不能直接删除程序文件夹，否则会残留注册表项和系统文件。\n\n【具体说明】\n安装类型：①典型安装——只安装常用组件，占用空间小，适合大多数用户；②完全安装——安装所有组件，功能最全，占用空间大；③自定义安装——用户自行选择要安装的组件和安装路径；④最小安装——只安装运行必需的最小组件。\n\n【应会操作】安装应用程序的完整操作路径：\n第一步：运行安装程序。双击setup.exe或install.exe（或从光盘自动播放）→弹出安装向导→点击\"下一步\"。\n\n第二步：接受许可协议。阅读软件许可协议→勾选\"我接受许可协议中的条款\"→点击\"下一步\"。\n\n第三步：选择安装类型和路径。选择\"典型安装\"或\"自定义安装\"→选择安装路径（默认C:\\Program Files\\软件名，建议保持默认）→点击\"下一步\"。\n\n第四步：选择组件（自定义安装时）。勾选需要安装的组件→取消不需要的附加程序（如工具栏、浏览器插件等捆绑软件）→点击\"下一步\"。\n\n第五步：完成安装。点击\"安装\"→等待安装进度完成→点击\"完成\"（可勾选\"立即运行程序\"或\"查看自述文件\"）。\n\n【应会操作】卸载应用程序的完整操作路径：\n第一步：打开程序和功能。点击开始菜单→控制面板→程序→程序和功能（或\"卸载程序\"）。\n\n第二步：选择要卸载的程序。在已安装程序列表中找到要卸载的软件→单击选中。\n\n第三步：执行卸载。点击列表上方的\"卸载\"按钮（或右键选择\"卸载\"）→弹出确认对话框→点击\"是\"→按照卸载向导提示完成卸载→重启计算机（如要求）。\n\n补充说明：部分软件自带卸载程序（位于开始菜单→该软件文件夹→卸载XX），或通过360软件管家等第三方工具卸载。卸载后建议用磁盘清理清理残留文件。\n\n【常见错误】\n1. 直接删除程序文件夹来卸载——程序安装时向注册表写入了信息和系统服务，直接删文件夹会留下大量垃圾数据导致系统变慢。\n2. 安装时不取消捆绑软件——很多免费软件会捆绑安装浏览器插件、杀毒软件等，安装时要仔细看每个步骤取消不需要的选项。\n3. 安装路径含中文或特殊字符——某些软件安装在中文路径下会出错，建议保持默认的英文路径。\n\n【出题方向】\n常考选择题\"卸载应用程序的正确方法是\"（控制面板→程序和功能→卸载）。填空题\"应用程序的安装程序通常是____或____\"（setup.exe、install.exe）。判断题\"可以直接删除程序文件夹来卸载程序\"（错）。实操题\"安装指定程序，然后通过控制面板正确卸载该程序\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(737,728,4,3,'任务3管理设备',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(738,737,4,4,'即插即用PnP技术','# 即插即用（PnP）技术\n\n【一句话定义】\n即插即用（Plug and Play，PnP）是系统自动侦测周边设备和板卡并自动安装设备驱动程序的技术，做到插上就能用，无须人工干预。\n\n【具体例子】\n插入U盘——Windows自动识别\"这是U盘\"→自动查找并安装驱动→弹出提示\"设备已就绪\"→打开资源管理器就能用。这就是PnP的工作流程：插入设备→系统检测新硬件→查找匹配的驱动程序→安装驱动→设备可用。PnP是由Microsoft、Intel、Compaq等公司共同提出的技术标准，只有符合PnP标准的设备才能实现真正的\"即插即用\"。如果插入设备后系统找不到驱动，会提示\"未能成功安装设备驱动程序\"，这时需要手动从设备官网下载驱动安装。\n\n【常见错误】\n1. 以为PnP不需要驱动——PnP只是自动安装驱动，驱动本身还是必需的。\n2. 设备没反应以为坏了——可能是USB接口接触不良，换个接口试试。\n3. 所有设备都能即插即用——只有符合PnP标准的设备才能自动识别，老旧设备可能不支持。\n\n【出题方向】\n常考选择题\"即插即用的英文缩写是\"（PnP）。填空题\"即插即用是指系统自动____周边设备并自动____的技术\"（侦测、安装驱动程序）。判断题\"即插即用不需要驱动程序\"（错）。简答题\"简述即插即用（PnP）技术的工作原理\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(739,737,4,4,'驱动程序的概念与作用','# 驱动程序的概念与作用\n\n【一句话定义】\n驱动程序（Device Driver）是使计算机和设备通信的特殊程序，相当于硬件的接口，操作系统只有通过这个接口才能控制硬件设备的工作。\n\n【具体例子】\n驱动程序就像翻译官——操作系统说\"打印这份文档\"，但打印机听不懂操作系统的语言，驱动程序负责翻译，让双方能沟通。没有正确安装驱动程序，设备就无法正常工作——比如显卡驱动没装好，屏幕分辨率调不上去、画面卡顿；声卡驱动没装好，没有声音。驱动程序安装顺序（重要！）：①主板芯片组→②显卡→③声卡→④网卡→⑤无线网卡→⑥触控板→⑦读卡器→⑧其他设备。为什么不按顺序会失败？因为后面的驱动可能依赖前面驱动提供的基础功能。\n\n【应会操作】查看和更新驱动程序的完整操作路径：\n第一步：打开设备管理器。右击\"计算机\"→管理→设备管理器（或控制面板→硬件和声音→设备管理器）。\n第二步：展开设备类别（如显示适配器/网络适配器/声音视频和游戏控制器）。\n第三步：查看设备状态：设备名称旁有黄色感叹号表示驱动异常；红色叉号表示设备被禁用。\n\n更新驱动程序：右键设备→更新驱动程序软件→选择\"自动搜索更新的驱动程序软件\"（在线搜索）或\"浏览计算机以查找驱动程序软件\"（手动指定驱动文件路径）→按向导完成安装。\n\n禁用/启用设备：右键设备→禁用（暂时停用设备）/启用（重新激活设备）。\n\n驱动程序安装顺序建议：主板芯片组→显卡→声卡→网卡→其他外设。\n\n【常见错误】\n1. 驱动安装顺序搞错——必须先主板芯片组，再显卡，然后声卡/网卡。\n2. 以为系统能自动安装所有驱动——有些老旧设备或专业设备需要手动安装驱动。\n3. 驱动装不上不管——设备管理器中黄色感叹号表示驱动有问题，设备不能正常工作。\n\n【出题方向】\n常考选择题\"驱动程序的作用是使操作系统能____硬件设备\"（控制）。填空题\"驱动程序安装顺序：先____，再____，然后声卡、网卡\"（主板芯片组、显卡）。判断题\"如果驱动程序未能正确安装，设备可能无法正常工作\"（对）。简答题\"简述驱动程序的作用及安装顺序\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(740,728,4,3,'任务4管理账户',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(741,740,4,4,'Windows账户类型','# Windows账户类型\n\n【一句话定义】\nWindows 7有三种账户类型：管理员账户（最高权限，可修改系统设置和创建其他账户）、标准账户（日常使用，不能修改影响其他用户的设置）、来宾账户（权限最低，只能浏览不能安装软件），此外还有系统内置的Administrator超级管理员账户。\n\n【具体说明】\n管理员账户：可以对计算机进行最高级别的控制，包括安装和卸载软件、修改系统设置、创建/修改/删除其他用户账户、访问所有文件。在控制面板→用户账户中显示为\"管理员\"。\n\n标准账户：适用于日常计算机使用，可以运行程序、访问自己的文件、更改自己的账户设置，但不能安装软件、修改系统设置或查看其他用户的文件。可以防止误操作和恶意软件对系统造成破坏。\n\n来宾账户（Guest）：针对需要临时使用计算机的用户，访问权限最低——只能浏览网页和运行已有程序，不能安装软件、不能修改系统设置、不能创建密码、不能访问其他用户的文件。默认未启用，需要在控制面板中手动启用。\n\nAdministrator账户：Windows 7系统内置的超级管理员账户，权限比普通管理员更高，默认被禁用（隐藏），在标准登录界面不显示。主要用于系统故障修复、密码重置等高级管理操作。\n\n【应会操作】创建新用户账户的完整操作路径：\n第一步：打开用户账户管理。点击开始菜单→控制面板→用户帐户和家庭安全→用户帐户→管理其他帐户。\n\n第二步：创建新账户。点击\"创建一个新帐户\"→输入新账户的名称→选择账户类型（标准用户/管理员）→点击\"创建帐户\"。\n\n第三步：设置密码（可选）。点击新建的账户→选择\"创建密码\"→输入两次密码和密码提示→点击\"创建密码\"。\n\n【应会操作】启用来宾账户的操作路径：\n控制面板→用户帐户和家庭安全→用户帐户→管理其他帐户→Guest来宾帐户→点击\"启用\"。\n\n【常见错误】\n1. 日常使用管理员账户——为了安全，日常操作建议用标准账户，管理员账户只在需要时切换使用。\n2. Administrator和普通管理员搞混——Administrator是系统内置超级管理员，默认禁用，权限比普通管理员更高。\n3. 来宾账户不设密码也不安全——来宾虽然权限低，但仍可能访问共享文件夹，不用时应禁用。\n\n【出题方向】\n常考选择题\"Windows 7中默认被禁用的内置管理员账户是____\"（Administrator）。填空题\"Windows 7中适用于日常使用的账户类型是____\"（标准账户）。判断题\"来宾账户（Guest）可以安装和卸载软件\"（错）。实操题\"在Windows中创建一个名为\'学生\'的标准账户并设置密码\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(742,740,4,4,'来宾账户','# 来宾账户\n\n【一句话定义】\n来宾账户主要针对需要临时使用计算机的用户，Windows 7内置的来宾帐户名为Guest，默认情况下没有启用。\n\n【应会操作】\n\n来宾账户的权限：临时使用计算机、上网浏览、运行已安装的程序。来宾账户的限制：不能安装软件、不能修改系统设置、不能访问其他用户的文件、不能创建密码、关机后所有操作记录和个人数据都会消失。使用场景：有客人临时借用你的电脑查个资料，启用来宾账户既方便客人使用，又不用担心自己的文件被看到或系统被修改。\n\n【常见错误】\n1. 以为来宾账户和标准账户一样——来宾账户权限更低，连文件都保存不了。\n2. 不知道来宾账户默认未启用——需要在控制面板→用户帐户中手动启用。\n3. 长期启用来宾账户——有安全风险，建议需要时再启用，用完禁用。\n\n【出题方向】\n常考选择题\"来宾帐户的特点是\"（临时使用、权限最低、默认未启用）。填空题\"Windows 7内置的来宾帐户名为____，默认情况____\"（Guest、没有启用/未启用）。判断题\"来宾用户可以安装软件\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(743,740,4,4,'标准账户','# 标准账户\n\n【一句话定义】\n标准账户适用于日常计算机的使用，用户创建的帐户默认为标准用户；标准用户可防止用户做出对该计算机的所有用户或安全造成影响的更改，从而保护计算机系统。\n\n【应会操作】\n\n标准账户能做什么：上网浏览、写文档、玩游戏、修改自己的个性化设置（桌面背景、屏幕保护等）。标准账户不能做什么：安装软件、卸载软件、修改系统设置、删除其他用户的文件、创建或删除用户账户。学校机房给学生用的通常是标准账户——学生可以正常学习但不能乱装游戏或修改系统。\n\n【常见错误】\n1. 以为标准账户什么都做不了——标准账户能满足日常办公、上网、娱乐等绝大多数需求。\n2. 标准账户不能装软件就以为是坏了——这是正常限制，需要管理员权限才能安装软件。\n3. 不知道自己的账户类型——控制面板→用户帐户和家庭安全→用户帐户可以看到当前账户类型。\n\n【出题方向】\n常考选择题\"标准用户不能进行的操作是\"（安装软件/修改系统设置）。填空题\"用户创建的帐户默认为____用户\"（标准）。判断题\"标准用户可以防止对计算机安全造成影响的更改\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(744,740,4,4,'管理员账户','# 管理员账户\n\n【一句话定义】\n管理员账户可以对计算机进行最高级别的控制，但应该只在必要时才使用；Administrator是Windows 7系统保留的管理员账户，默认情况下被禁用。\n\n【具体例子】\n管理员账户的权限：安装和卸载软件、修改系统设置、创建和删除其他用户账户、访问所有文件（包括其他用户的文件）。学校机房中，老师用的通常是管理员账户——可以安装教学软件、管理学生账户。Administrator是系统内置的超级管理员账户，权限比普通管理员更高，默认被禁用（隐藏），只有在需要进行高级管理时才启用（如系统修复、密码重置）。日常使用建议用标准账户，需要管理操作时再切换到管理员账户。\n\n【常见错误】\n1. 日常使用管理员账户——为了安全，日常操作建议用标准账户，防止误操作或病毒感染。\n2. Administrator和普通管理员搞混——Administrator是系统保留的超级管理员，权限更高，默认禁用。\n3. 以为管理员可以为所欲为——虽然权限高，但删除系统文件同样会导致系统崩溃。\n\n【出题方向】\n常考选择题\"下列关于管理员账户的说法正确的是\"（可以对计算机进行最高级别的控制）。填空题\"Administrator管理员帐户默认情况下被____\"（禁用）。判断题\"管理员帐户可以创建和删除其他用户帐户\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(745,728,4,3,'任务5维护Windows',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(746,745,4,4,'磁盘分区MBR与GPT','# 磁盘分区（MBR与GPT）\n\n【一句话定义】\n磁盘分区是把一个物理硬盘划分为多个逻辑区域的技术；MBR（主引导记录）是传统分区方式最多支持4个主分区，GPT（GUID分区表）是新标准支持更多分区和超过2TB的大容量硬盘。\n\n【具体说明】\n分区基本概念：主分区——可直接安装操作系统，最多4个（MBR）或128个（GPT）；扩展分区——一种特殊主分区，不能直接使用，必须划分为逻辑分区；逻辑分区——在扩展分区内创建，用于存储数据。\n\n【应会操作】创建磁盘分区的完整操作路径：\n第一步：打开磁盘管理。右击\"计算机\"（或\"我的电脑\"）→选择\"管理\"→展开\"存储\"→点击\"磁盘管理\"。\n\n第二步：压缩卷获取未分配空间。右击要分区的磁盘（如D盘）→选择\"压缩卷\"→输入要压缩的空间大小（MB）→点击\"压缩\"。完成后会出现一块\"未分配\"的黑色区域。\n\n第三步：新建简单卷。右击\"未分配\"区域→选择\"新建简单卷\"→弹出新建简单卷向导→点击\"下一步\"。\n\n第四步：设置卷大小。输入新建分区的大小（默认全部未分配空间）→点击\"下一步\"。\n\n第五步：分配驱动器号。选择一个盘符（如E:）→点击\"下一步\"。\n\n第六步：格式化分区。文件系统选择NTFS（推荐），分配单元大小默认，卷标输入分区名称（如\"数据盘\"），勾选\"执行快速格式化\"→点击\"下一步\"→点击\"完成\"。\n\nMBR与GPT对比：MBR最多4个主分区，最大支持2TB硬盘；GPT支持128个主分区，最大支持18EB（约180亿GB），兼容性：Windows 7 64位支持GPT，32位不支持从GPT磁盘启动。\n\n【常见错误】\n1. 系统盘分区时选错磁盘——磁盘管理中一定要确认选的是数据盘而非系统盘，误操作系统盘会导致无法开机。\n2. 不知道扩展分区不能直接存数据——扩展分区必须先创建逻辑分区才能使用。\n3. GPT磁盘在32位Win7上无法启动——老旧系统不支持GPT启动。\n\n【出题方向】\n常考选择题\"MBR分区表最多支持____个主分区\"（4）。填空题\"在Windows磁盘管理中，新建分区前需要先____获得未分配空间\"（压缩卷）。判断题\"GPT分区表支持超过2TB的硬盘\"（对）。实操题\"请使用磁盘管理工具将D盘压缩出20GB空间并新建一个E盘分区（NTFS格式）\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(747,745,4,4,'磁盘碎片整理','# 磁盘碎片整理\n\n【一句话定义】\n磁盘碎片是硬盘读写过程中产生的不连续文件片段，碎片过多会降低系统性能；Windows 7的磁盘碎片整理程序可以重新整理文件、优化磁盘性能，提高文件读取速度。\n\n【具体说明】\n碎片产生原因：文件写入时，磁盘会寻找空闲空间存放，一个文件可能被分散存放在磁盘的不同位置。长期频繁的创建、删除、修改文件后，碎片越来越多，导致磁头需要移动到多个位置才能读取完整文件，速度变慢。\n\n【应会操作】磁盘碎片整理的完整操作路径：\n第一步：打开磁盘碎片整理程序。点击开始菜单→所有程序→附件→系统工具→磁盘碎片整理程序。\n\n第二步：分析磁盘。在磁盘碎片整理程序窗口中，选中要整理的磁盘（如C:）→点击\"分析磁盘\"按钮→等待分析完成（1-5分钟）→查看碎片百分比。\n\n第三步：开始整理（如需要）。如果碎片百分比超过10%，选中该磁盘→点击\"磁盘碎片整理\"按钮→等待整理完成（20分钟到数小时，取决于磁盘大小和碎片程度）→可以在此期间使用计算机，但性能可能受影响。\n\n第四步：配置计划（可选）。点击\"配置计划\"→勾选\"按计划运行\"→设置频率（每天/每周/每月）、日期、时间→选择要整理的磁盘→点击\"确定\"。\n\n重要注意：固态硬盘（SSD）不需要碎片整理——SSD通过闪存芯片存储数据，随机读取速度与顺序读取速度相同，不存在机械寻道延迟；而且碎片整理会增加SSD的写入次数，缩短使用寿命。Windows 7会自动检测SSD并禁用对其的碎片整理计划。\n\n【常见错误】\n1. 以为SSD也需要碎片整理——SSD不需要，碎片整理会增加写入次数缩短寿命。\n2. 碎片整理和磁盘清理搞混——碎片整理是重排文件提高读取速度，磁盘清理（cleanmgr）是删除临时文件释放空间。\n3. 整理过程中强制关机或重启——可能导致数据损坏，应让整理程序完成后再关机。\n\n【出题方向】\n常考选择题\"磁盘碎片整理的作用是\"（优化磁盘性能/提高文件读取速度）。填空题\"____硬盘会产生碎片需要定期整理，____硬盘不需要碎片整理\"（机械/HDD、固态/SSD）。判断题\"固态硬盘也需要定期进行碎片整理\"（错）。实操题\"请打开磁盘碎片整理程序，分析C盘的碎片情况\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(748,745,4,4,'磁盘碎片的产生与影响','# 磁盘碎片的产生与影响\n\n【一句话定义】\n磁盘碎片是硬盘读写过程中产生的不连续文件，使用虚拟内存、频繁读写硬盘、下载大文件都会产生碎片；碎片过多会增加寻道时间，影响系统效能。\n\n【具体例子】\n碎片产生的原因：①使用虚拟内存时频繁读写硬盘；②硬盘上非连续写入的文件；③网上下载大文件时产生碎片。碎片的影响：读取文件时需要在多个碎片之间跳转，增加了等待盘片旋转到指定扇区和磁头切换磁道所需的寻道时间，导致系统变慢。就像一本书的章节被打乱散放在图书馆各处，读完一本书需要跑很多地方，效率很低。\n\n【常见错误】\n1. 以为SSD也会产生碎片——固态硬盘（SSD）不需要碎片整理。\n2. 碎片整理和磁盘清理搞混——碎片整理是重排文件，磁盘清理是删除临时文件。\n3. 碎片整理很频繁——一两个月做一次就够了，过度整理反而损耗硬盘。\n\n【出题方向】\n常考选择题\"磁盘碎片过多会影响系统的____\"（效能/性能）。填空题\"使用____时频繁读写硬盘，会产生大量碎片\"（虚拟内存）。判断题\"磁盘碎片是硬盘读写过程中产生的不连续文件\"（对）。简答题\"简述磁盘碎片的产生原因及影响\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(749,745,4,4,'系统备份与镜像恢复','# 系统备份与镜像恢复\n\n【一句话定义】\nWindows 7的\"备份和还原\"功能可以将整个系统分区（C盘）制作成系统镜像备份到外部硬盘或光盘，当系统严重损坏无法启动时，可通过镜像文件将系统恢复到备份时的状态。\n\n【具体操作步骤】\n创建系统镜像备份：\n第一步：打开备份和还原。开始菜单→控制面板→系统和安全→备份和还原→点击左侧\"创建系统映像\"。\n\n第二步：选择保存位置。选择\"在硬盘上\"→在下拉列表中选择外部硬盘或另一个分区（不能选系统分区本身）→点击\"下一步\"。也可以选择\"在一张或多张DVD上\"刻录到光盘。\n\n第三步：确认备份内容。默认勾选\"包括系统驱动器的系统映像（推荐）\"，也可以勾选其他分区一起备份→点击\"开始备份\"。\n\n第四步：等待备份完成。系统开始创建镜像文件（.vhd格式），耗时取决于系统分区大小和硬盘速度（通常20-60分钟），完成后会提示是否创建系统修复光盘。\n\n从镜像恢复系统：\n第一步：进入系统恢复环境。方法1：开机按F8→选择\"修复计算机\"；方法2：使用系统安装光盘或恢复盘启动→选择\"修复计算机\"。\n\n第二步：选择恢复方式。进入\"系统恢复选项\"→选择\"使用以前创建的系统映像恢复计算机\"。\n\n第三步：选择镜像文件。系统自动搜索可用的系统镜像→选择要恢复的镜像文件→选择日期（如果有多个备份）。\n\n第四步：开始恢复。确认恢复操作（注意：恢复会覆盖当前系统分区所有数据）→点击\"完成\"→等待恢复完成（通常20-40分钟）。\n\n与系统还原的区别：系统还原只还原系统文件和设置（利用还原点），不影响个人文件；系统镜像恢复是将整个分区还原到备份时的状态，之后所有的更改都会丢失，恢复更彻底。\n\n【常见错误】\n1. 把系统镜像保存在系统分区上——镜像必须保存在其他分区或外部硬盘，否则无法恢复。\n2. 恢复前没备份个人数据——镜像恢复会覆盖系统分区的所有内容，桌面、文档等个人文件也会丢失。\n3. 系统还原和系统镜像搞混——还原点是轻量级恢复（只还原系统文件），镜像是重量级恢复（整个分区还原）。\n\n【出题方向】\n常考选择题\"Windows 7的系统镜像备份文件扩展名是____\"（.vhd）。填空题\"系统镜像恢复会将____的所有数据恢复到备份时的状态\"（系统分区/C盘）。判断题\"系统镜像备份可以保存在系统分区（C盘）上\"（错）。简答题\"简述系统镜像备份与系统还原的区别\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(750,745,4,4,'系统还原','# 系统还原\n\n【一句话定义】\n系统还原是Windows 7将计算机恢复到之前某个正常状态（还原点）的功能，用于解决系统故障；还原点包含系统文件、安装的程序、注册表设置等信息，可以自动或手动创建。\n\n【具体说明】\n还原点保存内容：系统文件、驱动程序、已安装程序、Windows注册表设置。不保存内容：个人文件（文档、照片、邮件等）不受影响。\n\n【应会操作】执行系统还原的完整操作路径：\n第一步：打开系统还原。点击开始菜单→所有程序→附件→系统工具→系统还原→弹出系统还原向导→点击\"下一步\"。\n\n第二步：选择还原点。在还原点列表中选择一个日期（选择问题出现之前的还原点）→可以点击\"扫描受影响的程序\"查看哪些程序会受影响→点击\"下一步\"。\n\n第三步：确认还原。查看还原点信息确认无误→点击\"完成\"→弹出确认对话框点击\"是\"→系统开始还原（约10-30分钟）→自动重启。\n\n【应会操作】手动创建还原点的完整操作路径：\n第一步：打开系统保护设置。右击\"计算机\"→选择\"属性\"→点击左侧\"系统保护\"。\n\n第二步：创建还原点。在\"系统属性\"对话框中确认系统盘（C:）的保护状态为\"已打开\"→点击\"创建\"按钮。\n\n第三步：输入描述。输入还原点名称（如\"安装Office前\"）→点击\"创建\"→等待几秒后显示\"已成功创建还原点\"→点击\"关闭\"。\n\n注意：如果系统无法正常启动，可以在开机时按F8键进入高级启动选项→选择\"修复计算机\"→选择\"系统还原\"→从还原列表中选择还原点进行恢复。\n\n【常见错误】\n1. 以为系统还原会删除个人文件——不会，还原只影响系统文件和程序，文档照片等个人文件不受影响。\n2. 没有提前创建还原点——等到系统出问题了才发现没有可用的还原点，应在安装重要软件前手动创建。\n3. 系统还原和系统备份搞混——还原是回到某个时间点的系统状态（利用还原点），备份是把文件复制到外部存储保存。\n\n【出题方向】\n常考选择题\"系统还原可以恢复到____\"（之前的还原点/还原点时刻的状态）。填空题\"手动创建还原点的路径：计算机→属性→____→创建\"（系统保护）。判断题\"系统还原会删除用户的个人文档\"（错）。实操题\"请创建一个名为\'软件安装前\'的系统还原点\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(751,745,4,4,'还原点的概念与使用','# 还原点的概念与使用\n\n【一句话定义】\n还原点表示计算机系统文件的存储状态，Windows会按特定时间间隔自动创建还原点，也可以在任何时候手动创建还原点；当系统出现故障时，可以将系统还原到之前的还原点来恢复。\n\n【具体例子】\n还原点创建时机：①系统自动创建（按特定时间间隔）；②系统检测到计算机开始变化时（如安装软件前）；③用户手动创建（控制面板→系统和安全→系统→系统保护→创建）。还原操作：软件或系统出故障时，控制面板→系统和安全→系统→系统保护→系统还原→选择一个还原点→还原。还原效果：系统文件和设置恢复到还原点时的状态，但个人文档（如Word文件、照片等）不会丢失。\n\n【常见错误】\n1. 以为还原点会删除个人文件——不会，系统还原只影响系统文件和程序设置。\n2. 没有提前创建还原点——等到系统出问题了才发现没有可用的还原点。\n3. 系统还原和系统备份搞混——还原是回到某个时间点，备份是把文件复制到别处保存。\n\n【出题方向】\n常考选择题\"还原点表示计算机____的存储状态\"（系统文件）。填空题\"Windows会按____创建还原点，也可以在任何时候____创建\"（特定时间间隔、手动）。判断题\"系统还原会删除用户的个人文档\"（错）。简答题\"简述还原点的作用及创建方法\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(752,728,4,3,'任务6使用CMD命令',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(753,752,4,4,'CD改变当前目录命令','# CD命令（改变当前目录）\n\n【一句话定义】\nCD命令用于改变或显示当前目录，CD 文件夹名进入子目录，CD..返回上级目录，CD\\返回根目录。\n\n【具体例子】\nCD \\EXAM —— 将当前目录改为EXAM文件夹（从根目录进入）；CD.. —— 返回上级目录；CD\\ —— 返回当前磁盘的根目录。注意：命令提示符显示的路径会随CD命令而改变，如C:\\Users\\dell>cd \\exam后，提示符变为C:\\EXAM>。\n\n【应会操作】CD命令的使用示例：\n基本格式：CD [路径] 或 CHDIR [路径]\n常用示例：\n- CD..——返回上一级目录。\n- CD\\——直接返回根目录。\n- CD D:——切换到D盘根目录。\n- CD D:\\Games——切换到D盘Games目录。\n- D:——直接切换到D盘当前目录。\n- CD \"C:\\Program Files\"——切换到含空格的目录路径（需加引号）。\n\n注意：切换不同磁盘分区时，需要先输入盘符（如D:）再CD。CMD提示符中显示的当前路径会随CD命令改变。\n\n【常见错误】\n1. CD和CD..搞混——CD后面跟文件夹名是进入，CD..是两个点表示返回上级。\n2. CD\\和CD搞混——CD\\返回根目录，CD进入指定文件夹。\n3. 不知道命令提示符会显示当前路径——看提示符就能知道自己现在在哪个目录。\n\n【出题方向】\n常考选择题\"返回上级目录的命令是\"（CD..）。填空题\"CD\\的作用是返回____\"（根目录）。判断题\"CD..可以返回上级目录\"（对）。实操题\"使用CD命令进入D盘的一个子文件夹，然后返回上级目录\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(754,752,4,4,'CMD命令提示符的概念','# CMD命令提示符的概念\n\n【一句话定义】\nCMD是Windows的命令提示符，通过\"命令提示符\"窗口可以运行常用的CMD命令完成相应任务，甚至可以完成图形界面不易完成或不易观察的操作结果（如网络测试命令的执行）。\n\n【具体例子】\n打开CMD的方法：开始菜单→所有程序→附件→命令提示符。关闭CMD的方法：①点击窗口右上角的关闭按钮；②在命令提示符后输入EXIT命令→回车。CMD的作用：虽然Windows有图形界面可以完成大多数操作，但有些操作用命令更高效（如批量重命名文件），有些操作只能命令完成（如网络测试ping命令）。\n\n【常见错误】\n1. 以为CMD是病毒——CMD是Windows自带的合法工具，不是病毒。\n2. 不知道怎么打开CMD——记住路径：开始→所有程序→附件→命令提示符。\n3. 命令输错就放弃——CMD命令对大小写不敏感，输错了看提示信息再试。\n\n【出题方向】\n常考填空题\"CMD是Windows的____\"（命令提示符）。选择题\"打开命令提示符的路径是\"（开始→所有程序→附件→命令提示符）。判断题\"CMD只能完成图形界面能完成的操作\"（错，有些操作只能命令完成）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(755,752,4,4,'CMD常用命令','# CMD常用命令\n\n【一句话定义】\nCMD（命令提示符）是Windows的命令行界面，通过输入文本命令完成文件管理、系统操作等任务，常用命令包括DIR、CD、MD、RD、COPY、DEL、TYPE、ATTRIB等。\n\n【具体例子】\n打开CMD：开始→搜索框输入cmd→回车。常用命令：①DIR——显示目录文件列表（DIR /W宽屏显示、DIR /P满屏暂停）；②CD——切换目录（CD 文件夹名 进入，CD.. 返回上级，CD\\ 返回根目录）；③MD——创建文件夹（MD 文件夹名）；④RD——删除空文件夹（RD 文件夹名）；⑤COPY——复制文件（COPY 源文件 目标位置）；⑥DEL——删除文件（DEL 文件名，支持通配符如DEL *.tmp）；⑦TYPE——显示文本文件内容（TYPE 文件名.txt）；⑧ATTRIB——显示/修改文件属性（ATTRIB +R 文件名 设为只读）。\n\n【常见错误】\n1. CMD命令记不住——重点记DIR（看）、CD（进）、MD（建）、RD（删文件夹）、COPY（复制）、DEL（删文件）。\n2. 路径写错——CMD中路径用反斜杠\\，不能用斜杠/。\n3. DEL和RD搞混——DEL删文件，RD删空文件夹（有文件的文件夹要先用DEL删文件）。\n\n【出题方向】\n常考选择题\"显示目录文件列表的命令是\"（DIR）、\"创建文件夹的命令是\"（MD）。也常考填空题\"切换目录的命令是____\"（CD）。判断题\"DEL命令可以删除文件夹\"（错，DEL删文件，RD删文件夹）。实操题\"使用CMD命令完成创建文件夹、复制文件、删除文件的操作\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(756,752,4,4,'COPY复制文件命令','# COPY命令（复制文件）\n\n【一句话定义】\nCOPY命令用于复制文件，可以复制单个文件、改名复制，也可以将多个文件合并成一个文件。\n\n【具体例子】\n复制单个文件：COPY C:\\ABC\\FENG1.JPG D:\\TEST\\IMG\\QILIU.JPG —— 将C盘ABC文件夹下的FENG1.JPG复制到D盘TEST\\IMG下，并改名为QILIU.JPG。合并文件：COPY A.TXT+B.TXT AB.TXT —— 将当前目录中的A.TXT和B.TXT合并成一个新文件AB.TXT。注意：目标路径的文件夹必须已存在，COPY不会自动创建目标文件夹。\n\n【应会操作】COPY命令的使用示例：\n基本格式：COPY 源文件 [目标路径][新文件名]\n常用示例：\n- COPY file.txt D:\\Backup——将file.txt复制到D盘Backup文件夹。\n- COPY C:\\file.txt D:\\newfile.txt——复制并重命名。\n- COPY *.txt D:\\Backup——将所有txt文件复制到目标文件夹（通配符批量复制）。\n- COPY file1.txt + file2.txt file3.txt——将两个文件合并成一个。\n\nXCOPY（复制文件夹及其内容）：\n- XCOPY C:\\Source D:\\Backup /S——复制Source文件夹及其子文件夹到Backup（/S包含子目录）。\n- XCOPY C:\\Source D:\\Backup /E——复制包括空子目录在内的所有内容。\n\nMOVE（移动文件/重命名）：\n- MOVE file.txt D:\\Backup——将文件移动到目标位置。\n- MOVE oldname.txt newname.txt——在同一目录下重命名文件。\n\n【常见错误】\n1. 目标文件夹不存在以为会自动创建——COPY不会自动创建目标文件夹，需先用MD创建。\n2. 复制和移动搞混——COPY是复制（原文件还在），MOVE才是移动。\n3. 合并文件时顺序写错——A.TXT+B.TXT和B.TXT+A.TXT结果不同。\n\n【出题方向】\n常考选择题\"COPY命令的功能是\"（复制文件）。填空题\"COPY A.TXT+B.TXT AB.TXT的作用是____\"（合并两个文件）。判断题\"COPY命令在复制时可以改名\"（对）。实操题\"使用COPY命令将一个文件复制到另一个文件夹并改名\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(757,752,4,4,'DEL删除文件命令','# DEL命令（删除文件）\n\n【一句话定义】\nDEL命令用于删除文件，支持通配符批量删除，删除前务必确认不要误删重要文件。\n\n【具体例子】\n删除单个文件：DEL C:\\TEST\\READ.TXT —— 删除C盘TEST文件夹中的READ.TXT文件。删除某文件夹下所有文件：DEL C:\\PHOTO —— 删除C盘PHOTO文件夹中的所有文件（注意：只删文件不删文件夹本身）。使用通配符：DEL C:\\TEMP\\*.TMP —— 删除C盘TEMP文件夹中所有扩展名为TMP的临时文件。\n\n【应会操作】DEL命令的使用示例：\n基本格式：DEL [路径]文件名 或 ERASE [路径]文件名\n常用示例：\n- DEL file.txt——删除当前目录中的file.txt。\n- DEL C:\\Temp\\*.tmp——删除Temp目录中所有.tmp临时文件（使用通配符批量删除）。\n- DEL /F file.txt——强制删除只读文件。\n- DEL /S *.log——删除当前目录及所有子目录中的.log文件。\n- DEL /Q *.bak——安静模式删除（不提示确认）。\n\n注意：DEL删除的文件不进入回收站，直接永久删除！删除前务必确认路径和文件名正确。\n\n【常见错误】\n1. DEL和RD搞混——DEL删文件，RD删空文件夹。\n2. DEL *.*不加确认——删除所有文件前系统会提示确认，一定要看清楚再按Y。\n3. 以为DEL会删除文件夹——DEL只删文件，文件夹还在（变空了）。\n\n【出题方向】\n常考选择题\"删除文件的命令是\"（DEL）。填空题\"DEL C:\\PHOTO的作用是删除该文件夹下的所有____\"（文件）。判断题\"DEL命令可以删除文件夹\"（错，只删文件）。实操题\"使用DEL命令删除指定文件\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(758,752,4,4,'DIR显示文件目录命令','# DIR命令（显示文件目录）\n\n【一句话定义】\nDIR命令用于显示指定目录下的文件和文件夹列表，支持/P（满屏暂停）、/W（宽屏显示）、/S（含子目录）等参数。\n\n【具体例子】\n基本用法：DIR D:\\ 显示D盘根目录下所有文件和文件夹。常用参数：DIR D:\\ /P —— 满屏暂停，按任意键继续显示；DIR D:\\ /W —— 宽屏显示（每行显示多个文件名）；DIR D:\\ /S —— 显示D盘根目录及所有子目录中的文件；DIR D:\\ /P/S —— 组合使用：满屏暂停+包含子目录。注意：参数可以组合使用，如/P和/S同时用就是DIR D:\\ /P/S。\n\n【应会操作】DIR命令的使用示例：\n基本格式：DIR [路径] [参数]\n常用示例：\n- DIR——显示当前目录中的文件和子目录列表。\n- DIR C:\\Users——显示指定目录的内容。\n- DIR /W——以宽列表格式显示（每行多个文件名）。\n- DIR /P——分屏显示，每满一页暂停，按任意键继续。\n- DIR /S——显示当前目录及所有子目录中的文件（递归显示）。\n- DIR *.txt——只显示扩展名为.txt的文件。\n- DIR /A:H——显示隐藏文件。\n- DIR /O:N——按文件名字母顺序排序显示。\n- DIR /T:C——按创建时间排序显示。\n\nDIR命令显示的信息：文件名、文件大小（字节）、创建日期和时间、文件总数和总大小。\n\n【常见错误】\n1. 参数前不加斜杠——参数必须以/开头，如/P不是P。\n2. /P和/S组合时参数顺序写错——参数顺序不影响，/P/S和/S/P效果一样。\n3. 路径格式写错——Windows路径用反斜杠\\，如D:\\不是D://。\n\n【出题方向】\n常考选择题\"DIR命令中/P参数的作用是\"（满屏暂停）。填空题\"DIR命令中____参数表示宽屏显示\"（/W）。判断题\"DIR /S可以显示当前目录及其子目录中的所有文件\"（对）。实操题\"使用DIR命令显示D盘根目录下的文件列表，要求满屏暂停\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(759,752,4,4,'FORMAT格式化磁盘命令','# FORMAT命令（格式化磁盘）\n\n【一句话定义】\nFORMAT命令用于格式化磁盘，可以指定文件系统（如NTFS），支持/Q参数进行快速格式化。\n\n【具体例子】\n基本格式：FORMAT [盘符:] [/FS:文件系统] [/Q]。示例：FORMAT G: /FS:NTFS /Q —— 快速将G盘（如U盘）格式化为NTFS文件系统。参数说明：/FS:NTFS指定文件系统为NTFS；/Q表示快速格式化（只清除文件分配表，不检查坏道）。注意：格式化会清空磁盘上所有数据，操作前务必备份重要文件！\n\n【应会操作】FORMAT命令的使用示例：\n基本格式：FORMAT 盘符: [参数]\n常用示例：\n- FORMAT D:——格式化D盘（会提示确认，需按Y确认）。\n- FORMAT D: /Q——快速格式化（只删除文件分配表，不检查坏扇区，速度快）。\n- FORMAT D: /FS:NTFS——格式化并指定文件系统为NTFS。\n- FORMAT D: /V:数据盘——格式化并设置卷标为\"数据盘\"。\n- FORMAT D: /Q /FS:NTFS /V:数据盘——组合参数：快速格式化+NTFS+卷标。\n\n注意：格式化会删除磁盘上所有数据，操作前务必备份重要文件！系统盘（通常是C:）不能在Windows运行状态下格式化。\n\n【常见错误】\n1. 格式化前不备份——格式化会清空所有数据，操作前必须确认无重要文件。\n2. 快速格式化和完全格式化搞混——/Q是快速格式化（快但不检查坏道），不加/Q是完全格式化（慢但检查坏道）。\n3. 格式化系统盘——不要格式化C盘（系统盘），否则系统会被删除。\n\n【出题方向】\n常考选择题\"FORMAT G: /FS:NTFS /Q命令的作用是\"（快速格式化G盘为NTFS）。填空题\"FORMAT命令中____参数表示快速格式化\"（/Q）。判断题\"格式化磁盘不会删除数据\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(760,752,4,4,'MD新建文件夹命令','# MD命令（新建文件夹）\n\n【一句话定义】\nMD（或MKDIR）命令用于新建文件夹，如果父文件夹不存在会自动创建。\n\n【具体例子】\n基本格式：MD [盘符:][路径]\\文件夹名。示例：MD D:\\TEST\\IMG —— 在D盘TEST文件夹下新建IMG文件夹；如果D盘根目录下没有TEST文件夹，系统会自动先创建TEST文件夹，再在TEST下创建IMG文件夹。MKDIR D:\\A\\B\\C —— 作用同MD，可以一次性创建多级嵌套的文件夹。\n\n【应会操作】MD命令的使用示例：\n基本格式：MD [路径]文件夹名 或 MKDIR [路径]文件夹名\n常用示例：\n- MD Test——在当前目录下创建名为Test的文件夹。\n- MD C:\\Users\\Admin\\Documents\\备份——在指定路径创建文件夹（可一次创建多级目录）。\n- MD \"My Documents\"——创建含空格的文件夹名（需加引号）。\n\n配套命令RD（删除文件夹）：\n- RD Test——删除空文件夹Test。\n- RD /S Test——删除Test文件夹及其所有内容（包括子文件夹和文件）→会提示确认。\n- RD /S /Q Test——强制删除不提示确认（/Q安静模式）。\n\n【常见错误】\n1. MD和MKDIR搞混——两者功能完全相同，可以互换使用。\n2. 父文件夹不存在就以为会报错——MD命令会自动创建不存在的父文件夹。\n3. 路径格式写错——用反斜杠\\分隔路径层级。\n\n【出题方向】\n常考选择题\"新建文件夹的命令是\"（MD或MKDIR）。填空题\"MD D:\\TEST\\IMG命令的作用是____\"（在D盘TEST下新建IMG文件夹）。判断题\"MD命令在父文件夹不存在时会报错\"（错，会自动创建）。实操题\"使用MD命令在D盘根目录下创建A\\B\\C多级文件夹\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(761,752,4,4,'REN重命名命令','# REN命令（重命名文件和文件夹）\n\n【一句话定义】\nREN（或RENAME）命令用于重命名文件和文件夹，格式为REN [盘符:][路径]原文件名 新文件名。\n\n【具体例子】\n重命名文件：REN C:\\ABC\\FENG2.JPG HELIU.JPG —— 将C盘ABC文件夹下的FENG2.JPG重命名为HELIU.JPG。重命名文件夹：REN C:\\ABC EXAM —— 将C盘根目录下的ABC文件夹重命名为EXAM。注意：REN只能改名，不能改变文件位置（不能加路径把文件移到别处）。\n\n【应会操作】REN命令的使用示例：\n基本格式：REN [路径]原文件名 新文件名\n常用示例：\n- REN old.txt new.txt——将old.txt重命名为new.txt。\n- REN C:\\Backup\\file.doc document.doc——重命名指定路径的文件。\n- REN *.txt *.bak——将所有txt文件的扩展名改为bak（批量重命名）。\n- REN \"My Document.txt\" \"My Document.doc\"——重命名含空格的文件（需加引号）。\n\n注意：REN只能重命名，不能改变文件位置（移动文件用MOVE）。不能为目标文件指定路径（只能在原位置改名）。\n\n【常见错误】\n1. REN和MOVE搞混——REN只是改名（位置不变），MOVE是移动位置。\n2. 重命名时加了目标路径——REN不能改变位置，只能改名字。\n3. REN和RENAME搞混——两者功能完全相同。\n\n【出题方向】\n常考选择题\"重命名文件的命令是\"（REN或RENAME）。填空题\"REN C:\\ABC\\FENG2.JPG HELIU.JPG的作用是将文件____\"（重命名为HELIU.JPG）。判断题\"REN命令可以改变文件的位置\"（错，只能改名）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(762,439,4,2,'单元7使用Windows附件',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(763,762,4,3,'任务1使用记事本和写字板',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(764,763,4,4,'写字板与记事本的区别','# 写字板与记事本的区别\n\n【一句话定义】\n记事本是纯文本编辑器，只能编辑.txt文件，功能简单；写字板支持格式设置、插入图片等，可以编辑.rtf、.docx、.odt等格式文件，功能更丰富。\n\n【具体例子】\n界面区别：记事本有菜单栏（文件、编辑、格式、查看、帮助），写字板有功能区（主页、查看选项卡）。功能区别：记事本只能设置整个文档的字体（格式→字体），不能插入图片，保存为.txt；写字板可以设置局部文字的字体、颜色、大小，可以插入图片和对象，保存为.rtf（ rich text format，富文本格式）或.docx。使用场景：记事本适合写代码、记简单笔记（打开速度快）；写字板适合写带格式的文档（如简单的报告、信件）。\n\n【常见错误】\n1. 以为记事本和写字板功能一样——写字板比记事本功能强大得多。\n2. 记事本保存为.docx——记事本保存为.txt，用记事本打开.docx会显示乱码。\n3. 不知道写字板能保存为Word格式——写字板可以打开和编辑.docx文件。\n\n【出题方向】\n常考选择题\"下列说法正确的是\"（写字板可以插入图片，记事本不能）。填空题\"记事本保存的文件扩展名是____，写字板默认保存的文件扩展名是____\"（.txt、.rtf）。判断题\"记事本和写字板的功能完全相同\"（错）。简答题\"比较记事本和写字板的主要区别\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(765,763,4,4,'写字板窗口组成','# 写字板窗口组成\n\n【一句话定义】\n写字板（WordPad）是Windows 7自带的多功能文本编辑工具，窗口由标题栏（含快捷访问工具栏）、功能区（含\"主页\"和\"查看\"选项卡）、标尺和缩放栏、文档编辑区四部分组成。\n\n【具体例子】\n标题栏：左侧是快捷访问工具栏，默认有\"保存\"\"撤销\"\"重做\"三个按钮；中间显示文档名；右侧是最小化、最大化和关闭按钮。标尺和缩放栏：标尺提供文字位置的参考依据，通过标尺可以控制文字的缩进位置；缩放栏用于调整文档的显示比例，拖动滑块可以放大或缩小显示。功能区：由\"写字板\"按钮（新建、打开、保存、打印等）、\"主页\"选项卡（文字编辑按钮：字体、段落、插入对象等）和\"查看\"选项卡（查看文档的工具）组成。文档编辑区：用于输入和编辑，结合\"主页\"选项卡可以完成各种编辑任务。\n\n【应会操作】写字板的基本操作：\n启动：开始菜单→所有程序→附件→写字板。\n保存文件：文件→保存（Ctrl+S）→选择保存位置→输入文件名→保存类型可选RTF文档(*.rtf)、文本文档(*.txt)、Office Open XML文档(*.docx)→保存。\n格式化文字：选中文字→在\"主页\"选项卡中设置字体/字号/颜色/加粗/倾斜/下划线/删除线/下标/上标/突出显示。\n段落设置：主页→对齐方式（左对齐/居中/右对齐）→缩进→行距→项目符号/编号。\n插入对象：插入→图片→选择图片文件插入；插入→绘图→打开画图；插入→日期和时间。\n页面设置：文件→页面设置→设置纸张大小/方向/页边距。\n打印预览：文件→打印预览→查看打印效果→打印。\n\n【常见错误】\n1. 写字板和记事本搞混——写字板有功能区（像简化版Word），记事本只有菜单栏。\n2. 以为写字板就是Word——写字板功能比Word简单得多，但比记事本强大。\n3. 不会用标尺——标尺上的三角形滑块控制首行缩进和悬挂缩进。\n\n【出题方向】\n常考选择题\"写字板窗口不包括以下哪个部分\"（干扰项如\"菜单栏\"——写字板用功能区不是菜单栏）。填空题\"写字板窗口由____、____、____和____四部分组成\"（标题栏、功能区、标尺和缩放栏、文档编辑区）。判断题\"写字板的功能区包含\'主页\'和\'查看\'两个选项卡\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(766,763,4,4,'记事本窗口组成','# 记事本窗口组成\n\n【一句话定义】\n记事本（Notepad）是Windows 7自带的纯文本编辑工具，窗口由标题栏、菜单栏和文档编辑区三部分组成。\n\n【具体例子】\n标题栏：显示当前文档的名称，如\"无标题 - 记事本\"；左侧是记事本图标，右侧是最小化、最大化和关闭按钮。菜单栏：包含\"文件\"\"编辑\"\"格式\"\"查看\"\"帮助\"五组常用操作命令，单击菜单名会出现下拉菜单。文档编辑区：占据了窗口的大部分区域，用于输入和编辑文本内容。记事本只能编辑纯文本（.txt），不能设置字体颜色、不能插入图片，保存的文件体积很小。打开方法：开始→所有程序→附件→记事本，或Win+R输入notepad回车。\n\n【应会操作】记事本的基本操作：\n启动：开始菜单→所有程序→附件→记事本。\n保存文件：文件→保存（Ctrl+S）→选择保存位置→输入文件名→保存类型选\"文本文档(*.txt)\"→保存。\n打开文件：文件→打开（Ctrl+O）→选择文件→打开。\n自动换行设置：格式→自动换行（勾选后长文本自动换行显示）。\n字体设置：格式→字体→选择字体/字形/大小（记事本只能设置全局字体，不能局部设置）。\n插入时间：编辑→时间/日期（F5键快速插入当前日期时间）。\n页面设置：文件→页面设置→设置纸张大小/方向/页边距/页眉页脚。\n打印：文件→打印（Ctrl+P）→选择打印机→打印。\n\n【常见错误】\n1. 记事本里设置字体颜色——记事本是纯文本编辑器，不能设置颜色。\n2. 记事本里插入图片——记事本只能编辑文字，不支持图片。\n3. 以为记事本和Word一样——记事本功能非常简单，没有排版功能。\n\n【出题方向】\n常考选择题\"记事本窗口不包括以下哪个部分\"（干扰项如\"功能区\"\"工具栏\"——记事本只有标题栏、菜单栏、编辑区）。填空题\"记事本窗口由____、____和____三部分组成\"（标题栏、菜单栏、文档编辑区）。判断题\"记事本可以编辑纯文本文件\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(767,763,4,4,'记事本菜单栏功能','# 记事本菜单栏功能\n\n【一句话定义】\n记事本的菜单栏包含\"文件\"\"编辑\"\"格式\"\"查看\"\"帮助\"五个菜单，分别负责文件操作、文本编辑、格式设置、查看方式和帮助信息。\n\n【具体例子】\n\"文件\"菜单：新建、打开、保存、另存为、页面设置、打印、退出。\"编辑\"菜单：撤销、剪切、复制、粘贴、删除、查找、查找下一个、替换、转到、全选、时间/日期。\"格式\"菜单：自动换行（文本到达窗口边缘时自动换到下一行）、字体（可以设置字体、字形、大小，但整个文档只能有一种字体设置）。\"查看\"菜单：状态栏（显示行号和列号）。\"帮助\"菜单：查看帮助主题、关于记事本。\n\n【常见错误】\n1. 以为记事本可以设置多种字体——记事本的\"格式\"→\"字体\"是对整个文档统一设置，不能局部设置不同字体。\n2. 找不到\"替换\"功能——在\"编辑\"菜单里有\"替换\"选项（快捷键Ctrl+H）。\n3. 不知道记事本能显示行号——勾选\"查看\"→\"状态栏\"后，底部会显示当前光标所在的行和列。\n\n【出题方向】\n常考选择题\"记事本的\'格式\'菜单中可以设置____\"（字体/自动换行）。填空题\"记事本中查看当前行号需要勾选____菜单中的____\"（查看、状态栏）。判断题\"记事本可以为文档的不同部分设置不同的字体\"（错）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(768,762,4,3,'任务2使用画图',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(769,768,4,4,'画图五大类工具','# 画图五大类工具\n\n【一句话定义】\n画图的\"主页\"选项卡提供了五大类工具：剪贴板工具、图像工具、辅助绘图工具（含文字工具）、形状工具、颜色工具。\n\n【具体例子】\n①剪贴板工具：粘贴（粘贴剪贴板内容）、剪切、复制。②图像工具：选择（矩形选择/自由图形选择）、裁剪（保留选中区域，删除其他部分）、调整大小和扭曲（改变图片尺寸）、旋转（90度旋转/翻转）。③辅助绘图工具：铅笔（手绘）、填充颜色（油漆桶，填充区域颜色）、文本（A字按钮，在图中添加文字）、橡皮擦（擦除不需要的部分）、取色器（吸取图中某处颜色）。④形状工具：直线、曲线、矩形、椭圆、多边形等，可以设置轮廓粗细和颜色。⑤颜色工具：颜色1（轮廓色）、颜色2（填充色），点击编辑颜色可以自定义颜色。\n\n【常见错误】\n1. 颜色1和颜色2搞混——颜色1是轮廓颜色，颜色2是填充颜色。\n2. 裁剪和橡皮擦搞混——裁剪是整体裁剪画布，橡皮擦是局部擦除。\n3. 不会用取色器——点击取色器工具，再点击图中某处，该颜色就成为当前颜色。\n\n【出题方向】\n常考选择题\"画图的五大类工具不包括\"（干扰项如\"滤镜工具\"——画图没有滤镜）。填空题\"画图中____工具可以吸取图中某处的颜色\"（取色器）。判断题\"画图的辅助绘图工具中包含文字工具\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(770,768,4,4,'画图图像工具详解','# 画图图像工具详解\n\n【一句话定义】\n画图的图像工具包括选择（矩形/自由图形）、裁剪、调整大小和扭曲、旋转（翻转）等功能，用于对图像进行整体操作。\n\n【具体例子】\n选择工具：矩形选择——拖动鼠标画矩形框选中区域；自由图形选择——画任意形状选中不规则区域。裁剪工具：先用选择工具选中要保留的区域，然后点击\"裁剪\"，删除选中区域以外的部分。调整大小：可以按百分比缩放或按像素指定新尺寸，勾选\"保持纵横比\"可以防止图片变形。旋转和翻转：向右旋转90度、向左旋转90度、旋转180度、垂直翻转、水平翻转。使用场景：拍的照片太大了用\"调整大小\"缩小；照片拍倒了用\"旋转\"转正；只想要照片的一部分用\"选择\"+\"裁剪\"。\n\n【常见错误】\n1. 调整大小不勾选\"保持纵横比\"——图片会被拉伸变形。\n2. 裁剪和橡皮擦搞混——裁剪是整体保留选中部分，橡皮擦是局部擦除。\n3. 旋转后保存覆盖了原图——建议\"另存为\"，保留原图。\n\n【出题方向】\n常考选择题\"要保持图片比例不变，调整大小时应勾选____\"（保持纵横比）。填空题\"画图中____工具可以删除选中区域以外的部分\"（裁剪）。判断题\"画图的旋转功能包括水平翻转和垂直翻转\"（对）。实操题\"使用画图打开一张图片，将其水平翻转后另存为\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(771,768,4,4,'画图窗口组成','# 画图窗口组成\n\n【一句话定义】\n画图（Paint）是Windows 7自带的图像编辑工具，窗口由快捷访问工具栏、\"画图\"按钮、功能区和画布四个部分组成。\n\n【具体例子】\n快捷访问工具栏：包含一些常用操作的快捷按钮。\"画图\"按钮：位于左上角，点击后打开菜单（新建、打开、保存、另存为、打印等）。功能区：包含\"画图\"按钮、\"主页\"选项卡和\"查看\"选项卡。画布：占据了窗口中间的大部分区域，是实际绘画和编辑图像的工作区域。打开画图：开始→所有程序→附件→画图。保存格式：默认保存为.png，也可以保存为.bmp、.jpg、.gif等格式。\n\n【应会操作】画图程序的基本操作：\n启动：开始菜单→所有程序→附件→画图。\n新建/打开/保存：文件→新建（Ctrl+N）；文件→打开（Ctrl+O）；文件→保存（Ctrl+S）→可选择保存为PNG/JPEG/BMP/GIF格式。\n绘制基本图形：主页→形状→选择矩形/椭圆/直线等→在画布上拖拽绘制；按住Shift键拖拽可绘制正方形/圆形/45度直线。\n填充颜色：主页→用颜色填充（颜料桶图标）→选择颜色→点击封闭区域填充。\n橡皮擦：主页→橡皮擦→选择大小→在画布上擦除。\n文字工具：主页→文本（A图标）→在画布上拖拽出文本框→输入文字→可设置字体/大小/颜色。\n裁剪和选择：主页→选择→矩形选择/自由图形选择→选中区域后→可裁剪/复制/删除/移动。\n调整大小：主页→重新调整大小→按百分比或像素调整→可勾选\"保持纵横比\"。\n旋转：主页→旋转→向右旋转/向左旋转/水平翻转/垂直翻转。\n\n【常见错误】\n1. 以为画图只能画画——画图也可以编辑照片（裁剪、调整大小、添加文字等）。\n2. 找不到保存选项——点击左上角的\"画图\"按钮，里面有\"保存\"和\"另存为\"。\n3. 画布大小不会调——拖动画布右下角的小方块可以调整画布大小。\n\n【出题方向】\n常考选择题\"画图窗口不包括以下哪个部分\"（干扰项如\"菜单栏\"——画图用功能区）。填空题\"画图窗口由____、____、____和____四部分组成\"（快捷访问工具栏、画图按钮、功能区、画布）。判断题\"画布的默认保存格式是.png\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(772,762,4,3,'任务3使用计算器',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(773,772,4,4,'标准型模式','# 标准型模式\n\n【一句话定义】\n标准型模式与日常生活中的计算器基本一样，用户可以通过鼠标单击按钮或键盘数字键区及组合键来完成基本算术运算。\n\n【具体例子】\n基本算术运算符号：加（+）、减（-）、乘（*）、除（/）、开方（√）、百分数（%）、倒数（1/x）等。操作方式：①鼠标点击计算器上的数字和运算符按钮；②用键盘上的数字键区（小键盘）输入数字和运算符；③组合键如Backspace删除最后一位、Esc清除全部、Ctrl+C复制结果。使用场景：日常购物算账、简单数学计算。\n\n【常见错误】\n1. 不知道可以用键盘输入——数字键区可以直接输入，比鼠标点更快。\n2. %按钮用法不对——计算器中的%是求百分数（如50+10%=55），不是取模运算。\n3. 1/x按钮不知道是求倒数——1/x就是求一个数的倒数（如输入5再按1/x得到0.2）。\n\n【出题方向】\n常考选择题\"标准型计算器不包括以下哪个功能\"（干扰项如\"三角函数\"——那是科学型的功能）。填空题\"标准型计算器的基本运算符号有+、-、*、/、____、____等\"（开方√、百分数%）。判断题\"标准型计算器可以用键盘数字键区输入\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(774,772,4,4,'科学型模式','# 科学型模式\n\n【一句话定义】\n科学型模式可以计算各种指数、常用函数（三角函数、对数等）、双曲线函数、反函数等，适合高中及以上数学运算。\n\n【具体例子】\n指数运算：2的10次方（输入2→x^y→10→=→1024）。三角函数：计算sin(30°)（确保选中\"度\"模式→输入30→sin→结果0.5）。对数运算：log(100)=2、ln(e)=1。双曲线函数：sinh、cosh、tanh。反函数：按Inv按钮后，sin变成arcsin，cos变成arccos。角度单位切换：计算器可以切换\"度\"（Degrees）、\"弧度\"（Radians）、\"梯度\"（Grads）三种角度单位。\n\n【常见错误】\n1. 角度单位没切换——计算三角函数时要确认是\"度\"还是\"弧度\"模式。\n2. 不知道Inv按钮作用——Inv是反函数开关，按一下sin变arcsin。\n3. 不会输入指数——用x^y按钮（如2^x输入2→x^y→x→=）。\n\n【出题方向】\n常考选择题\"科学型计算器可以计算____\"（三角函数/对数/指数等）。填空题\"计算三角函数时需要确认角度单位是____、____或____\"（度、弧度、梯度）。判断题\"科学型模式可以计算双曲线函数\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(775,772,4,4,'程序员模式','# 程序员模式\n\n【一句话定义】\n程序员模式可以实现二进制、八进制、十进制、十六进制之间的相互转换，以及按位逻辑运算（AND、OR、NOT、XOR）。\n\n【具体例子】\n进制转换操作：①选中十进制（Dec）→输入255→点二进制（Bin）→显示11111111；②选中二进制→输入1010→点十进制→显示10；③选中十进制→输入255→点十六进制（Hex）→显示FF。按位逻辑运算：AND（与，两位都为1才为1）、OR（或，有一位为1就为1）、NOT（非，取反）、XOR（异或，不同为1相同为0）。示例：10 AND 6 = 2（二进制1010 AND 0110 = 0010）。字节显示：可以切换显示的字节数（Qword=64位、Dword=32位、Word=16位、Byte=8位）。\n\n【常见错误】\n1. 进制按钮点不动——先确认当前输入的数符合目标进制的规则（如二进制只能输0和1）。\n2. 逻辑运算和算术运算搞混——AND/OR/NOT/XOR是按位运算，不是加减乘除。\n3. 十六进制输入字母不会——程序员模式下可以直接输入A-F。\n\n【出题方向】\n常考选择题\"程序员模式可以实现____进制之间的相互转换\"（二进制、八进制、十进制、十六进制）。填空题\"按位逻辑运算包括AND、OR、____和____\"（NOT、XOR）。判断题\"程序员模式可以进行二进制到十进制的转换\"（对）。实操题\"使用程序员模式将十进制数255转换为二进制和十六进制\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(776,772,4,4,'统计信息模式','# 统计信息模式\n\n【一句话定义】\n统计信息模式加入了许多统计函数，可以输入一组数据后完成常见的统计运算，如平均值、求和、标准差等。\n\n【具体例子】\n使用方法：①切换到统计信息模式；②逐个输入数据（输入一个数→点击\"Add\"添加）；③输入完所有数据后，点击统计按钮查看结果。可以计算的统计量：平均值（Average）、求和（Sum）、标准差（Standard Deviation）、样本方差、总体方差等。示例：输入5个学生的成绩85、90、78、92、88，可以一次性计算出平均分、总分、成绩的标准差。清除数据：点击\"CAD\"清除所有已输入的数据。\n\n【常见错误】\n1. 不会添加数据——输入数字后要点击\"Add\"按钮才算添加。\n2. 和Excel的统计功能搞混——计算器统计功能比较简单，适合少量数据。\n3. 不知道CAD按钮作用——CAD是Clear All Data，清除所有已输入的统计数据。\n\n【出题方向】\n常考选择题\"统计信息模式可以计算____\"（平均值/求和/标准差等）。填空题\"在统计信息模式中，输入数据后需要点击____按钮添加\"（Add）。判断题\"统计信息模式可以计算一组数据的平均值和标准差\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(777,772,4,4,'计算器四种模式','# 计算器四种模式\n\n【一句话定义】\nWindows 7计算器有四种模式：标准型（日常计算）、科学型（指数函数等）、程序员（进制转换）、统计信息（统计运算）。\n\n【具体例子】\n切换模式：查看菜单→选择模式。①标准型：和日常计算器一样，用鼠标点击按钮或键盘数字键区输入计算。②科学型：可以计算指数（如2^10=1024）、三角函数（sin、cos、tan）、对数（log、ln）、双曲线函数、反函数等。③程序员：实现二进制、八进制、十进制、十六进制之间的相互转换，以及按位逻辑运算（与AND、或OR、非NOT、异或XOR）。④统计信息：可以输入一组数据后计算平均值、求和、标准差等统计量。\n\n【应会操作】切换计算器模式的操作路径：\n启动：开始菜单→所有程序→附件→计算器。\n切换模式：查看菜单→选择模式：\n- 标准型（Alt+1）：基本算术运算（加减乘除、百分比、平方根、倒数、取反）。\n- 科学型（Alt+2）：三角函数（sin/cos/tan）、对数（log/ln）、指数、阶乘、幂运算、角度/弧度/梯度切换。\n- 程序员（Alt+3）：二进制/八进制/十进制/十六进制转换、位运算（AND/OR/XOR/NOT）、字节字双字四字切换。\n- 统计信息（Alt+4）：求和、平均数、标准差、方差等统计运算。\n\n进制转换（程序员模式）：输入数字→点击\"十六进制\"/\"十进制\"/\"八进制\"/\"二进制\"→自动转换显示。\n单位转换：查看→单位转换→选择类型（能量/面积/长度/重量/温度等）→输入数值→自动转换。\n\n【常见错误】\n1. 找不到模式切换——在\"查看\"菜单里选择模式。\n2. 以为计算器只能加减乘除——科学型和程序员模式功能很强大。\n3. 程序员模式不会用——选中一种进制（如十进制），输入数字，再点其他进制按钮即可转换。\n\n【出题方向】\n常考选择题\"Windows 7计算器不包括以下哪种模式\"（干扰项如\"图形模式\"\"编程模式\"——不存在）。填空题\"计算器的四种模式是____、____、____和____\"（标准型、科学型、程序员、统计信息）。判断题\"程序员模式可以实现二进制和十进制的相互转换\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(778,439,4,2,'单元1认识计算机',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(779,778,4,3,'任务1走进计算机世界',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(780,779,4,4,'AIGC生成式人工智能','# AIGC生成式人工智能\n\n【一句话定义】\nAIGC（Artificial Intelligence Generated Content，人工智能生成内容）是利用大语言模型、扩散模型等AI技术自动生成文本、图像、音频、视频和代码等内容的技术，是人工智能从\"分析\"走向\"创造\"的重要标志。\n\n【具体说明】\n代表性应用：①大语言模型——OpenAI GPT-4/ChatGPT（对话问答、文案撰写、代码辅助）、百度文心一言（中文理解与创作）、阿里通义千问、字节豆包、DeepSeek（国产高性能推理模型）；②AI图像生成——Midjourney、Stable Diffusion（文生图）、DALL-E；③AI视频生成——Sora、Runway Gen-2、可灵AI（文生视频）；④AI编程辅助——GitHub Copilot、通义灵码（自动生成和补全代码）。\n\n实际应用场景：学生用ChatGPT辅助理解概念和梳理论文大纲；设计师用Midjourney快速生成创意草图；程序员用Copilot自动补全代码提升效率；教师用AI生成个性化练习题和教学材料。\n\n与早期AI的区别：传统AI（如语音识别、图像分类）主要是\"识别和分析\"；AIGC是\"生成和创造\"，能产出原本不存在的内容。这是人工智能技术范式的跃迁。\n\n【常见错误】\n1. 认为AIGC可以替代人类创作——AIGC是辅助工具，生成的内容需要人工审核和修改，不能直接照搬。\n2. 分不清AI对话和搜索引擎——搜索引擎是检索已有信息，ChatGPT是生成新内容，两者原理不同。\n3. 忽视AI伦理问题——用AI写作业、写论文属于学术不端；AI生成内容可能存在事实错误和偏见。\n\n【出题方向】\n常考选择题\"ChatGPT属于____技术\"（AIGC/生成式AI）。填空题\"AIGC的中文全称是____\"（人工智能生成内容）。判断题\"AIGC与传统AI的主要区别在于AIGC能够生成原本不存在的内容\"（对）。简答题\"列举2-3个AIGC的实际应用场景\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(781,779,4,4,'多媒体技术','# 多媒体技术\n\n【一句话定义】\n多媒体技术是能够同时采集、处理、编辑、存储和展示两个以上不同类型信息媒体的技术，这些信息媒体包括文本、声音、图形、图像、动画和视频等。\n\n【具体例子】\n你玩的游戏就是多媒体技术的典型应用：屏幕上有文字（对话框）、有图像（人物场景）、有声音（背景音乐和音效）、有动画（人物走动）、有视频（过场动画），五种媒体同时呈现。PowerPoint课件也是多媒体：老师插入文字说明、配一张图片、加一段讲解音频、放一个演示视频，多种媒体组合在一起让内容更生动。\n\n【常见错误】\n1. 以为\"多媒体\"就是\"很多媒体文件\"——多媒体技术的关键是\"同时处理多种类型的媒体\"，而非简单堆砌。\n2. 把多媒体等同于视频——视频只是多媒体中的一种媒体类型，多媒体还包括文本、声音、图形、图像、动画。\n3. 分不清\"图形\"和\"图像\"——图形是矢量图（由线条和数学公式描述，放大不失真），图像是位图（由像素点组成，放大会模糊）。\n\n【出题方向】\n常考选择题\"下列不属于多媒体元素的是\"（通常给出一个纯文本文件或一个单独的声音文件作为干扰项，正确答案看选项设置）。也常考填空题\"多媒体技术能够处理的媒体类型包括文本、声音、____、____、____和视频\"（图形、图像、动画）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(782,779,4,4,'智慧城市与工业互联网','# 智慧城市与工业互联网\n\n【一句话定义】\n智慧城市运用物联网、大数据、云计算和AI等技术实现城市管理的智能化（如智慧交通、智慧安防）；工业互联网将工业生产中的人、机、物全面互联，实现智能制造和高效协同。\n\n【具体说明】\n智慧城市的典型应用：①智慧交通——红绿灯根据车流量自动调节时长（如杭州城市大脑），导航App实时推送最优路线避开拥堵；②智慧安防——公共场所摄像头集成人脸识别自动预警，小区门禁刷脸进出；③智慧政务——\"一网通办\"让市民在线办理证件、缴税、挂号，不用跑政务大厅；④智慧环保——传感器实时监测空气质量和河流水质，数据自动上传到管理平台。\n\n工业互联网的典型应用：①智能工厂——生产线机器人自动协作，机械臂按订单灵活调整生产流程（如特斯拉超级工厂）；②设备预测性维护——传感器实时监测机床温度、振动，AI预判故障提前维修，减少停机损失；③数字孪生——在计算机中建立真实工厂的数字模型，先在虚拟环境中测试生产方案再实际投产；④供应链协同——从原材料采购到成品出库全流程数据打通，库存周转效率大幅提升。\n\n两者的关系：智慧城市面向城市治理和民生服务，工业互联网面向生产制造，两者共同构成\"数字中国\"的核心支柱。\n\n【常见错误】\n1. 把智慧城市理解为\"城市里有WiFi\"——智慧城市的核心是数据驱动的智能决策，不只是网络覆盖。\n2. 工业互联网和物联网搞混——工业互联网是物联网在工业领域的具体应用，是\"物联网+工业\"。\n3. 以为数字孪生是3D游戏——数字孪生是对真实物理对象的实时数字映射，用于分析和预测，不是娱乐。\n\n【出题方向】\n常考选择题\"城市红绿灯根据车流量自动调节，属于____的应用\"（智慧城市/智慧交通）。填空题\"工业互联网是____技术在工业领域的具体应用\"（物联网）。判断题\"数字孪生技术可以在虚拟环境中测试生产方案，降低实际生产风险\"（对）。简答题\"举例说明智慧城市在日常生活中的一个具体应用\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(783,779,4,4,'计算机的分类','# 计算机的分类\n\n【一句话定义】\n计算机可以从三个角度分类：按性能规模分为巨型机、大中型机、小型机、微型机和工作站；按用途分为通用计算机和专用计算机；按处理对象分为数字、模拟和混合计算机。\n\n【具体例子】\n按性能规模：学校机房的台式电脑属于微型机，也叫微机或PC；气象局用来预测天气的是巨型机；医院CT机后面连接的计算机属于工作站，专门处理医学影像。按用途：机房电脑是通用计算机，能装各种软件；ATM取款机里的计算机是专用计算机，只能做存取款相关操作。按处理对象：机房电脑处理的是数字信号（0和1），属于数字计算机；老式温度计里的指针是模拟信号，如果用计算机处理模拟信号就叫模拟计算机。\n\n【常见错误】\n1. 按性能规模分类时漏掉\"工作站\"——工作站虽然是微型机的一种，但因其专业用途在教材中单独列出。\n2. 认为笔记本不是微型机——笔记本、台式机、平板都属于微型机，只是形态不同。\n3. 混淆\"通用\"和\"专用\"——专用计算机不是性能差，而是功能单一、面向特定任务（如ATM、收银机）。\n\n【出题方向】\n常考选择题\"学校机房使用的计算机属于\"（微型机）、\"ATM取款机属于\"（专用计算机）。也常考填空题\"计算机按性能规模可分为巨型计算机、大中型计算机、小型计算机、____和____\"（微型计算机、工作站）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(784,779,4,4,'计算机的发展历程','# 计算机的发展历程\n\n【一句话定义】\n计算机从1946年诞生至今，按照所使用的核心电子元器件不同，经历了电子管、晶体管、集成电路、大规模集成电路四代发展。\n\n【具体例子】\n第一代电子管计算机（1946-1958）：像房间那么大的ENIAC，重30吨，用1.8万个电子管，每秒只能做5000次加法，耗电150千瓦。第二代晶体管计算机（1958-1964）：体积缩小到柜子大小，运算速度提高到每秒几十万次。第三代集成电路计算机（1964-1971）：像电视机大小，IBM 360是代表。第四代大规模集成电路计算机（1971至今）：就是我们用的笔记本电脑和手机，Intel的CPU一个芯片上集成了几十亿个晶体管。\n\n【常见错误】\n1. 以为计算机发展按年代划分——实际是按电子元器件划分，各代的核心区别在于硬件而非软件。\n2. 把\"集成电路\"和\"大规模集成电路\"混为一谈——第三代用中小规模集成电路，第四代用大规模和超大规模集成电路。\n3. 不知道我国计算机发展里程碑——1958年103机（我国第一台小型电子管计算机）、1964年119机（第一台大型通用计算机）、1983年\"银河\"（第一台亿次巨型机）。\n\n【出题方向】\n常考选择题\"第一代计算机使用的元器件是\"（电子管）、\"第四代计算机使用的元器件是\"（大规模集成电路）。也常考填空题\"世界上第一台电子计算机____于____年诞生\"（ENIAC，1946）。时间范围1946-1958、1958-1964等也是常考填空。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(785,779,4,4,'计算机的发展方向与新一代信息技术','# 计算机的发展方向与新一代信息技术\n\n【一句话定义】\n计算机的发展方向是巨型化、微型化、网络化、智能化和多媒体化；新一代信息技术主要包括云计算、大数据、人工智能、虚拟现实、物联网、移动互联网和区块链。\n\n【具体例子】\n巨型化：中国\"天河\"超级计算机，每秒运算次数达到百亿亿次。微型化：智能手表只有指甲盖大小的芯片，却集合了CPU、内存、通信模块。网络化：学校机房的电脑全部连到一个局域网里，可以共享打印机和文件。智能化：扫地机器人能自己规划路线、避开障碍物。多媒体化：现在的计算机能同时处理文字、声音、图片、视频。云计算：百度网盘把你的文件存在远程服务器上，换台电脑也能访问，这就是\"云\"。物联网：家里的智能灯泡能用手机App远程控制，灯泡和手机通过互联网连接，就是物联网。\n\n【常见错误】\n1. 把\"网络化\"理解为\"能上网\"——网络化是指计算机通过网络互联形成体系，是发展趋势而非功能描述。\n2. 新一代信息技术名字记不全——常考填空要求写出3-5个，建议记口诀\"云大物移智区\"（云计算、大数据、物联网、移动互联网、人工智能、区块链）。\n3. 分不清VR和AR——VR（虚拟现实）是完全虚拟的世界，AR（增强现实）是在现实世界叠加虚拟信息。\n\n【出题方向】\n常考填空题\"计算机的发展方向有巨型化、微型化、____、____和多媒体化\"（网络化、智能化）。也常考简答题\"列举3种新一代信息技术并简要说明\"。选择题\"百度网盘使用的是____技术\"（云计算）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(786,779,4,4,'计算机的应用领域','# 计算机的应用领域\n\n【一句话定义】\n计算机的应用领域非常广泛，主要包括数值计算、信息处理、计算机辅助技术、实时控制、人工智能和网络应用六大方面。\n\n【具体例子】\n数值计算：气象局用巨型计算机预测未来一周的天气，每秒进行几百亿次运算。信息处理：学校教务系统管理几千名学生的成绩、课表、考勤，就是信息处理。计算机辅助设计（CAD）：建筑设计师用计算机画楼房的三维图纸，代替手工绘图。计算机辅助教学（CAI）：你用的网课平台、在线答题系统都属于CAI。实时控制：工厂里的机械手臂按照计算机指令精准焊接，误差不到1毫米。人工智能：手机上的语音助手能听懂你说话并回答问题。\n\n【常见错误】\n1. 缩写记不住——CAI（辅助教学）、CAD（辅助设计）、CAM（辅助制造）、CAT（辅助测试）容易混淆。\n2. 把\"信息处理\"理解为\"处理信息\"的泛化说法——实际上信息处理是特指对大量数据进行采集、存储、分类、统计等操作，如办公自动化、图书管理。\n3. 分不清CAI和CAD——CAI是\"I\"（Instruction教学），CAD是\"D\"（Design设计），记首字母区别。\n\n【出题方向】\n常考选择题\"学校教务管理系统属于计算机的____应用领域\"（信息处理）、\"机械手臂自动控制属于\"（实时控制/过程控制）。也常考缩写填空\"CAI的中文含义是____\"（计算机辅助教学）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(787,779,4,4,'计算机的概念','# 计算机的概念\n\n【一句话定义】\n计算机是一种能迅速而高效的自动完成信息处理的电子设备，它能按照人们预先编好的程序，自动地对信息进行加工、处理和存储。\n\n【具体例子】\n就像学校机房里的台式机：你打开Word写作文，计算机按照Word程序的指令，自动把你敲的每个字显示在屏幕上、保存在硬盘里。整个过程不需要人工干预——你只管打字，计算机负责显示、存储、排版，一气呵成。计算器也是一种小型计算机，但它只能做算术，而机房的计算机能写作文、做表格、上网、看电影。\n\n【常见错误】\n1. 把计算器当计算机——计算器只能执行固定运算，不能运行程序，属于专用设备；计算机能执行各种程序，属于通用设备。\n2. 认为计算机只能打游戏——其实计算机的核心功能是信息处理，游戏只是众多应用软件中的一种。\n3. 认为手机不是计算机——智能手机本质上就是一台微型计算机，有CPU、内存、存储器，能运行各种App。\n\n【出题方向】\n常考判断题\"计算机只能用来计算\"（错）、选择题\"下列属于通用计算机的是\"（台式机/笔记本，而非计算器/ATM）。也常考填空题\"计算机是一种能迅速而____的自动完成信息处理的电子设备\"（填\"高效\"）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(788,779,4,4,'计算机的特点','# 计算机的特点\n\n【一句话定义】\n计算机具有运算速度快、计算精确性高、存储容量大、自动化程度高和具有逻辑判断功能五大特点。\n\n【具体例子】\n运算速度快：普通微机每秒能执行几十万条指令，算一道复杂的数学题只需要几毫秒。计算精确性高：算圆周率可以算到小数点后几十亿位不出错。存储容量大：一个1TB的硬盘能存大约25万张高清照片。自动化程度高：你设置好打印机共享后，教室任何一台电脑都能自动连接打印，不需要老师每次都去配置。逻辑判断功能：考试系统自动判断你的选择题对错，就是靠计算机的\"是非\"判断能力。\n\n【常见错误】\n1. 把\"计算精确性高\"理解为\"一定不会有错误\"——计算机的错误来自程序或输入，其本身的计算是精确的。\n2. 认为\"自动化\"等于\"智能化\"——自动化是按程序执行，智能化是能自主学习判断，两者不是一回事。\n3. 只记住五个特点的名字，说不出具体含义——考试中常要求举例说明某个特点。\n\n【出题方向】\n常考简答题\"简述计算机的五大特点\"、选择题\"计算机能自动完成处理是因为____\"（有程序控制）。也常考填空题，如\"计算机的五大特点：运算速度快、____、____、____、____\"（计算精确性高、存储容量大、自动化程度高、具有逻辑判断功能）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(789,778,4,3,'任务2认识计算机系统',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(790,789,4,4,'中央处理器CPU','# 中央处理器（CPU）\n\n【一句话定义】\nCPU是计算机的运算和控制核心，由运算器和控制器组成，主要性能指标包括主频、外频、倍频和字长。\n\n【具体例子】\nCPU就像班级的班长+学习委员的组合：运算器是学习委员，负责做具体的计算（加减乘除、逻辑判断）；控制器是班长，负责发号施令\"先做第一题、再做第二题\"。主频好比班长说话的速度——3.0GHz的CPU比2.0GHz的快，就像一个人每分钟说300个字比说200个字效率高。字长好比一次能处理多少道题——64位CPU一次能处理64位的数据，比32位的处理能力更强。主频的计算公式要记牢：主频 = 外频 × 倍频。\n\n【常见错误】\n1. 以为CPU只有\"运算\"功能——实际上CPU = 运算器 + 控制器，缺一不可。\n2. 认为主频越高CPU一定越好——还要看核心数、缓存大小、架构等因素。\n3. 记不住主频公式——主频 = 外频 × 倍频，外频是基准频率，倍频是放大系数。\n\n【出题方向】\n常考填空题\"CPU由____和____组成\"（运算器、控制器）。也常考计算题\"已知外频为100MHz，倍频为36，求主频\"（100×36=3600MHz=3.6GHz）。选择题\"下列不属于CPU性能指标的是\"（干扰项通常是\"分辨率\"\"刷新率\"等显示器指标）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(791,789,4,4,'低代码与无代码开发平台','# 低代码与无代码开发平台\n\n【一句话定义】\n低代码（Low-Code）平台通过可视化拖拽和少量编程实现应用开发，无代码（No-Code）平台完全不需要编写代码，让非专业程序员也能快速搭建软件应用。\n\n【具体说明】\n传统开发 vs 低/无代码：传统软件开发需要专业程序员用Java/Python等语言编写大量代码，开发周期长、成本高。低代码平台将常用功能封装成可视化组件，用户像搭积木一样拖拽组装，必要时用少量代码补充；无代码平台完全屏蔽代码，纯可视化操作。\n\n代表性平台：①钉钉宜搭——阿里巴巴的低代码平台，可以快速搭建请假审批、进销存管理、客户信息管理等办公应用；②腾讯微搭——基于微信生态的低代码平台，适合快速开发小程序和企业内部应用；③OutSystems——国际领先的低代码平台；④简道云——国内知名的无代码平台，非技术人员也能搭建业务系统。\n\n应用场景：学校用低代码平台快速搭建学生请假审批系统；中小企业用无代码平台搭建库存管理系统，无需雇佣专职程序员；社区用低代码工具搭建疫情防控信息登记小程序。\n\n局限性：低/无代码平台适合标准化、流程化的业务应用；对于高性能、高并发、复杂算法的系统仍需传统开发。平台本身也有技术锁定风险。\n\n【常见错误】\n1. 认为低代码会取代程序员——低代码降低了开发门槛，但复杂系统仍需专业开发，两者是互补关系。\n2. 低代码和无代码混用——低代码仍需少量编程，适合有一定技术基础的人；无代码完全不需要代码，适合纯业务人员。\n3. 认为低代码做的软件不能商用——很多低代码平台支持导出独立部署，完全可以用于生产环境。\n\n【出题方向】\n常考选择题\"低代码开发平台的核心特点是\"（可视化拖拽+少量编程）。填空题\"____平台完全不需要编写代码即可搭建应用\"（无代码/No-Code）。判断题\"低代码开发平台适合开发高并发、复杂算法的核心系统\"（错，适合标准化流程化应用）。简答题\"简述低代码平台相比传统开发的优势\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(792,789,4,4,'冯诺依曼体系结构','# 冯诺依曼体系结构\n\n【一句话定义】\n冯·诺依曼体系结构规定计算机由运算器、控制器、存储器、输入设备和输出设备五大功能部件组成，其核心思想是\"存储程序\"——程序和数据都存放在存储器中，计算机自动从存储器中取出指令执行。\n\n【具体例子】\n用做数学题来理解五大部件：输入设备（你的眼睛看到题目）→存储器（大脑记住题目和解题步骤）→运算器（大脑进行加减乘除计算）→控制器（大脑指挥先算什么后算什么）→输出设备（手写出答案）。整个流程就是你先看题（输入）、记住方法（存储）、一步步计算（运算+控制）、最后写出结果（输出）。现代计算机中，运算器和控制器被集成在一起做成了CPU。\n\n【常见错误】\n1. 五大部件名称记不全——口诀\"运控存入出\"（运算器、控制器、存储器、输入设备、输出设备）。\n2. 以为\"存储程序\"是数据存在硬盘里——实际上是指程序指令和数据一起放在存储器中，计算机按顺序自动读取执行。\n3. 漏掉\"冯·诺依曼\"这个名字——填空题常考\"____体系结构奠定了现代计算机的基本结构\"（冯·诺依曼）。\n\n【出题方向】\n常考填空题\"冯·诺依曼体系结构的五大部件是____、____、____、____和____\"。也常考简答题\"什么是存储程序原理\"。选择题\"现代计算机中，____和____被集成在一起称为CPU\"（运算器、控制器）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(793,789,4,4,'存储器与存储层次','# 存储器与存储层次\n\n【一句话定义】\n存储器是计算机中存放程序和数据的部件，分为内存（RAM/ROM）和外存（硬盘/U盘/光盘）；从快到慢、从小到大形成存储层次：寄存器→Cache→内存→外存。\n\n【具体例子】\n用教室场景类比：寄存器是老师手里的粉笔（ fastest，一次拿几根）；Cache是讲台桌面（很快，放正在用的教材）；内存（RAM）是老师的记忆（快但断电忘，关机后作业没保存就丢了）；硬盘是书包（慢但长期保存，关机后文件还在）。ROM是教室的规章制度（只读不能改，写在墙上）。外存是图书馆（很慢但能存海量书籍，U盘/移动硬盘就像你借书带走）。内存的特点是\"快贵小\"——速度快、价格高、容量相对外存小。\n\n【常见错误】\n1. 以为RAM和ROM是一个东西——RAM是随机存取存储器（可读可写，断电丢数据），ROM是只读存储器（只能读不能随意写，断电不丢数据）。\n2. 认为外存就是\"外面的存储器\"——外存是相对内存而言的辅助存储器，不是\"放在机箱外面的\"。\n3. 存储层次顺序记反——口诀\"寄C内外\"（寄存器→Cache→内存→外存），速度递减、容量递增。\n\n【出题方向】\n常考填空题\"存储器分为____和____\"（内存、外存/内部存储器、外部存储器）。也常考选择题\"断电后数据丢失的存储器是\"（RAM）、\"断电后数据不丢失的存储器是\"（ROM/硬盘/U盘）。简答题\"简述计算机存储层次结构\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(794,789,4,4,'开源软件与国产操作系统','# 开源软件与国产操作系统\n\n【一句话定义】\n开源软件是指源代码公开、允许用户自由使用修改和分发的软件（如Linux）；国产操作系统是我国自主研发的操作系统（如鸿蒙HarmonyOS、统信UOS、麒麟OS），是信息技术国产替代战略的核心组成部分。\n\n【具体说明】\n开源软件特点：源代码公开透明，任何人都可以查看、修改和重新发布；社区协作开发，全球开发者共同贡献代码；典型的开源许可证有GPL、MIT、Apache。代表性开源软件：Linux内核（操作系统核心）、Android（基于Linux的手机系统）、Firefox浏览器、LibreOffice办公套件、Python编程语言。\n\n国产操作系统现状：①鸿蒙HarmonyOS（华为）——基于微内核的分布式操作系统，支持手机、平板、智慧屏、穿戴设备、车机等多种终端，实现\"万物互联\"；②统信UOS——基于Linux内核，兼容大量国产软硬件，广泛应用于政务和企事业单位办公；③麒麟操作系统（银河麒麟/中标麒麟）——面向服务器和高安全需求场景，用于国防、金融等关键领域；④龙蜥操作系统——阿里云主导的服务器操作系统，面向云计算场景。\n\n国产替代的意义：操作系统是信息产业的\"地基\"，掌握自主知识产权可避免\"卡脖子\"风险。近年来政务系统、金融机构、关键基础设施正逐步从Windows向国产操作系统迁移。\n\n【常见错误】\n1. 认为开源软件等于免费软件——开源的核心是源代码开放和自由使用，与价格无关；很多开源软件也有商业版本。\n2. 国产操作系统就是换了皮肤的Windows——统信UOS/麒麟OS基于Linux内核开发，与Windows架构完全不同。\n3. 鸿蒙是Android的\"套壳\"——鸿蒙采用自研的微内核架构，与Android的宏内核架构有本质区别，早期版本兼容安卓是为保障应用生态过渡。\n\n【出题方向】\n常考选择题\"下列属于国产操作系统的是\"（鸿蒙HarmonyOS/统信UOS/麒麟OS）。填空题\"开源软件的源代码是____的\"（公开/开放）。判断题\"鸿蒙HarmonyOS是一款面向全场景的分布式操作系统\"（对）。简答题\"简述发展国产操作系统的意义\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(795,789,4,4,'总线','# 总线\n\n【一句话定义】\n总线是连接计算机各部件的公共通信通道，按传输内容分为数据总线（双向传输数据）、地址总线（单向传输地址）和控制总线（传输控制信号）三种。\n\n【具体例子】\n总线就像学校的走廊：数据总线是双向走廊——学生和老师在走廊里来来往往（数据双向传输）；地址总线是单向指示牌——只从教室指向办公室方向（地址从CPU指向内存或外设）；控制总线是广播系统——校长通过广播发号施令\"几点开会\"\"放学\"（控制信号指挥各部件协调工作）。三种总线缺一不可：没有数据总线，数据传不了；没有地址总线，不知道往哪传；没有控制总线，不知道什么时候传。\n\n【常见错误】\n1. 以为总线就是\"一根线\"——总线是一组信号线，不是单根线。\n2. 把三种总线的方向搞混——数据总线是双向的（唯一双向），地址总线和控制总线都是单向的。\n3. 记不住三种总线的功能——口诀\"数地控\"：数据总线传数据，地址总线传地址，控制总线传控制信号。\n\n【出题方向】\n常考填空题\"总线按传输内容可分为____、____和____\"（数据总线、地址总线、控制总线）。也常考选择题\"三种总线中，双向传输的是\"（数据总线）。判断题\"地址总线是双向传输的\"（错，是单向的）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(796,789,4,4,'程序设计语言','# 程序设计语言\n\n【一句话定义】\n程序设计语言经历了三个阶段：机器语言（0和1组成，计算机直接识别）、汇编语言（用助记符代替机器指令）、高级语言（接近自然语言，如Python、C、Java）。\n\n【具体例子】\n机器语言就像只有\"点头\"和\"摇头\"两个动作的机器人——用01010101这样的二进制直接指挥计算机，效率高但人看不懂。汇编语言把01010101换成了ADD、MOV这样的英文缩写——好比把\"点头摇头\"换成了\"是\"和\"否\"，但还是很难理解。高级语言就像用中文写指令——print(\"你好\")就是\"打印你好\"的意思，Python、C语言、Java都属于高级语言。高级语言必须经过翻译才能执行：编译方式像全文翻译（先翻译成机器语言再执行，如C语言），解释方式像同声传译（逐句翻译执行，如Python）。\n\n【常见错误】\n1. 认为高级语言\"高级\"是因为功能强——\"高级\"是指接近人类自然语言，不是指功能强弱。\n2. 把\"编译\"和\"解释\"混为一谈——编译是先全部翻译再执行（生成目标文件），解释是逐行翻译执行（不生成目标文件）。\n3. 以为机器语言已经被淘汰——实际上所有程序最终都要转换成机器语言才能执行，高级语言只是中间层。\n\n【出题方向】\n常考选择题\"计算机能直接识别的语言是\"（机器语言）。也常考填空题\"程序设计语言的发展经历了____、____和____三个阶段\"（机器语言、汇编语言、高级语言）。简答题\"简述编译方式和解释方式的区别\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(797,789,4,4,'系统软件与应用软件','# 系统软件与应用软件\n\n【一句话定义】\n软件分为系统软件和应用软件两大类：系统软件是管理和控制计算机硬件资源的软件（如操作系统），为应用软件提供运行环境；应用软件是为解决特定问题而设计的软件（如Word、QQ）。\n\n【具体例子】\n系统软件就像房子的基础设施：Windows操作系统是地基和水电管线，没有它房子不能用；驱动程序是插座开关，让硬件能被系统识别。应用软件就像房间里的家具家电：Word是书桌（写字用），QQ是电话（聊天用），Photoshop是画板（画画用）。所有应用软件都要在操作系统这个\"地基\"上才能运行。\n\n【常见错误】\n1. 把Office当成系统软件——Office是应用软件，Windows才是系统软件。\n2. 认为杀毒软件是应用软件——杀毒软件属于系统实用工具，是系统软件的范畴。\n3. 分不清驱动程序属于哪类——驱动程序是系统软件，属于系统实用工具。\n\n【出题方向】\n常考选择题\"下列属于系统软件的是\"（Windows、Linux、驱动程序，干扰项是Word、QQ、Photoshop）。也常考判断题\"操作系统是系统软件\"（对）、\"Word是应用软件\"（对）。填空题\"计算机软件分为____软件和____软件\"（系统、应用）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(798,789,4,4,'编译与解释','# 编译与解释\n\n【一句话定义】\n编译方式是先把整个高级语言源程序翻译成机器语言目标程序，然后再执行目标程序（如C语言）；解释方式是逐条翻译、逐条执行高级语言语句，不生成目标程序（如Python）。\n\n【具体例子】\n编译方式像考前全文背诵：老师把整篇英文课文翻译成中文（编译过程），你拿着中文稿直接背诵（执行），速度快但前期翻译耗时。解释方式像现场逐句翻译：老师读一句英文翻译一句中文（解释过程），不需要提前准备全文翻译稿，灵活性高但逐句翻译速度较慢。C语言、C++用编译方式；Python、JavaScript用解释方式。Java比较特殊，先编译成字节码，再在虚拟机上解释执行。\n\n【常见错误】\n1. 认为编译一定比解释快——编译后的执行确实快，但开发阶段需要反复编译比较耗时。\n2. 以为解释方式不翻译——解释方式也要翻译，只是逐条翻译逐条执行，不保存翻译结果。\n3. 分不清哪些语言用编译、哪些用解释——C/C++编译，Python/JavaScript解释，Java先编译后解释。\n\n【出题方向】\n常考选择题\"C语言采用____方式执行\"（编译）、\"Python采用____方式执行\"（解释）。也常考简答题\"简述编译方式和解释方式的区别\"。判断题\"编译方式会生成目标程序文件\"（对）、\"解释方式不生成目标程序文件\"（对）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(799,789,4,4,'计算机系统的组成','# 计算机系统的组成\n\n【一句话定义】\n一个完整的计算机系统由硬件系统和软件系统两大部分组成，硬件是计算机的物理设备，软件是运行在硬件上的程序、数据和相关文档。\n\n【具体例子】\n硬件就像人的身体：CPU是大脑，内存是短期记忆，硬盘是长期记忆，键盘鼠标是手脚（输入），显示器是嘴巴（输出）。软件就像人的知识和能力：操作系统如同你的本能（呼吸、走路），应用软件如同你学会的技能（打字、做表格）。没有软件的硬件（裸机）就像没有灵魂的身体，什么都做不了；没有硬件的软件就像幽灵，没有载体无法存在。\n\n【常见错误】\n1. 认为买了硬件就是完整系统——实际上没有安装操作系统和应用软件的电脑（裸机）无法直接使用。\n2. 把软件等同于程序——软件包括程序、数据和相关文档三部分，程序只是其中之一。\n3. 分不清\"存储器\"是硬件还是软件——硬盘、U盘、内存条都是硬件；里面存的文件、程序属于软件。\n\n【出题方向】\n常考填空题\"一个完整的计算机系统由____和____两大部分组成\"（硬件系统、软件系统）。也常考判断题\"没有安装任何软件的计算机称为裸机\"（对）、\"软件就是程序\"（错）。简答题要求简述软硬件关系。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(800,789,4,4,'输入设备','# 输入设备\n\n【一句话定义】\n输入设备是人与计算机交互的桥梁，负责将外部信息（文字、图像、声音等）转换成计算机能识别和处理的电信号输入到计算机中。\n\n【具体例子】\n键盘是最基本的输入设备，标准104键分四个区：主键盘区（打字用）、功能键区（F1-F12，F1通常打开帮助）、编辑控制键区（方向键、Delete、Insert）、数字小键盘区（Num Lock控制开关）。鼠标分三种：机械鼠标（底下有滚球，现在很少见）、光机式鼠标（滚球+光电结合）、光电鼠标（底部发光，靠感应移动，现在最常见）。扫描仪能把纸质照片变成电脑里的图片文件，就像给纸上的内容\"拍照\"存进电脑。\n\n【常见错误】\n1. 把显示器当输入设备——显示器是输出设备，不是输入设备。\n2. 认为U盘是输入设备——U盘是外存储器，既不是输入设备也不是输出设备。\n3. 键盘分区记不全——尤其分不清编辑控制键区（Delete删除、Insert插入/改写切换）和数字小键盘区。\n\n【出题方向】\n常考选择题\"下列属于输入设备的是\"（键盘、鼠标、扫描仪，干扰项通常是显示器、打印机、音箱）。也常考填空题\"键盘一般分为四个区：主键盘区、____、____和____\"（功能键区、编辑控制键区、数字小键盘区）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(801,789,4,4,'输出设备','# 输出设备\n\n【一句话定义】\n输出设备负责将计算机处理后的结果转换成人类能识别的形式（文字、图像、声音等）输出，常见的有显示器、打印机和音箱。\n\n【具体例子】\n显示器分三种：CRT（老式大屁股显示器，像老式电视机，很占地方）、LCD（液晶显示器，轻薄省电，现在最常见）、LED（发光二极管显示器，比LCD更薄更亮，色彩更好）。打印机分三种：针式打印机（用针头打色带，能复写，快递单和发票用它）、喷墨打印机（喷头喷墨水，彩色效果好但墨水贵）、激光打印机（用激光和碳粉，速度快、精度高、单页成本低，办公室最常见）。音箱不用解释，就是放声音的。\n\n【常见错误】\n1. 分不清三种打印机的特点和应用场景——针式用于复写票据，喷墨用于照片彩色，激光用于办公文档。\n2. 认为LCD和LED是完全不同的东西——LED本质上是一种特殊的LCD，只是背光源不同。\n3. 把投影仪当输入设备——投影仪是输出设备，把计算机画面投射到大屏幕上。\n\n【出题方向】\n常考选择题\"打印快递单应选用____打印机\"（针式）、\"办公室打印文档应选用____打印机\"（激光）。也常考填空题\"显示器按技术类型可分为CRT、____和____\"（LCD、LED）。简答题\"比较三种打印机的特点和适用场景\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(802,778,4,3,'任务3计算机信息编码',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(803,802,4,4,'ASCII码','# ASCII码\n\n【一句话定义】\nASCII（美国标准信息交换码）用7位二进制编码表示128个字符，占用一个字节（最高位为0），常见字符编码：大写A=65、小写a=97、数字0=48。\n\n【具体例子】\n你在键盘上敲字母A，计算机内部存的是01000001（二进制），也就是十进制的65。敲空格键存的是32，回车键是13，数字0存的是48。小写字母比大写字母大32——a是97（65+32=97）。记住这三个基准值就能推出所有字母和数字的ASCII值：大写A=65，那么B=66、C=67；小写a=97，那么b=98、c=99；数字0=48，那么1=49、2=50。\n\n【常见错误】\n1. ASCII值记成8位——标准ASCII码用7位编码（0-127），扩展ASCII码才用8位（0-255）。\n2. 大小写字母的ASCII值关系搞不清——小写a（97）= 大写A（65）+ 32。\n3. 数字字符\'0\'的ASCII值当成0——字符\'0\'的ASCII值是48，不是0。\n\n【出题方向】\n常考填空题\"大写字母A的ASCII码值是____\"（65）、\"小写字母a的ASCII码值是____\"（97）。也常考选择题\"字符\'0\'的ASCII码值是\"（48）。计算题\"已知A的ASCII是65，求D的ASCII值\"（68=65+3）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(804,802,4,4,'Unicode与UTF-8编码','# Unicode与UTF-8编码\n\n【一句话定义】\nUnicode是全球统一的字符编码标准，为世界上几乎所有文字的每个字符分配唯一的数字编号；UTF-8是Unicode的一种实现方式，用1-4个可变长度字节表示字符，是目前互联网和操作系统使用最广泛的字符编码。\n\n【具体说明】\n为什么需要Unicode：ASCII码只能表示128个英文字符（最高位为0），无法表示中文、日文、阿拉伯文等。各国各自制定编码（如中国GB2312/GBK、日本Shift-JIS），导致同一文档在不同国家打开是乱码。Unicode统一了全球字符集，目前收录超过14万个字符。\n\nUTF-8编码规则（变长编码）：①ASCII字符（0-127）用1个字节表示（与ASCII完全兼容，最高位为0）；②常用汉字、希腊字母等用3个字节表示；③生僻字符和emoji表情用4个字节表示。\n\nUTF-8的优势：与ASCII兼容（英文文档不增加体积）；变长设计节省存储空间（纯英文文本与ASCII等大）；是互联网标准（网页、JSON、XML默认使用UTF-8）；Windows/macOS/Linux现代系统默认编码。\n\n实际应用：打开网页看到源码中的`<meta charset=\"UTF-8\">`就是声明使用UTF-8编码；Python 3源码默认UTF-8，可以直接在代码中写中文；如果文件用GBK编码在UTF-8环境中打开，中文就会显示乱码。\n\n【常见错误】\n1. Unicode和UTF-8混淆——Unicode是\"字符集\"（给每个字符分配编号），UTF-8是\"编码方式\"（将编号转为字节存储），两者是标准和实现的关系。\n2. 以为UTF-8每个字符都是3个字节——UTF-8是变长的，英文字母1字节，中文3字节。\n3. GBK和UTF-8混用导致乱码——中文Windows的记事本默认保存为ANSI（GBK），在Linux/macOS上打开中文会乱码，应统一使用UTF-8。\n\n【出题方向】\n常考选择题\"目前互联网使用最广泛的字符编码是\"（UTF-8）。填空题\"UTF-8编码中，一个英文字母占____个字节，一个常用汉字占____个字节\"（1、3）。判断题\"UTF-8与ASCII编码不兼容\"（错，UTF-8的1字节编码与ASCII完全一致）。简答题\"简述UTF-8相比固定长度编码的优势\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(805,802,4,4,'二维码的编码原理与应用','# 二维码的编码原理与应用\n\n【一句话定义】\n二维码是用黑白小方块在二维平面上排列组合来存储信息的图形编码，相比一维条形码能存储更多数据（最多数千字符），且支持数字、字母、汉字、二进制等多种数据类型，还具有纠错能力（部分污损仍可识别）。\n\n【具体说明】\n二维码的结构：三个角落的回字形定位图案（让扫描设备确定二维码位置和方向）；黑白数据区（每个小方块表示二进制0或1）；格式信息和纠错码（存储编码方式和冗余校验数据）。\n\n常见二维码类型：①QR Code（最常用，日本发明，微信/支付宝扫码均采用）——正方形，三个定位角，解码速度快；②Data Matrix——体积小，适合在电子元器件上标记；③PDF417——条带形，早期用于身份证和物流。\n\n纠错级别：QR码有4级纠错（L/M/Q/H），级别越高冗余数据越多，可恢复的数据比例越大。H级即使二维码被遮挡30%仍能正常识别，这也是为什么二维码中间可以放Logo图标。\n\n应用场景：移动支付（微信/支付宝扫码付款）；健康码/行程卡（疫情期间存储个人健康信息）；电子票务（电影票/火车票/登机牌的电子凭证）；产品溯源（扫描商品二维码查看生产日期和流通信息）；WiFi快速连接（扫描自动填入密码连接网络）。\n\n【常见错误】\n1. 二维码和条形码分不清——条形码（一维码）只能水平方向存储信息，容量小（通常只存几十位数字）；二维码是二维的，水平和垂直都能存信息，容量大得多。\n2. 以为二维码只能存网址——二维码可以存文本、电话号码、WiFi配置、名片信息等多种类型。\n3. 二维码有方向要求——QR码的三个定位图案让扫描设备可以识别任意方向的二维码，倒着扫也能识别。\n\n【出题方向】\n常考选择题\"二维码相比一维条形码的优势是\"（存储容量大/支持多种数据类型/有纠错能力）。填空题\"QR码最多可恢复约____%的污损数据\"（30/H级纠错）。判断题\"二维码必须正对着扫描设备才能识别\"（错，QR码支持任意方向扫描）。简答题\"列举3个二维码在生活中的实际应用\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(806,802,4,4,'十进制二进制八进制十六进制','# 十进制、二进制、八进制、十六进制\n\n【一句话定义】\n计算机内部使用二进制（数码0和1，逢二进一），人们习惯用十进制（0-9，逢十进一），八进制（0-7，逢八进一）和十六进制（0-9+A-F，逢十六进一）常作为二进制的简化表示。\n\n【具体例子】\n十进制数15，写成二进制是1111（1×8+1×4+1×2+1×1=15），写成八进制是17（1×8+7×1=15），写成十六进制是F。计算机内部所有数据最终都是二进制，因为一个电子元件只有\"通电\"（1）和\"断电\"（0）两种状态。但二进制写起来太长——十进制的255写成二进制是11111111（8位），写成十六进制只需要FF（2位），所以程序员喜欢用十六进制简化表示。\n\n【常见错误】\n1. 二进制数越写越大不会进位——二进制1+1=10（不是2），11+1=100。\n2. 十六进制含字母就认为是\"不是数字\"——A-F是十六进法的合法数码，A就是10。\n3. 不同进制比较大小直接比——不同进制必须先转换成同一进制再比较。\n\n【出题方向】\n常考选择题\"计算机内部使用的数制是\"（二进制）。也常考填空题\"十六进制的数码包括0-9和____\"（A-F）。判断题\"八进制的基数是8\"（对）。比较题\"下列数中最大的是\"（需先统一进制再比较）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(807,802,4,4,'数制转换','# 数制转换\n\n【一句话定义】\nR进制转十进制用\"按权展开求和\"，十进制转R进制用\"除R取余\"（整数部分）和\"乘R取整\"（小数部分），二进制与八/十六进制之间可以按位分组快速转换。\n\n【具体例子】\n二进制转十进制：1011 = 1×2³ + 0×2² + 1×2¹ + 1×2⁰ = 8+0+2+1 = 11。十进制转二进制（以13为例）：13÷2=6余1→6÷2=3余0→3÷2=1余1→1÷2=0余1，从下往上读得1101。二进制转八进制：每3位一组（101 110 → 5 6 → 56）。二进制转十六进制：每4位一组（1010 1110 → A E → AE）。\n\n【常见错误】\n1. \"除R取余\"从上面往下读——必须从下往上读（最后一次除得的余数是最高位）。\n2. 二进制转八进制/十六进制时位数不够没补零——整数部分左边补零，小数部分右边补零。\n3. 不同进制之间直接转换（非十进制转非十进制）时搞混——正确做法是先转十进制，再转目标进制。\n\n【出题方向】\n常考计算题\"将二进制数101101转换为十进制\"（45）、\"将十进制数25转换为二进制\"（11001）。也常考\"二进制转八进制/十六进制\"的快速转换题。填空题\"十进制转R进制，整数部分采用____法\"（除R取余）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(808,802,4,4,'数据存储单位','# 数据存储单位\n\n【一句话定义】\n位（bit）是数据的最小单位（一个0或1），字节（Byte）是数据存储的基本单位（1Byte=8bit），字是CPU一次处理的二进制数据长度；存储容量按1024递进：1KB=1024B、1MB=1024KB、1GB=1024MB、1TB=1024GB。\n\n【具体例子】\n位就像开关——只能表示开或关（1或0）。字节就像一个宿舍房间——能住8个\"位\"同学，可以表示256种状态（2^8），足够表示一个英文字母（如A在ASCII中占1字节）。你买的U盘标着\"64GB\"，实际在计算机中显示约59.6GB，因为厂商按1000算（64×1000^3），计算机按1024算（64×1024^3）。字长就像CPU一次能吃几碗饭——32位CPU一次处理32bit（4字节），64位CPU一次处理64bit（8字节）。\n\n【常见错误】\n1. bit和Byte不分——小写b是bit（位），大写B是Byte（字节），1Byte=8bit。网速100Mbps其实是100兆位/秒，不是100兆字节/秒。\n2. 存储单位按1000算——计算机中1KB=1024B（2^10），不是1000B。只有硬盘厂商用1000。\n3. 字和字节混淆——字（Word）是CPU一次处理的数据长度（与字长有关），字节（Byte）是固定8bit。\n\n【出题方向】\n常考填空题\"1Byte=____bit\"（8）、\"1KB=____B\"（1024）。也常考选择题\"数据存储的基本单位是\"（字节/Byte）、\"数据的最小单位是\"（位/bit）。计算题\"2GB等于多少MB\"（2048）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(809,802,4,4,'汉字点阵存储计算','# 汉字点阵存储计算\n\n【一句话定义】\n汉字字形码用点阵表示，一个N×N点阵的汉字需要N×N÷8字节存储（因为1字节=8bit，每个bit表示一个点），例如24×24点阵的汉字需要72字节。\n\n【具体例子】\n一个16×16点阵的汉字：16×16=256个点，256÷8=32字节。也就是说存一个16×16的汉字需要32字节。一个24×24点阵的汉字：24×24=576个点，576÷8=72字节。一个32×32点阵的汉字：32×32=1024个点，1024÷8=128字节。字越大越清晰，但占用的空间也越多——就像照片分辨率越高越清晰但文件越大。\n\n【常见错误】\n1. 忘记除以8——直接用N×N作为答案，忘了1字节=8bit，需要N×N÷8。\n2. 计算结果单位写成bit——存储容量的单位应该是字节（Byte），不是位（bit）。\n3. 混淆不同点阵的计算——记住公式：存储字节数 = 行数 × 列数 ÷ 8。\n\n【出题方向】\n常考计算题\"一个24×24点阵的汉字需要多少字节存储\"（72字节）、\"一个32×32点阵的汉字需要多少字节存储\"（128字节）。也常考填空题\"存储一个汉字字形码，计算公式为____\"（行数×列数÷8）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(810,802,4,4,'汉字编码','# 汉字编码\n\n【一句话定义】\n汉字在计算机中需要经过多种编码转换：输入码（外码，如拼音、五笔）用于键盘输入，国标码（如GB2312）用于统一标准，机内码用于计算机内部存储，字形码用于显示和打印。\n\n【具体例子】\n以\"中\"字为例：你在键盘上打\"zhong\"（这是输入码/外码），计算机把它转换成机内码存在内存里，显示时再把机内码转换成字形码（由一个个小点组成的字模）显示在屏幕上。GB2312-80是我国1980年颁布的汉字编码国家标准，收录了6763个常用汉字。区位码是GB2312的一种表示方式：每个汉字对应一个\"区号\"和\"位号\"，比如\"啊\"字在16区01位，区位码就是1601。\n\n【常见错误】\n1. 以为汉字编码只有一种——实际上有输入码、国标码、机内码、字形码、国标交换码等多种，各有各的用途。\n2. 把区位码和机内码混为一谈——区位码是十进制表示（如1601），国标交换码是十六进制，机内码是国标交换码+8080H。\n3. 不知道GB2312收录多少汉字——GB2312收录6763个汉字和682个非汉字图形字符。\n\n【出题方向】\n常考填空题\"汉字编码国家标准GB2312-80收录了____个汉字\"（6763）。也常考简答题\"简述汉字从输入到显示需要经过哪些编码\"。选择题\"用拼音输入法输入汉字，使用的是____\"（输入码/外码）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(811,802,4,4,'进制的概念','# 进制的概念\n\n【一句话定义】\n进制即进位计数制，是利用固定的数字符号和统一的规则来计数的方法，包含三个要素：数码（数字符号）、基数（数码个数）、位权（每一位的权重）。\n\n【具体例子】\n十进制：数码0-9，基数10，位权是10的n次方（个位10^0=1，十位10^1=10，百位10^2=100）。二进制：数码只有0和1，基数2，位权是2的n次方（第1位2^0=1，第2位2^1=2，第3位2^2=4）。好比十进制是\"逢十进一\"（9之后是10），二进制是\"逢二进一\"（1之后是10）。八进制数码0-7，十六进制数码0-9加A-F。\n\n【常见错误】\n1. 把数码和基数搞混——数码是能用的数字符号，基数是数码的总个数。\n2. 认为位权从0开始还是从1开始搞不清——最右边一位的位权是基数的0次方（=1），往左依次加1。\n3. 十六进制的A-F对应的十进制值记错——A=10、B=11、C=12、D=13、E=14、F=15。\n\n【出题方向】\n常考填空题\"二进制数的数码是____和____，基数是____\"（0、1、2）。也常考选择题\"十六进制的基数是\"（16）。简答题\"简述进制的三要素\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(812,778,4,3,'任务4认识信息安全与知识产权',NULL,0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(813,812,4,4,'个人信息保护法与数据安全法','# 《个人信息保护法》与《数据安全法》\n\n【一句话定义】\n《个人信息保护法》（2021年11月1日施行）是我国首部专门保护个人信息权益的法律，规范了个人信息处理活动；《数据安全法》（2021年9月1日施行）是我国数据安全领域的基础性法律，确立了数据分类分级保护制度。\n\n【具体说明】\n《个人信息保护法》核心要点：①知情同意原则——处理个人信息应事先充分告知并取得个人同意，不得强制索要不必要的权限；②最小必要原则——App只能收集提供服务所必需的最少个人信息；③敏感个人信息——生物识别（人脸/指纹）、宗教信仰、医疗健康、金融账户、行踪轨迹等信息需单独同意、加强保护；④个人权利——个人有权查阅、复制、更正、删除自己的信息，有权拒绝个性化推送；⑤违法处罚——违法处理个人信息最高可处5000万元罚款或上一年度营业额5%的罚款。\n\n《数据安全法》核心要点：①数据分类分级——国家建立数据分类分级保护制度，关系国家安全的数据实行更严格管理；②数据安全审查——处理特定数据应申报安全审查；③重要数据出境——重要数据出境需经安全评估；④政务数据安全——国家机关收集个人信息应保密，不得泄露或非法向他人提供。\n\n与知识产权保护的关系：知识产权法保护的是智力创造成果（软件著作权、专利、商标）；《个人信息保护法》和《数据安全法》保护的是公民个人信息权益和国家数据安全。三者共同构成我国数字经济时代的法律保障体系。\n\n【常见错误】\n1. 两部法律搞混——《个人信息保护法》侧重保护公民个人权益，《数据安全法》侧重国家层面的数据安全管理。\n2. 以为法律只约束企业——《数据安全法》也规范国家机关的数据处理行为，政府部门同样受约束。\n3. 认为不同意隐私政策就不能用App——《个保法》规定不得以个人不同意处理其个人信息或撤回同意为由拒绝提供产品或服务（处理个人信息属于提供产品或服务所必需的除外）。\n\n【出题方向】\n常考选择题\"《个人信息保护法》自____起施行\"（2021年11月1日）。填空题\"处理个人信息应当遵循____、____、必要和诚信原则\"（合法、正当）。判断题\"《个人信息保护法》规定，APP不得强制索取与服务无关的个人信息权限\"（对）。简答题\"简述《个人信息保护法》中的\'最小必要\'原则\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(814,812,4,4,'信息安全','# 信息安全\n\n【一句话定义】\n信息安全是指保护计算机系统中的硬件、软件和数据资源，使其不因偶然或恶意的原因而遭到破坏、更改或泄露，确保系统能够连续、正常运行。\n\n【具体例子】\n学校机房的电脑设了开机密码，这就是最基本的信息安全保护——防止别人用你的账号做坏事。网上银行用了HTTPS加密，这样你输入的密码在传输过程中不会被坏人截获看到。保障信息安全的四大技术：防火墙技术（像学校门卫，管进出流量）、数据加密技术（把明文变成密文，外人看不懂）、身份认证技术（查学生证确认你是谁）、入侵检测技术（监控网络中有没有可疑行为）。\n\n【常见错误】\n1. 把信息安全等同于\"安装杀毒软件\"——杀毒只是信息安全的一部分，还包括硬件保护、数据备份、访问控制等。\n2. 认为\"设置了密码就安全了\"——弱密码（如123456）很容易被破解，还要定期更换。\n3. 混淆信息安全的四大技术——记住口诀\"火加身入\"（防火墙、加密、身份认证、入侵检测）。\n\n【出题方向】\n常考填空题\"保障信息安全的主要技术有____、____、____和____\"（防火墙技术、数据加密技术、身份认证技术、入侵检测技术）。也常考简答题\"简述信息安全的含义\"或\"列举信息安全的主要技术\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(815,812,4,4,'入侵检测技术','# 入侵检测技术\n\n【一句话定义】\n入侵检测技术是对计算机和网络资源上的恶意使用行为进行识别和响应的安全技术，通过实时监测网络活动，发现未经授权的访问或攻击行为并及时报警。\n\n【具体例子】\n入侵检测系统就像学校的监控摄像头和保安巡逻：摄像头24小时盯着走廊（实时监控网络流量），发现有陌生人翻墙进来（检测到异常流量）立刻通过对讲机报告保安室（报警）。入侵检测分为主机入侵检测（HIDS，守在单台电脑上，像教室里的摄像头）和网络入侵检测（NIDS，守在整个网络上，像校门口的监控）。\n\n【常见错误】\n1. 把入侵检测和防火墙混为一谈——防火墙是\"守门员\"（阻止 unauthorized 访问），入侵检测是\"监控摄像头\"（发现可疑行为并报警），两者互补。\n2. 认为有了防火墙就不需要入侵检测——防火墙只管边界，内部的恶意行为需要入侵检测来发现。\n3. 以为入侵检测能阻止攻击——入侵检测主要是\"发现\"和\"报警\"，不是\"阻止\"（阻止需要防火墙等配合）。\n\n【出题方向】\n常考选择题\"入侵检测系统的主要功能是\"（检测和报警，不是阻止）。也常考判断题\"入侵检测技术可以完全阻止网络攻击\"（错）。简答题\"简述入侵检测技术与防火墙的区别\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(816,812,4,4,'数据加密技术','# 数据加密技术\n\n【一句话定义】\n数据加密技术是将可读的数据（明文）通过加密算法转换成不可读的形式（密文），只有拥有正确密钥的人才能解密还原，从而保护数据在传输和存储过程中不被窃取。\n\n【具体例子】\n就像你和同桌发明的\"暗号\"：把每个字母往后移3位，A变成D、B变成E（这就是加密）。别人看到\"D\"不知道是A，只有知道\"移3位\"这个密钥的你们才能还原。真正的加密更复杂：对称加密用同一把钥匙加密解密（像同一把钥匙锁门和开门），速度快但密钥分发困难；非对称加密用两把不同的钥匙（公钥加密、私钥解密），像信箱——任何人都能投信（公钥），但只有你有钥匙能打开（私钥）。\n\n【常见错误】\n1. 把加密和压缩搞混——加密是让数据不可读，压缩是让数据变小，目的不同。\n2. 认为加密后数据绝对安全——没有绝对的安全，只是提高破解难度。\n3. 分不清对称加密和非对称加密——对称加密：一把钥匙；非对称加密：两把钥匙（公钥和私钥）。\n\n【出题方向】\n常考选择题\"对称加密和非对称加密的主要区别是\"（密钥数量不同）。也常考填空题\"数据加密的目的是将____转换成____\"（明文、密文）。简答题\"简述对称加密和非对称加密的区别\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(817,812,4,4,'知识产权保护','# 知识产权保护\n\n【一句话定义】\n计算机软件是享有著作权保护的知识产品，受法律保护；使用盗版软件不仅违法，还可能因软件被植入恶意程序而导致系统崩溃或信息泄露。\n\n【具体例子】\n你写的作文别人不能抄，软件开发公司写的程序也一样——别人不能随意复制和分发。微软的Windows操作系统一套正版几百元，盗版只要几元——但盗版可能被植入木马病毒（破解者在里面加了后门程序），你用了之后网银密码、QQ密码都可能被盗。这就是\"贪小便宜吃大亏\"。学校机房应该使用正版软件，既是对知识产权的尊重，也是对教学安全的保障。\n\n【常见错误】\n1. 认为用盗版软件\"没什么大不了\"——盗版是违法行为，损害了软件开发者的利益。\n2. 觉得正版太贵不划算——正版有保障（技术支持、安全更新），盗版有安全风险。\n3. 混淆\"免费软件\"和\"盗版软件\"——免费软件（如Firefox）是作者自愿免费，盗版软件是未经授权的复制。\n\n【出题方向】\n常考判断题\"使用盗版软件不仅违法，还可能带来安全风险\"（对）。也常考填空题\"计算机软件是享有____保护的知识产品\"（著作权）。简答题\"简述使用盗版软件的危害\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(818,812,4,4,'社会工程学攻击与防范','# 社会工程学攻击与防范\n\n【一句话定义】\n社会工程学攻击是利用人性的弱点（如信任、恐惧、贪婪）而非技术漏洞来骗取敏感信息（密码、验证码、银行卡号）的攻击方式，常见的有钓鱼邮件、电信诈骗、假冒客服等，是现实中比病毒更普遍的安全威胁。\n\n【具体说明】\n常见攻击手法：①钓鱼邮件——伪装成银行、学校或公司发送邮件，内含虚假链接诱导输入账号密码；②电信诈骗——冒充公检法、快递客服、领导等打电话，以\"涉嫌洗钱\"\"快递丢失赔偿\"等话术骗取转账；③假冒WiFi——在公共场所搭建免费WiFi热点，截获连接者的上网数据；④伪装的U盘——在停车场/电梯口丢弃植入恶意程序的U盘，引诱好奇者拾取插入电脑；⑤冒充技术支持——打电话谎称\"你的电脑有病毒\"，诱导安装远程控制软件。\n\n防范措施：①不点击来历不明的链接——收到短信/邮件中的链接，先核实发件人身份，不直接点击；②不随意连接公共WiFi——尤其是不设密码的WiFi，避免在公共WiFi下进行网银操作；③验证码就是密码——任何情况下都不要告诉别人短信验证码；④来电核实身份——接到\"领导\"\"客服\"电话要求转账，挂断后用已知号码回拨核实；⑤U盘先杀毒再打开——外来U盘插入电脑前先用杀毒软件扫描。\n\n技术防范手段：开启邮箱的垃圾邮件过滤；安装并定期更新杀毒软件；操作系统和浏览器保持最新版本修补安全漏洞。\n\n【常见错误】\n1. 以为安装了杀毒软件就安全了——社会工程学攻击利用的是人的弱点，杀毒软件无法防御人的判断失误。\n2. 认为\"我不会被骗\"——社会工程学攻击针对不同人群定制话术，任何人都可能成为目标。\n3. 帮\"朋友\"解封账号——骗子盗号后冒充朋友发消息求助，应先通过其他渠道（如打电话）确认对方身份。\n\n【出题方向】\n常考选择题\"以下属于社会工程学攻击的是\"（钓鱼邮件/电信诈骗/假冒客服）。填空题\"社会工程学攻击利用的是____而非技术漏洞\"（人性弱点/人的信任/心理弱点）。判断题\"不点击来历不明的链接是防范社会工程学攻击的有效措施\"（对）。简答题\"列举2种社会工程学攻击的常见手法及对应的防范方法\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(819,812,4,4,'计算机病毒','# 计算机病毒\n\n【一句话定义】\n计算机病毒是能够侵入计算机系统、对系统起破坏作用并具有自我复制能力的一段程序代码，主要特征有传染性（最基本特征）、潜伏性、隐蔽性、破坏性和可触发性。\n\n【具体例子】\n病毒就像流感：传染性（从一个文件传到另一个文件，是病毒与正常程序的本质区别）、潜伏性（藏在系统里暂时不发作，像潜伏期）、隐蔽性（伪装成正常文件让你发现不了）、破坏性（发作后删除文件、偷密码、让电脑变慢）、可触发性（满足条件才发作，比如特定日期）。常见类型：引导型（感染启动扇区）、文件型（感染.exe文件）、宏病毒（感染Word/Excel文档）。防治措施：装杀毒软件和防火墙、不打来历不明的邮件和链接、定期备份、及时打补丁。\n\n【常见错误】\n1. 认为病毒只会破坏文件——病毒还能窃取信息、控制电脑、占用资源。\n2. 以为不联网就不会中毒——U盘传播也是重要途径，机房公用U盘很容易交叉感染。\n3. 认为安装了杀毒软件就万事大吉——新病毒不断出现，需要及时更新病毒库。\n\n【出题方向】\n常考填空题\"计算机病毒最基本的特征是____\"（传染性）。也常考选择题\"下列不属于计算机病毒特征的是\"（干扰项通常是\"可修复性\"等）。简答题\"简述计算机病毒的主要特征和防治措施\"。判断题\"计算机病毒只会通过网络传播\"（错，还可通过U盘等移动设备传播）。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(820,812,4,4,'身份认证技术','# 身份认证技术\n\n【一句话定义】\n身份认证技术是通过验证用户的身份信息来确认其真实身份的过程，常见方式有用户名+密码、数字证书、生物特征识别（指纹、人脸）等。\n\n【具体例子】\n登录QQ输入账号密码就是最基本的身份认证——系统核对你输入的密码和数据库里存的密码是否一致。去银行办网银会给你U盾（数字证书），里面存有你的唯一身份标识，比单纯密码更安全。现在手机支持指纹解锁和人脸识别，属于生物特征认证——你的指纹和脸就是你的\"天然密码\"，很难被伪造。\n\n【常见错误】\n1. 把身份认证和访问控制混为一谈——身份认证是\"证明你是谁\"，访问控制是\"你能做什么\"，是两个不同的步骤。\n2. 认为密码越长越安全——密码安全取决于复杂度和随机性，纯数字密码即使很长也不如混合密码安全。\n3. 所有账户用同一个密码——一个账户泄露全部账户都危险。\n\n【出题方向】\n常考选择题\"下列属于生物特征认证的是\"（指纹识别、人脸识别，干扰项可能是用户名密码、数字证书）。也常考填空题\"身份认证的目的是____\"（核查用户的真实身份）。简答题\"列举三种身份认证方式\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50'),(821,812,4,4,'防火墙技术','# 防火墙技术\n\n【一句话定义】\n防火墙是一种位于内部网络和外部网络之间的网络安全设备，通过预设的安全策略监控和过滤进出网络的数据流量，防止未经授权的访问和恶意攻击。\n\n【具体例子】\n防火墙就像学校的大门和门卫系统：学生（内部网络）可以自由进出校门（允许内部访问外部），但陌生人（外部网络）进校门必须登记并得到允许（过滤外部访问）。门卫手里有一份\"黑名单\"（防火墙规则），名单上的人一律不许进。Windows自带的防火墙就是一道软件\"门\"，默认会阻止不信任的程序连接网络，保护你的电脑不被外部攻击。\n\n【常见错误】\n1. 认为防火墙能防所有病毒——防火墙只管网络流量，不管文件里的病毒，杀毒软件和防火墙功能不同。\n2. 以为防火墙只是硬件——防火墙有硬件防火墙（企业用）和软件防火墙（个人电脑用）。\n3. 为了省事关闭防火墙——关闭防火墙等于敞开大门，极易受到网络攻击。\n\n【出题方向】\n常考选择题\"防火墙的主要作用是\"（监控进出网络流量、防止非法访问）。也常考判断题\"防火墙能防止所有计算机病毒\"（错）。简答题\"简述防火墙的功能\"。\n',0,1,'2026-05-22 07:17:50','2026-05-22 07:17:50');
