INSERT INTO `tasks` VALUES (1,1,4,'简单操作Windows实训方案','◆ 一、实训目标\n通过本次实训，学生能够独立完成Windows桌面环境的基本设置，包括鼠标操作、窗口管理、任务栏自定义以及文件和文件夹的创建与命名。\n\n◆ 二、实训环境与工具\n| 类别 | 内容 |\n|------|------|\n| 软件/工具 | Windows 7 或 Windows 10 操作系统 |\n| 硬件设备 | 计算机、鼠标、键盘 |\n\n◆ 三、实训任务\n【任务1】Windows基础操作热身\n【任务描述】：通过鼠标和键盘，完成打开窗口、切换窗口、关闭窗口等基本操作，并学会使用帮助功能。\n【操作步骤】：\n1. 打开计算机窗口\n2. 切换窗口\n3. 关闭窗口\n【预期结果】：能独立完成窗口基本操作\n【检查点】：检查窗口是否正确打开和关闭\n\n【任务2】任务栏与文件管理\n【任务描述】：自定义任务栏设置，创建文件夹和文件\n【操作步骤】：\n1. 解锁和锁定任务栏\n2. 在D盘创建文件夹\n3. 创建文本文件并命名\n【预期结果】：能完成文件管理基本操作\n【检查点】：文件夹和文件是否正确创建\n\n【任务3】综合练习\n【任务描述】：综合运用所学Windows操作技能完成文件整理\n【操作步骤】：\n1. 创建练习文件\n2. 按类别整理到不同文件夹\n3. 验证整理结果\n【预期结果】：独立完成文件整理\n【检查点】：文件整理是否按类别分好\n\n◆ 四、评分标准\n| 评分项 | 分值 | 评分标准 |\n|--------|------|----------|\n| 任务完成度 | 40 | 所有步骤按预期执行 |\n| 操作规范性 | 30 | 符合操作规范 |\n| 成果质量 | 30 | 输出符合要求 |\n\n◆ 五、常见问题与排错指南\n1. 窗口无法切换：检查是否最小化到任务栏\n2. 文件无法重命名：确认文件未被其他程序占用','',2,1,100.0,'POINT_100',NULL,'PRACTICE','CLASS',1,'CLASS','2026-05-23 00:00:00','ONGOING',NULL,0,0,1,NULL,0,NULL,NULL,'2026-05-22 08:49:11','2026-05-22 14:24:49','NOT_SUBMITTED',1,0,0,NULL,0,NULL,NULL,NULL,NULL);
/*!40000 ALTER TABLE `tasks` ENABLE KEYS */;
UNLOCK TABLES;

